function unlockCardForPlayer(id, source){
  if(!id || !CARD_DEFS_BASELINE[id] && !liveCards[id]) return false; // not a real card id
  // The Nest (2026-09-27, item 10): every real grant now also adds an owned COPY, even when the
  // defId is already unlocked — see grantCardCopy's own comment. This runs before the
  // already-unlocked early-return below so a 2nd/3rd/4th pull of the same card still counts as
  // owning more copies, not a silent no-op.
  grantCardCopy(id);
  noteSighted([id]); // 2026-10-02: getting a card counts as seeing it (Hidden -> Discovered)
  if(myUnlockedCardIds.has(id)) return false; // already unlocked -- nothing to do, additive-only
  myUnlockedCardIds.add(id);
  saveUnlockedCardIds();
  const d = getCardDefs()[id] || {};
  logTxn({action:'unlocked', cardId:id, cardName:d.name, icon:d.icon, source: CARD_UNLOCK_SOURCES[source]||source||'Unknown', before:null, after:null});
  return true;
}
// "Received but still locked" (2026-09-25, per explicit request: "I think maybe there are times
// you would be able to receive the card, but it's still locked. Such as trading. (not
// implemented.)"): a card copy arriving through a future trade would need to exist somewhere
// distinct from "owned and playable" (myUnlockedCardIds) — this Set is that place, deliberately
// built now so the data model is ready, exactly like the request frames it ("available but not
// wired"). Nothing adds to this yet (there is no trading feature — see the Shop's greyed-out
// "🏳️ Flea Market" button), and nothing reads it either; getCardDefs()'s locked-overlay logic
// above intentionally does NOT consult it, since a card in here is specifically meant to stay
// locked until some other, also-not-yet-built action (accepting the trade? a separate unlock
// step?) promotes it into myUnlockedCardIds via unlockCardForPlayer() above. Persisted the same
// load/save-pair shape as myUnlockedCardIds so wiring it up later is a drop-in, not a redesign.
function loadLockedReceivedCardIds(){
  try{ const raw = localStorage.getItem('bramblewood_arena_locked_received'); if(raw){ const arr = JSON.parse(raw); if(Array.isArray(arr)) return new Set(arr); } }catch(e){}
  return new Set();
}
let myLockedReceivedCardIds = loadLockedReceivedCardIds();
function saveLockedReceivedCardIds(){ try{ localStorage.setItem('bramblewood_arena_locked_received', JSON.stringify(Array.from(myLockedReceivedCardIds))); }catch(e){} }
// receiveLockedCard() is the future trade-receive entry point this data model is built for — not
// called from anywhere yet (there is no trading feature), kept here so it's a one-line hookup
// once one exists rather than something to design from scratch later.
function receiveLockedCard(id, source){
  if(!id || myUnlockedCardIds.has(id) || myLockedReceivedCardIds.has(id)) return false;
  noteSighted([id]);
  myLockedReceivedCardIds.add(id);
  saveLockedReceivedCardIds();
  const d = getCardDefs()[id] || {};
  logTxn({action:'receivedLocked', cardId:id, cardName:d.name, icon:d.icon, source: source||'Trade', before:null, after:null});
  return true;
}
// The Nest (2026-09-27, item 10, per explicit request: "now we need to build the Nest or Repo —
// containing cards you OWN. Each card is fungible. As in, you could have 5 Bee Knights, and only
// 1 is foil, maybe... I think individual for now"). Until now myUnlockedCardIds only ever tracked
// a boolean "can this defId be played" flag — there was no concept of owning more than one copy
// of a card, so a second pull of an already-unlocked card was indistinguishable from the first.
// myCardCopies is the new per-COPY ownership record: {[defId]: [{foil}, {foil}, ...]}, one array
// entry per owned physical copy, each carrying its OWN splash-effect state — "individual for
// now", the option the request explicitly landed on over the alternative (unlocking a splash
// effect once for every copy of that card at once). Same load/save-pair shape as
// myUnlockedCardIds/myLockedReceivedCardIds above, so it plugs into the same patterns.
function loadCardCopies(){
  try{ const raw = localStorage.getItem('bramblewood_arena_card_copies'); if(raw){ const obj = JSON.parse(raw); if(obj && typeof obj==='object') return obj; } }catch(e){}
  return {};
}
let myCardCopies = loadCardCopies();
function saveCardCopies(){ try{ localStorage.setItem('bramblewood_arena_card_copies', JSON.stringify(myCardCopies)); }catch(e){} soonCheckMilestones(); }
// One-time migration (2026-09-27): every card this player unlocked BEFORE the Nest existed has
// no copy record at all yet — without this, those cards would show as owned x0 in the new
// screen despite being real, played, unlocked cards. Seeds exactly 1 non-foil copy for any
// already-unlocked id with zero copies on record; a no-op on every later load once it's run
// once (idempotent — checks copies.length, not a one-shot flag), and never touches an id that
// already has copies from real grants.
function migrateCardCopiesFromUnlocks(){
  let changed = false;
  myUnlockedCardIds.forEach(id=>{
    if(!myCardCopies[id] || !myCardCopies[id].length){ myCardCopies[id] = [{foil:false}]; changed = true; }
  });
  if(changed) saveCardCopies();
}
migrateCardCopiesFromUnlocks();
// grantCardCopy: the ONE place a new owned copy is ever added — always pushes, even if this
// defId is already unlocked (that's the whole point: a 2nd/3rd/4th pull of the same card grants
// an actual additional copy now, instead of the pre-Nest behavior where unlockCardForPlayer's
// duplicate check silently no-opped every pull after the first). New copies start non-foil;
// see toggleCardCopyFoil() for how a specific copy's foil state changes later.
function grantCardCopy(id){
  if(!id) return;
  if(!myCardCopies[id]) myCardCopies[id] = [];
  myCardCopies[id].push({foil:false});
  saveCardCopies();
}
// Toggles ONE specific owned copy's foil state (the Nest screen's per-copy chip click) — never
// touches any other copy of the same card, per "individual for now".
function toggleCardCopyFoil(id, copyIdx){
  const copies = myCardCopies[id];
  if(!copies || !copies[copyIdx]) return;
  copies[copyIdx].foil = !copies[copyIdx].foil;
  saveCardCopies();
}
