const DIALOGUE_FLAGS_KEY = 'bramblewood_dialogue_flags_v1';
let DIALOGUE_REPLY_MS = 30000, DIALOGUE_LINE_MS = 3600; // let: tests shorten them
function loadDialogueFlags(){ try{ return JSON.parse(localStorage.getItem(DIALOGUE_FLAGS_KEY)||'{}') || {}; }catch(e){ return {}; } }
function setDialogueFlag(k, v){ const f = loadDialogueFlags(); f[k] = v; try{ localStorage.setItem(DIALOGUE_FLAGS_KEY, JSON.stringify(f)); }catch(e){} }
let dialogueQueue = Promise.resolve();
function dialogueDock(){
  let dock = document.getElementById('dialogueDock');
  if(!dock){ dock = document.createElement('div'); dock.id = 'dialogueDock'; dock.className = 'dialogue-dock'; dock.setAttribute('aria-live','polite'); document.body.appendChild(dock); }
  return dock;
}
function speakerPortraitHTML(sp){
  const d = sp.card && getCardDefs()[sp.card];
  return d && d.art ? `<img class="dlg-portrait" src="${d.art}" alt="">` : `<span class="dlg-portrait dlg-portrait-ico">${sp.icon||'💬'}</span>`;
}
// Plays a script; resolves to {replies:[...]} — the labels you picked ('…' for a timeout).
// Queued, so two scripts never talk over each other. `once` remembers it was seen.
function playDialogue(id, opts){
  opts = opts || {};
  const script = DIALOGUES[id]; if(!script) return Promise.resolve(null);
  if(opts.once && loadDialogueFlags()['seen:'+id]) return Promise.resolve(null);
  const run = async ()=>{
    if(opts.once) setDialogueFlag('seen:'+id, true);
    const dock = dialogueDock();
    const replies = [];
    const byLabel = {}; script.lines.forEach((l,i)=>{ if(l.label) byLabel[l.label] = i; });
    let i = 0, guard = 0;
    while(i < script.lines.length && guard++ < 50){
      const line = script.lines[i];
      const sp = DIALOGUE_SPEAKERS[line.who] || {name: line.who, icon:'💬'};
      const b = document.createElement('div');
      b.className = 'dlg-line' + (line.options ? ' dlg-to-you' : '');
      b.innerHTML = `${speakerPortraitHTML(sp)}<div class="dlg-body"><div class="dlg-name">${escapeHtml(sp.name)}</div><div class="dlg-text">${escapeHtml(line.text)}</div></div>`;
      dock.appendChild(b);
      while(dock.children.length > 3) dock.firstElementChild.remove();
      if(hasGsap()) gsap.from(b, {x: -40, opacity: 0, duration: .35, ease: 'power3.out'});
      let next = i+1;
      if(line.options){
        const choice = await new Promise(resolve=>{
          const row = document.createElement('div'); row.className = 'dlg-replies';
          row.innerHTML = line.options.map((o,k)=> `<button type="button" class="btn small dlg-reply" data-k="${k}">${escapeHtml(o.label)}</button>`).join('') + `<span class="dlg-timer" title="Answer within 30 seconds"><svg viewBox="0 0 36 36"><circle cx="18" cy="18" r="15"></circle></svg><b>30</b></span>`;
          b.querySelector('.dlg-body').appendChild(row);
          const ring = row.querySelector('circle'), num = row.querySelector('.dlg-timer b');
          const started = Date.now();
          const tick = setInterval(()=>{ const left = Math.max(0, DIALOGUE_REPLY_MS - (Date.now()-started)); num.textContent = Math.ceil(left/1000); ring.style.strokeDashoffset = String(94.2 * (1 - left/DIALOGUE_REPLY_MS)); if(!left){ clearInterval(tick); resolve(null); } }, 250);
          row.querySelectorAll('.dlg-reply').forEach(btn=> btn.onclick = ()=>{ clearInterval(tick); resolve(line.options[+btn.dataset.k]); });
        });
        const reply = document.createElement('div');
        reply.className = 'dlg-line dlg-mine';
        reply.innerHTML = `<div class="dlg-body"><div class="dlg-name">You</div><div class="dlg-text">${escapeHtml(choice ? choice.label : '…')}</div></div>`;
        b.querySelector('.dlg-replies').remove();
        dock.appendChild(reply);
        while(dock.children.length > 3) dock.firstElementChild.remove();
        replies.push(choice ? choice.label : '…');
        const target = choice ? choice.goto : line.silent;
        if(target && byLabel[target]!=null) next = byLabel[target];
        await sleep(900);
      } else {
        await sleep(Math.max(2200, Math.min(6000, DIALOGUE_LINE_MS + line.text.length*25)));
        if(line.goto && byLabel[line.goto]!=null) next = byLabel[line.goto];
      }
      i = next;
    }
    await sleep(1800);
    Array.from(dock.children).forEach(el=>{ if(hasGsap()) gsap.to(el, {opacity:0, x:-30, duration:.3, onComplete:()=> el.remove()}); else el.remove(); });
    if(opts.onDone) try{ opts.onDone(replies); }catch(e){}
    return {replies};
  };
  const p = dialogueQueue.then(run, run);
  dialogueQueue = p.catch(()=>{});
  return p;
}
// ---- Conquest-first onboarding (2026-10-03, explicit: "When you finish the tutorial, the leaves
// push apart, and your map is revealed. At the start, there isn't even the map tab, just this small
// map and possibility. No shop, no deck edit. But as you conquer, you spot 'game interactibles' as
// icons on the map. Clicking them unlocks a small speech, then right into it."). Each feature lives
// behind a spot on the map; a spot appears once its map is open and its `after` node is cleared.
// Clicking it unlocks the feature, starts its dialogue (non-blocking) and goes straight there.
// Players who were already past the tutorial when this shipped keep everything their progress has
// earned (migrateFeatureUnlocks). Admin → "Unlock all features" / "Replay onboarding".
const UNLOCKS_KEY = 'bramblewood_unlocks_v1';
const FEATURE_SPOTS = [
  {key:'deck', icon:'⛺', name:'Armoury Tent', map:'m1', after:'1-1', dialogue:'unlock_deck', tabs:['deck','codex'], go:()=> switchTab('deck')},
  {key:'nest', icon:'🪺', name:'Old Nest', map:'m1', after:'1-2', dialogue:'unlock_nest', tabs:['nest'], go:()=> switchTab('nest')},
  {key:'quests', icon:'📜', name:'Notice Board', map:'m1', after:'1-3', dialogue:'unlock_quests', tabs:['quests'], go:()=> openQuestsModal()},
  {key:'arena', icon:'🏟️', name:'The Arena', map:'m2', after:null, dialogue:'unlock_arena', tabs:['arena','ranking','friends','guild'], go:()=>{ playSubTab = 'arena'; switchTab('play'); }},
  {key:'shop', icon:'🛒', name:'Traveller’s Cart', map:'m3', after:null, dialogue:'unlock_shop', tabs:['shop'], go:()=> switchTab('shop')},
  {key:'autobattle', icon:'🧩', name:'Whisper’s Game', map:'m3', after:'3-2', dialogue:'unlock_autobattler', tabs:['autobattle'], go:()=>{ playSubTab = 'autobattle'; switchTab('play'); }},
  {key:'raid', icon:'🐲', name:'Raid Banner', map:'m4', after:null, dialogue:'unlock_raid', tabs:['raid'], go:()=>{ playSubTab = 'raid'; switchTab('play'); }},
];
function loadUnlocks(){
  try{ const u = JSON.parse(localStorage.getItem(UNLOCKS_KEY)||'null'); if(u && u.unlocked) return u; }catch(e){}
  return migrateFeatureUnlocks();
}
function saveUnlocks(u){ try{ localStorage.setItem(UNLOCKS_KEY, JSON.stringify(u)); }catch(e){} }
function spotAvailable(spot, progress){
  progress = progress || loadConquestProgress();
  const map = CONQUEST_MAPS.find(m=> m.id===spot.map); if(!map || !isMapUnlocked(map, progress)) return false;
  return !spot.after || (progress.completed||[]).includes(conquestNodeId(spot.map, spot.after));
}
// First run of this build for an existing player: grant whatever their progress has already reached.
function migrateFeatureUnlocks(){
  const u = {unlocked:{}, migrated: Date.now()};
  if(loadTutorialDone()){ const pr = loadConquestProgress(); FEATURE_SPOTS.forEach(sp=>{ if(spotAvailable(sp, pr)) u.unlocked[sp.key] = true; }); }
  saveUnlocks(u);
  return u;
}
function featureUnlocked(key){ return !!loadUnlocks().unlocked[key]; }
// Is a tab/sub-tab/feature name open? Anything no spot owns is always open.
function tabOpen(tab){ const sp = FEATURE_SPOTS.find(x=> x.tabs.includes(tab)); return !sp || featureUnlocked(sp.key); }
function unlockFeature(key){ const u = loadUnlocks() || {unlocked:{}}; u.unlocked[key] = true; saveUnlocks(u); }
function activateSpot(spot){
  const first = !featureUnlocked(spot.key);
  if(first){ unlockFeature(spot.key); try{ if(SoundKit.unlock) SoundKit.unlock(); }catch(e){} showToast(`${spot.icon} ${spot.name} — unlocked!`, 'ok'); playDialogue(spot.dialogue, {once:true}); }
  spot.go();
}
// Maps that have a generated pixel-art background baked into the build (see assemble_arena.py).
const MAP_ART_IDS = new Set(["m1","m2","m3","m4","m5","m6","m7","m8","m9","m10","m11"]);
function mapSpotsHTML(map, positions, progress){
  return FEATURE_SPOTS.filter(sp=> sp.map===map.id && spotAvailable(sp, progress)).map(sp=>{
    const idx = sp.after ? map.nodes.findIndex(n=> n.key===sp.after) : map.nodes.findIndex(n=> n.kind!=='tutorial');
    const base = positions[Math.max(0, idx)] || {x:50, y:50};
    const x = Math.max(4, Math.min(96, base.x + (sp.after ? 5 : -6))), y = Math.max(8, Math.min(92, base.y + (sp.after ? -18 : 14)));
    const open = featureUnlocked(sp.key);
    return `<button type="button" class="map-spot ${open?'is-open':'is-new'}" data-spot="${sp.key}" style="left:${x}%; top:${y}%;" title="${escapeAttr(sp.name + (open ? '' : ' — something new!'))}" aria-label="${escapeAttr(sp.name)}">
      <span class="map-spot-ico">${sp.icon}</span>${open ? '' : '<span class="map-spot-new">!</span>'}<span class="map-spot-name">${escapeHtml(sp.name)}</span></button>`;
  }).join('');
}
// The leaves part to reveal the map (end of the tutorial).
function leavesRevealToMap(){
  playSubTab = 'conquest'; conquestSelectedMap = 'm1'; conquestSelectedNodeKey = null;
  switchTab('play');
  const cover = document.createElement('div');
  cover.className = 'leaves-cover'; cover.setAttribute('aria-hidden','true');
  const glyphs = ['🌿','🍂','🍁','🌿','🍂','🌱'];
  const rnd = seededRng(20261003);
  let html = '';
  // a jittered grid, so the cover is dense everywhere without visible rows
  for(let i=0;i<160;i++){ const gx = i%16, gy = Math.floor(i/16); const x = Math.min(99, (gx + rnd())*6.4 - 1), y = Math.min(99, (gy + rnd())*10.4 - 2); html += `<span class="lc-leaf" style="left:${x}%; top:${y}%; font-size:${46 + (i*7)%40}px; transform:rotate(${(i*47)%360}deg)" data-side="${x<50?-1:1}">${glyphs[i%glyphs.length]}</span>`; }
  cover.innerHTML = html;
  document.body.appendChild(cover);
  const done = ()=>{ cover.remove(); playDialogue('outskirts_reveal', {once:true}); };
  if(!hasGsap()){ setTimeout(done, 400); return; }
  try{ if(SoundKit.shift) SoundKit.shift(); }catch(e){}
  const tl = gsap.timeline({delay:.5, onComplete: done});
  cover.querySelectorAll('.lc-leaf').forEach(l=>{ const side = +l.dataset.side; tl.to(l, {x: side*(window.innerWidth*0.75 + Math.random()*200), y: (Math.random()-.5)*240, rotation: '+=' + (side*(180+Math.random()*240)), duration: 1.3 + Math.random()*.5, ease: 'power3.in'}, Math.random()*.25); });
  tl.to(cover, {backgroundColor: 'rgba(20,40,16,0)', duration: 1.1, ease: 'power2.in'}, .2);
}
// ---- Skirmish editor (2026-10-03, "Are the mega editors ready... the skirmish editor?"). Admin
// Mode → select a node → 🛠️ Edit skirmish. Edits name/icon/flavour, kind, castle HP, castle
// character, battle mode, surrender behaviour, deck reveal, prerequisite nodes, pre-fight dialogue
// and the enemy deck; "Simulate 200 vs my deck" for tuning; "Test fight" (no Energy, no progress);
// Save publishes live for everyone (card_overrides) when you're a cloud admin. ➕ New skirmish adds
// a node to the map (place it with 📐 Edit layout). ----
const SKIRMISH_KINDS = ['skirmish','elite','boss','raidboss','finalboss'];
function nodePatchFor(mapId, key){ const e = nodeEdits[mapId] = nodeEdits[mapId] || {}; e.patches = e.patches || {}; return e; }
function isAddedNode(mapId, key){ return ((nodeEdits[mapId]||{}).added||[]).some(n=> n.key===key); }
function addSkirmishToMap(mapId){
  const map = CONQUEST_MAPS.find(m=> m.id===mapId); if(!map) return;
  const e = nodePatchFor(mapId); e.added = e.added || [];
  let n = 1; while(map.nodes.some(x=> x.key===`${mapId}-c${n}`)) n++;
  const last = map.nodes.filter(x=> x.kind!=='tutorial').slice(-1)[0];
  const node = {key:`${mapId}-c${n}`, kind:'skirmish', name:'New Skirmish', icon:'⚔️', hqHp:30, flavor:'', deck: Object.assign({}, (last && last.deck) || {'otter-centurion':6}), requires: last ? [last.key] : []};
  e.added.push(node); persistNodeEdits(); applyNodeEdits();
  openSkirmishEditor(mapId, node.key);
}
function simulateSkirmishVsMyDeck(node, n){
  const defs = getCardDefs(); let wins = 0, losses = 0, draws = 0, rounds = 0, castleLeft = 0;
  const myChar = CHARACTER_DEFS[myCharacterId] || CHARACTER_DEFS.castle;
  const enemyChar = node.characterId && CHARACTER_DEFS[node.characterId] ? Object.assign({}, CHARACTER_DEFS[node.characterId], {health: node.hqHp}) : {id:'sim-enemy', name:node.name, health: node.hqHp||30, effects:{}};
  for(let i=0;i<n;i++){
    const engine = makeSimEngine(defs, seededRng(9100+i), {recordEvents:false, battleMode: node.battleMode || 'gravity'});
    const sideOf = id=> id===1?'A':'B', stats = {};
    const P = {1: engine.newPlayer(1, myDeckCounts, myChar), 2: engine.newPlayer(2, node.deck||{}, enemyChar)};
    P[2].loopCards = [];
    engine.draw(P[1], 3, 'A', stats, null); engine.draw(P[2], 3, 'B', stats, null);
    let r = 1, over = false, lastSig = null, stalled = 0;
    for(; r<=DRAW_ROUND_CAP && !over; r++){
      engine.setSuddenDeath(r >= SUDDEN_DEATH_ROUND);
      [1,2].forEach(p=>{ P[p].playedThisTurn = false; P[p].discardUsedThisTurn = false; });
      engine.aiTakeTurn(P, sideOf, 1, stats, null); engine.aiTakeTurn(P, sideOf, 2, stats, null);
      over = engine.resolveCombat(P, sideOf, stats, null, r%2===0 ? 1 : 2);
      if(over) break;
      const sig = boardSignature(P); stalled = (sig===lastSig && noActionsLeft(P)) ? stalled+1 : 0; lastSig = sig; if(stalled>=2) break;
      engine.draw(P[1], 1, 'A', stats, null); engine.draw(P[2], 1, 'B', stats, null);
    }
    const a = P[1].hq.hp<=0, b = P[2].hq.hp<=0;
    if(over && b && !a){ wins++; castleLeft += P[1].hq.hp/P[1].hq.maxHp; } else if(over && a && !b) losses++; else draws++;
    rounds += r;
  }
  return {wins, losses, draws, n, avgRounds: rounds/n, avgCastleLeft: wins ? castleLeft/wins : 0};
}
function openSkirmishEditor(mapId, nodeKey){
  const map = CONQUEST_MAPS.find(m=> m.id===mapId); const node = map && map.nodes.find(n=> n.key===nodeKey); if(!node) return;
  let overlay = document.getElementById('skirmishEditorOverlay');
  if(!overlay){ overlay = document.createElement('div'); overlay.id = 'skirmishEditorOverlay'; overlay.className = 'modal-overlay'; document.body.appendChild(overlay); }
  const draft = JSON.parse(JSON.stringify(node));
  draft.deck = draft.deck || {};
  let q = '', simText = '', dirty = false;
  const close = ()=>{ overlay.hidden = true; overlay.innerHTML = ''; if(currentTab==='play' && !matchState) renderPlay(); };
  const opt = (v, cur, label)=> `<option value="${escapeAttr(v)}" ${String(cur||'')===String(v)?'selected':''}>${escapeHtml(label)}</option>`;
  const render = ()=>{
    const defs = getCardDefs();
    const deckIds = Object.keys(draft.deck).filter(id=> draft.deck[id]>0);
    const total = deckIds.reduce((t,id)=> t + draft.deck[id], 0);
    const matches = q.trim().length < 2 ? [] : Object.keys(defs).filter(id=> !defs[id].test && defs[id].name.toLowerCase().includes(q.trim().toLowerCase())).slice(0, 18);
    const others = map.nodes.filter(n=> n.key!==draft.key);
    overlay.innerHTML = `<div class="modal skirmish-editor" role="dialog" aria-label="Skirmish editor">
      <div class="modal-head-row"><h2>🛠️ ${escapeHtml(draft.icon||'')} ${escapeHtml(draft.name||'Skirmish')} <span class="se-key">${escapeHtml(map.name)} · ${escapeHtml(draft.key)}${isAddedNode(mapId, draft.key)?' · added':''}</span></h2><button class="modal-close-btn" id="seClose" aria-label="Close">✕</button></div>
      <div class="se-grid">
        <label>Name<input id="seName" value="${escapeAttr(draft.name||'')}"></label>
        <label>Icon<input id="seIcon" value="${escapeAttr(draft.icon||'')}" maxlength="4"></label>
        <label>Kind<select id="seKind">${SKIRMISH_KINDS.map(k=> opt(k, draft.kind, KIND_LABEL[k]||k)).join('')}</select></label>
        <label>Castle HP<input id="seHp" type="number" min="1" max="9999" value="${draft.hqHp||30}"></label>
        <label>Castle<select id="seChar">${opt('', draft.characterId, 'Plain castle')}${Object.keys(CHARACTER_DEFS).map(id=> opt(id, draft.characterId, CHARACTER_DEFS[id].name)).join('')}</select></label>
        <label>Battle mode<select id="seMode">${opt('', draft.battleMode, 'Default (Gravity; player picks on elites)')}${Object.keys(BATTLE_MODES).map(k=> opt(k, draft.battleMode, BATTLE_MODES[k].label || k)).join('')}</select></label>
        <label>When out of moves<select id="seBehaviour">${opt('', draft.enemyBehaviour, 'Auto (bosses never surrender)')}${opt('surrender', draft.enemyBehaviour, 'Surrenders')}${opt('offerDraw', draft.enemyBehaviour, 'Offers a draw')}${opt('neverSurrender', draft.enemyBehaviour, 'Never surrenders (loop imps)')}</select></label>
        <label>Deck reveal<select id="seReveal">${opt('', draft.revealDeck, 'Always shown')}${opt('win', draft.revealDeck, 'After a win')}${['C','B','A','S'].map(r=> opt(r, draft.revealDeck, `After a Rank ${r} clear`)).join('')}</select></label>
        <label>Pre-fight dialogue<select id="seDialogue">${opt('', draft.dialogue, 'None')}${Object.keys(DIALOGUES).map(k=> opt(k, draft.dialogue, k)).join('')}</select></label>
        <label class="se-wide">Flavour<input id="seFlavor" value="${escapeAttr(draft.flavor||'')}"></label>
        <div class="se-wide se-req"><span>Requires (must clear first):</span>${others.map(n=> `<label class="se-chk"><input type="checkbox" data-req="${escapeAttr(n.key)}" ${(draft.requires||[]).includes(n.key)?'checked':''}> ${escapeHtml(n.icon||'')} ${escapeHtml(n.key)}</label>`).join('')}</div>
      </div>
      <h3 class="se-h">Enemy deck · ${total} cards</h3>
      <div class="se-deck">${deckIds.length ? deckIds.map(id=> `<div class="se-row"><span class="se-card">${defs[id] ? (defs[id].icon||'')+' '+escapeHtml(defs[id].name) : escapeHtml(id)+' (missing)'}</span><span class="se-stat">${defs[id] ? defs[id].attack+'/'+defs[id].health+(defs[id].wait?' · W'+defs[id].wait:'') : ''}</span>
        <button type="button" class="btn small" data-dec="${escapeAttr(id)}">−</button><b class="se-n">${draft.deck[id]}</b><button type="button" class="btn small" data-inc="${escapeAttr(id)}">+</button></div>`).join('') : '<p class="panel-sub">Empty — add cards below.</p>'}</div>
      <input type="text" id="seSearch" placeholder="Search a card to add to the enemy deck…" value="${escapeAttr(q)}" autocomplete="off">
      <div class="nr-results">${matches.map(id=> `<button type="button" class="nr-result" data-add="${escapeAttr(id)}"><span>${defs[id].icon||''} ${escapeHtml(defs[id].name)}</span><span class="nr-src">${defs[id].attack}/${defs[id].health}${defs[id].token?' · token':''}</span></button>`).join('')}</div>
      ${simText ? `<div class="se-sim">${simText}</div>` : ''}
      <div class="se-actions">
        <button type="button" class="btn" id="seSim">📊 Simulate 200 vs my deck</button>
        <button type="button" class="btn" id="seTest">▶ Test fight</button>
        <span style="flex:1"></span>
        ${isAddedNode(mapId, draft.key) ? `<button type="button" class="btn ghost" id="seDelete">🗑 Delete skirmish</button>` : `<button type="button" class="btn ghost" id="seReset" title="Drop all edits to this node">↺ Reset to original</button>`}
        <button type="button" class="btn primary" id="seSave">💾 Save${cloudCardAdmin?' & publish':''}</button>
      </div>
    </div>`;
    overlay.hidden = false;
    const read = ()=>{
      const v = id=> (document.getElementById(id)||{}).value;
      draft.name = v('seName') || draft.name; draft.icon = v('seIcon') || draft.icon; draft.kind = v('seKind');
      draft.hqHp = Math.max(1, Math.min(9999, Number(v('seHp'))||30)); draft.flavor = v('seFlavor')||'';
      ['characterId','battleMode','enemyBehaviour','revealDeck','dialogue'].forEach((k,i)=>{ const val = v(['seChar','seMode','seBehaviour','seReveal','seDialogue'][i]); if(val) draft[k] = val; else delete draft[k]; });
      draft.requires = [...overlay.querySelectorAll('[data-req]')].filter(c=> c.checked).map(c=> c.dataset.req);
    };
    overlay.querySelectorAll('input,select').forEach(el=>{ if(el.id!=='seSearch') el.addEventListener('change', ()=>{ dirty = true; read(); }); });
    document.getElementById('seClose').onclick = ()=>{ if(dirty && !confirm('Close without saving your changes?')) return; close(); };
    overlay.querySelectorAll('[data-inc]').forEach(b=> b.onclick = ()=>{ read(); draft.deck[b.dataset.inc]++; dirty = true; render(); });
    overlay.querySelectorAll('[data-dec]').forEach(b=> b.onclick = ()=>{ read(); draft.deck[b.dataset.dec]--; if(draft.deck[b.dataset.dec]<=0) delete draft.deck[b.dataset.dec]; dirty = true; render(); });
    overlay.querySelectorAll('[data-add]').forEach(b=> b.onclick = ()=>{ read(); draft.deck[b.dataset.add] = (draft.deck[b.dataset.add]||0) + 1; q = ''; dirty = true; render(); });
    const search = document.getElementById('seSearch');
    search.addEventListener('input', ()=>{ read(); q = search.value; const pos = search.selectionStart; render(); const s2 = document.getElementById('seSearch'); s2.focus(); s2.setSelectionRange(pos, pos); });
    document.getElementById('seSim').onclick = ()=>{ read(); const r = simulateSkirmishVsMyDeck(draft, 200);
      simText = `Your active deck vs this skirmish, 200 games: <b>${Math.round(r.wins/r.n*100)}% wins</b> · ${Math.round(r.losses/r.n*100)}% losses · ${Math.round(r.draws/r.n*100)}% draws · ${r.avgRounds.toFixed(1)} rounds on average${r.wins ? ` · ${Math.round(r.avgCastleLeft*100)}% castle left when you win` : ''}.`; render(); };
    document.getElementById('seSave').onclick = async ()=>{
      read();
      const e = nodePatchFor(mapId);
      if(isAddedNode(mapId, draft.key)){ e.added = e.added.map(n=> n.key===draft.key ? JSON.parse(JSON.stringify(draft)) : n); }
      else {
        const base = (CONQUEST_MAPS_BASELINE.find(m=> m.id===mapId)||{nodes:[]}).nodes.find(n=> n.key===draft.key) || {};
        const patch = {}; Object.keys(draft).forEach(k=>{ if(JSON.stringify(draft[k])!==JSON.stringify(base[k])) patch[k] = draft[k]; });
        ['characterId','battleMode','enemyBehaviour','revealDeck','dialogue'].forEach(k=>{ if(!(k in draft) && (k in base)) patch[k] = null; });
        if(Object.keys(patch).length) e.patches[draft.key] = patch; else delete e.patches[draft.key];
      }
      persistNodeEdits(); applyNodeEdits();
      const published = await publishNodeEdits(mapId);
      showToast(published ? `☁️ ${draft.name} published — live for every player.` : `💾 ${draft.name} saved in this browser.`, 'ok');
      dirty = false; close();
    };
    document.getElementById('seTest').onclick = ()=>{
      read();
      const e = nodePatchFor(mapId);
      // test the draft as-is without saving: temporarily swap it in
      const idx = map.nodes.findIndex(n=> n.key===draft.key); const saved = map.nodes[idx]; map.nodes[idx] = JSON.parse(JSON.stringify(draft));
      overlay.hidden = true;
      playSubTab = 'conquest'; switchTab('play');
      const ok = startConquestMatch(mapId, draft.key, {skipEnergyCost:true});
      map.nodes[idx] = saved;
      if(ok && matchState) matchState.adminTest = true;
    };
    const reset = document.getElementById('seReset');
    if(reset) reset.onclick = async ()=>{ if(!confirm('Drop every edit to this skirmish?')) return; const e = nodePatchFor(mapId); delete e.patches[draft.key]; persistNodeEdits(); applyNodeEdits(); await publishNodeEdits(mapId); showToast('↺ Skirmish reset.', 'ok'); close(); };
    const del = document.getElementById('seDelete');
    if(del) del.onclick = async ()=>{ if(!confirm('Delete this added skirmish?')) return; const e = nodePatchFor(mapId); e.added = (e.added||[]).filter(n=> n.key!==draft.key); delete e.patches[draft.key]; persistNodeEdits(); applyNodeEdits(); await publishNodeEdits(mapId); conquestSelectedNodeKey = null; showToast('🗑 Skirmish deleted.', 'ok'); close(); };
  };
  overlay.onclick = ev=>{ if(ev.target===overlay){ if(dirty && !confirm('Close without saving your changes?')) return; close(); } };
  render();
}
// ---- Player level (2026-10-03, explicit: "You have a level... don't have a cap. The level xp
// requirement should be exponential. Quests, progress and thresholds give a huge amount of xp - so
// levelling does mean not just playtime but actual achievement. E.g. collection size or arena
// rank."). Playing earns a trickle (3 XP a win); the real XP comes from quests and one-time
// milestones, checked by checkXpMilestones() whenever the game state might have crossed one. ----
const XP_KEY = 'bramblewood_player_xp_v1';
function xpToNext(level){ return Math.round(100 * Math.pow(1.18, level-1)); } // level 1→2 needs 100, grows 18% per level, no cap
function loadXp(){ try{ const x = JSON.parse(localStorage.getItem(XP_KEY)||'null'); if(x && typeof x.xp==='number') return Object.assign({milestones:[]}, x); }catch(e){} return {xp:0, milestones:[]}; }
function saveXp(x){ try{ localStorage.setItem(XP_KEY, JSON.stringify(x)); }catch(e){} }
function levelFromXp(xp){ let level = 1, rest = xp; while(rest >= xpToNext(level)){ rest -= xpToNext(level); level++; } return {level, into: rest, need: xpToNext(level)}; }
function playerLevelInfo(){ return levelFromXp(loadXp().xp); }
function awardXp(n, reason){
  if(!(n>0)) return;
  const x = loadXp(), before = levelFromXp(x.xp).level;
  x.xp += Math.round(n); saveXp(x);
  const after = levelFromXp(x.xp).level;
  if(after > before) setTimeout(()=> showToast(`⭐ Level ${after}!${reason ? ' — ' + reason : ''}`, 'ok'), 400);
  refreshLevelBadge();
}
function xpMilestones(){
  const out = [];
  const prog = loadConquestProgress();
  (prog.completed||[]).filter(id=> !/tutorial/.test(id)).forEach(id=> out.push({id:'cq:'+id, xp:25, label:'First clear'}));
  (typeof CONQUEST_MAPS!=='undefined' ? CONQUEST_MAPS : []).forEach(m=>{ if(conquestMapCleared(m.id)) out.push({id:'map:'+m.id, xp:300, label:`Cleared ${m.name}`}); });
  if(loadTutorialDone()) out.push({id:'tutorial', xp:200, label:'Finished the tutorial'});
  const owned = Object.keys(myCardCopies||{}).filter(k=> (myCardCopies[k]||[]).length).length;
  [[10,150],[25,300],[50,600],[100,1000],[200,2000]].forEach(([n,xp])=>{ if(owned>=n) out.push({id:'col:'+n, xp, label:`Collected ${n} cards`}); });
  [[1550,300],[1650,600],[1800,1000],[2000,2000],[2200,3000]].forEach(([r,xp])=>{ if(myRating>=r) out.push({id:'rank:'+r, xp, label:`Reached rating ${r}`}); });
  const st = loadLifetimeStats();
  STAT_MEDALS.forEach(m=>{ const t = medalTier(m.counter, st[m.counter]||0); for(let i=0;i<=t;i++) out.push({id:`medal:${m.counter}:${i}`, xp:[100,300,800,2000][i], label:`${MEDAL_NAMES[i]} medal`}); });
  if((st.abBestWins||0) >= 10) out.push({id:'ab:10', xp:500, label:'10 Autobattler wins in a run'});
  [15,20,30].forEach(n=>{ if((st.abBestWins||0) >= n) out.push({id:'ab:'+n, xp:250, label:`${n} Autobattler wins in a run`}); });
  return out;
}
// 2026-10-04 ("achievement toasts only came out on the Home menu — they should come out as you earn
// them"): milestones were only checked when Home rendered. Now every save that can cross one
// (conquest clears, collection, lifetime stats, rating) schedules a check, coalesced into one.
var milestoneCheckTimer = null; // var, not let: saves during start-up run before this line
function soonCheckMilestones(){
  if(typeof window === 'undefined') return;
  clearTimeout(milestoneCheckTimer);
  milestoneCheckTimer = setTimeout(()=>{ try{ checkXpMilestones(); }catch(e){} }, 700);
}
function checkXpMilestones(){
  const x = loadXp(); const have = new Set(x.milestones);
  const fresh = xpMilestones().filter(m=> !have.has(m.id));
  if(!fresh.length) return;
  fresh.forEach(m=> have.add(m.id));
  x.milestones = Array.from(have); saveXp(x);
  const total = fresh.reduce((t,m)=> t+m.xp, 0);
  awardXp(total, fresh.length===1 ? fresh[0].label : `${fresh.length} milestones`);
  showToast(`✨ +${total} XP — ${fresh.length===1 ? fresh[0].label : fresh.length + ' milestones'}`, 'ok');
}
function levelBadgeHTML(){
  const L = playerLevelInfo();
  return `<div class="player-level" id="playerLevelBadge" title="${L.into} / ${L.need} XP to level ${L.level+1} — XP mostly comes from quests and milestones">
    <span class="pl-num">⭐ Level ${L.level}</span><span class="pl-bar"><span style="width:${Math.round(L.into/L.need*100)}%"></span></span><span class="pl-xp">${L.into}/${L.need} XP</span></div>`;
}
function refreshLevelBadge(){ const el = document.getElementById('playerLevelBadge'); if(el) el.outerHTML = levelBadgeHTML(); }
// ---- Quests & statistics medals (2026-10-03, explicit: "Limited rewards to stop burnout. Daily
// quests: Use 40 energy on Skirmishes, Use 3 tickets in PVP, Defeat 12 units. Then the next tier
// (decreasing rewards): Join a Raid, etc. Weeklies are very rewarding, but also similarly tiered."
// + "reward the grinders with statistics medals"). Each tier shows once the tier above it is fully
// claimed; rewards shrink tier by tier. Counters come from bumpQuestCounter() calls at the source
// (energy spend, ticket use, enemy unit deaths, raid joins, wins). Lifetime totals of the same
// counters earn medals — recognition, never power. ----
const QUESTS_KEY = 'bramblewood_quests_v1';
const STATS_KEY = 'bramblewood_lifetime_stats_v1';
const QUEST_TIERS = {
  daily: [
    {reward:{gold:60, dust:8}, quests:[
      {id:'d1-energy', counter:'energyConquest', goal:40, label:'Use 40 ⚡ Energy on Conquest fights'},
      {id:'d1-pvp', counter:'pvpTickets', goal:3, label:'Use 3 🎟️ PvP tickets'},
      {id:'d1-units', counter:'unitsDefeated', goal:12, label:'Defeat 12 enemy units'}]},
    {reward:{gold:30, dust:4}, quests:[
      {id:'d2-raid', counter:'raidsJoined', goal:1, label:'Join a Raid'},
      {id:'d2-wins', counter:'wins', goal:2, label:'Win 2 matches'},
      {id:'d2-conquest', counter:'conquestWins', goal:2, label:'Clear 2 Conquest fights'}]},
    {reward:{gold:15, dust:2}, quests:[
      {id:'d3-units', counter:'unitsDefeated', goal:30, label:'Defeat 30 enemy units'},
      {id:'d3-pvp', counter:'pvpWins', goal:2, label:'Win 2 PvP matches'}]},
  ],
  weekly: [
    {reward:{gold:300, dust:40, metal:3}, quests:[
      {id:'w1-energy', counter:'energyConquest', goal:200, label:'Use 200 ⚡ Energy on Conquest fights'},
      {id:'w1-pvp', counter:'pvpTickets', goal:30, label:'Use 30 🎟️ PvP tickets'},
      {id:'w1-units', counter:'unitsDefeated', goal:100, label:'Defeat 100 enemy units'}]},
    {reward:{gold:150, dust:20, metal:1}, quests:[
      {id:'w2-raid', counter:'raidsJoined', goal:3, label:'Join 3 Raids'},
      {id:'w2-raiddmg', counter:'raidDamage', goal:20000, label:'Deal 20,000 Raid damage'},
      {id:'w2-wins', counter:'wins', goal:15, label:'Win 15 matches'}]},
    {reward:{gold:70, dust:10}, quests:[
      {id:'w3-conquest', counter:'conquestWins', goal:10, label:'Clear 10 Conquest fights'},
      {id:'w3-pvp', counter:'pvpWins', goal:10, label:'Win 10 PvP matches'}]},
  ],
};
// Medal thresholds for lifetime stats: bronze / silver / gold / platinum.
const STAT_MEDALS = [
  {counter:'unitsDefeated', label:'Units defeated', icon:'⚔️', steps:[100, 1000, 5000, 20000]},
  {counter:'wins', label:'Matches won', icon:'🏆', steps:[10, 100, 500, 2000]},
  {counter:'pvpWins', label:'PvP wins', icon:'🎟️', steps:[10, 100, 500, 2000]},
  {counter:'conquestWins', label:'Conquest fights cleared', icon:'🗺️', steps:[10, 100, 400, 1500]},
  {counter:'raidDamage', label:'Raid damage dealt', icon:'🐲', steps:[10000, 100000, 500000, 2500000]},
  {counter:'energyConquest', label:'Energy spent', icon:'⚡', steps:[200, 2000, 10000, 50000]},
];
const MEDAL_NAMES = ['Bronze','Silver','Gold','Platinum'];
const MEDAL_ICONS = ['🥉','🥈','🥇','💠'];
function weekKey(d){ d = d || new Date(); const m = new Date(d.getFullYear(), d.getMonth(), d.getDate()); m.setDate(m.getDate() - ((m.getDay()+6)%7)); return 'W'+localDayKey(m); } // weeks start Monday
function loadQuestState(){
  let q = null; try{ q = JSON.parse(localStorage.getItem(QUESTS_KEY)||'null'); }catch(e){}
  q = q || {};
  const day = localDayKey(), week = weekKey();
  if(q.day!==day) { q.day = day; q.daily = {}; q.claimedDaily = []; }
  if(q.week!==week){ q.week = week; q.weekly = {}; q.claimedWeekly = []; }
  q.daily = q.daily||{}; q.weekly = q.weekly||{}; q.claimedDaily = q.claimedDaily||[]; q.claimedWeekly = q.claimedWeekly||[];
  return q;
}
function saveQuestState(q){ try{ localStorage.setItem(QUESTS_KEY, JSON.stringify(q)); }catch(e){} }
function loadLifetimeStats(){ try{ return JSON.parse(localStorage.getItem(STATS_KEY)||'{}') || {}; }catch(e){ return {}; } }
function bumpQuestCounter(counter, n){
  if(!(n>0)) return;
  const q = loadQuestState();
  q.daily[counter] = (q.daily[counter]||0) + n;
  q.weekly[counter] = (q.weekly[counter]||0) + n;
  saveQuestState(q);
  const st = loadLifetimeStats(); st[counter] = (st[counter]||0) + n;
  try{ localStorage.setItem(STATS_KEY, JSON.stringify(st)); }catch(e){}
  refreshQuestBadge(); soonCheckMilestones();
}
// The tiers a player can currently see: every fully-claimed tier plus the first unfinished one.
function visibleQuestTiers(kind, q){
  const claimed = kind==='daily' ? q.claimedDaily : q.claimedWeekly;
  const out = [];
  for(const tier of QUEST_TIERS[kind]){
    out.push(tier);
    if(!tier.quests.every(x=> claimed.includes(x.id))) break;
  }
  return out;
}
function claimableQuestCount(){
  const q = loadQuestState(); let n = 0;
  ['daily','weekly'].forEach(kind=>{
    const counts = q[kind], claimed = kind==='daily' ? q.claimedDaily : q.claimedWeekly;
    visibleQuestTiers(kind, q).forEach(t=> t.quests.forEach(x=>{ if(!claimed.includes(x.id) && (counts[x.counter]||0) >= x.goal) n++; }));
  });
  return n;
}
function claimQuest(kind, id){
  const q = loadQuestState();
  const claimed = kind==='daily' ? q.claimedDaily : q.claimedWeekly;
  const tier = visibleQuestTiers(kind, q).find(t=> t.quests.some(x=> x.id===id)); if(!tier) return;
  const quest = tier.quests.find(x=> x.id===id);
  if(claimed.includes(id) || (q[kind][quest.counter]||0) < quest.goal) return;
  claimed.push(id); saveQuestState(q);
  Object.entries(tier.reward).forEach(([k,v])=> grantCurrency(k, v));
  const tierIdx = QUEST_TIERS[kind].indexOf(tier);
  awardXp((kind==='daily' ? [100,60,30] : [400,250,120])[tierIdx] || 20, 'quest');
  showToast(`📜 Quest reward: ${Object.entries(tier.reward).map(([k,v])=> `+${v} ${(CURRENCY_META[k]||{label:k}).label}`).join(', ')}`, 'ok');
  refreshQuestBadge();
}
function medalTier(counter, value){ const m = STAT_MEDALS.find(x=> x.counter===counter); let t = -1; if(m) m.steps.forEach((s,i)=>{ if(value>=s) t = i; }); return t; }
function questsModalHTML(){
  const q = loadQuestState(), st = loadLifetimeStats();
  const resetIn = (ms)=>{ const h = Math.floor(ms/3600000), d = Math.floor(h/24); return d ? `${d}d ${h%24}h` : `${h}h ${Math.floor((ms%3600000)/60000)}m`; };
  const now = new Date(), nextMon = new Date(now.getFullYear(), now.getMonth(), now.getDate() + (7 - ((now.getDay()+6)%7)));
  const section = (kind, title, ms)=>{
    const counts = q[kind], claimed = kind==='daily' ? q.claimedDaily : q.claimedWeekly;
    const tiers = visibleQuestTiers(kind, q);
    const hidden = QUEST_TIERS[kind].length - tiers.length;
    return `<section class="qs-section"><h3>${title} <span class="qs-reset">resets in ${resetIn(ms)}</span></h3>
      ${tiers.map((t,ti)=> `<div class="qs-tier"><div class="qs-tier-head">Tier ${ti+1} · each: ${Object.entries(t.reward).map(([k,v])=> `${(CURRENCY_META[k]||{}).glyph||''} ${v}`).join(' ')}</div>
        ${t.quests.map(x=>{ const v = Math.min(x.goal, counts[x.counter]||0), done = v>=x.goal, got = claimed.includes(x.id);
          return `<div class="qs-quest ${got?'is-claimed':''}"><div class="qs-q-label">${escapeHtml(x.label)}</div>
            <div class="qs-bar"><div style="width:${Math.round(v/x.goal*100)}%"></div></div><div class="qs-q-num">${v}/${x.goal}</div>
            ${got ? '<span class="qs-done">✓ Claimed</span>' : `<button class="btn small ${done?'primary':''}" data-claim-kind="${kind}" data-claim-id="${x.id}" ${done?'':'disabled'}>Claim</button>`}</div>`; }).join('')}
      </div>`).join('')}
      ${hidden>0 ? `<div class="qs-more">🔒 ${hidden} more tier${hidden===1?'':'s'} (smaller rewards) after this one</div>` : ''}
    </section>`;
  };
  const medals = STAT_MEDALS.map(m=>{ const v = st[m.counter]||0, t = medalTier(m.counter, v), next = m.steps[t+1];
    return `<div class="qs-medal ${t>=0?'has-medal':''}" title="${next!=null ? `Next: ${MEDAL_NAMES[t+1]} at ${next.toLocaleString()}` : 'Top medal reached'}"><span class="qs-medal-ico">${t>=0 ? MEDAL_ICONS[t] : '▫️'}</span>
      <span class="qs-medal-l">${m.icon} ${m.label}</span><span class="qs-medal-v">${v.toLocaleString()}</span></div>`; }).join('');
  return `<div class="modal quests-modal" role="dialog" aria-labelledby="qsTitle">
    <div class="modal-head-row"><h2 id="qsTitle">📜 Quests</h2><button class="modal-close-btn" id="qsClose" aria-label="Close">✕</button></div>
    ${section('daily', 'Daily', msUntilLocalMidnight())}
    ${section('weekly', 'Weekly', nextMon - now)}
    <section class="qs-section"><h3>Medals <span class="qs-reset">lifetime stats — for bragging, not power</span></h3><div class="qs-medals">${medals}</div></section>
  </div>`;
}
let questsKeyHandler = null;
function openQuestsModal(){
  const overlay = document.getElementById('authGateOverlay'); if(!overlay) return;
  const prevScroll = overlay.querySelector('.quests-modal') ? overlay.querySelector('.quests-modal').scrollTop : 0;
  overlay.innerHTML = questsModalHTML(); overlay.hidden = false;
  overlay.querySelector('.quests-modal').scrollTop = prevScroll;
  const close = ()=>{ overlay.hidden = true; overlay.innerHTML = ''; if(questsKeyHandler){ document.removeEventListener('keydown', questsKeyHandler); questsKeyHandler = null; } };
  if(questsKeyHandler) document.removeEventListener('keydown', questsKeyHandler);
  questsKeyHandler = e=>{ if(e.key==='Escape') close(); };
  document.addEventListener('keydown', questsKeyHandler);
  document.getElementById('qsClose').onclick = close;
  overlay.onclick = e=>{ if(e.target===overlay) close(); };
  overlay.querySelectorAll('[data-claim-id]').forEach(b=> b.addEventListener('click', ()=>{ claimQuest(b.dataset.claimKind, b.dataset.claimId); openQuestsModal(); }));
}
function refreshQuestBadge(){
  const n = claimableQuestCount();
  document.querySelectorAll('#homeQuestsBtn .home-badge').forEach(b=> b.remove());
  if(n>0) document.querySelectorAll('#homeQuestsBtn').forEach(btn=>{ const s = document.createElement('span'); s.className = 'home-badge'; s.textContent = n; btn.appendChild(s); });
}
// ---- Autobattler draft run (2026-10-03) — rules and simulation live in bramblewood-autobattle.js
// (shared with tests/autobattle.js); this is the UI and the local persistence. Fights are CPU vs CPU
// and resolve instantly, so a run is all about drafting and boon choices. ----
const AutoB = (typeof BramblewoodAutobattle!=='undefined') ? BramblewoodAutobattle : null;
const AB_RUN_KEY = 'bramblewood_ab_run_v1';
const AB_GHOSTS_KEY = 'bramblewood_ab_ghosts_v1';
let abLastFight = null; // the fight result shown on the result screen
const _abPoolCache = {};
function loadAbRun(){ try{ return JSON.parse(localStorage.getItem(AB_RUN_KEY)||'null'); }catch(e){ return null; } }
function saveAbRun(run){ try{ if(run) localStorage.setItem(AB_RUN_KEY, JSON.stringify(run)); else localStorage.removeItem(AB_RUN_KEY); }catch(e){} }
function loadAbGhosts(){ try{ return JSON.parse(localStorage.getItem(AB_GHOSTS_KEY)||'[]') || []; }catch(e){ return []; } }
function abPool(stage){
  liveRefreshGhosts('autobattle');
  const rec = LiveData.ghosts.autobattle.concat(loadAbGhosts()).filter(g=> g.owner!==myGhostOwnerId() && g.owner!==cloudUserId);
  const key = stage + ':' + Math.floor(Date.now()/(7*24*3600*1000)) + ':' + rec.length + ':' + (LiveData.ghostsAt.autobattle||0);
  if(!_abPoolCache[key]) _abPoolCache[key] = AutoB.opponentPool(getCardDefs(), CHARACTER_DEFS, stage, rec, Date.now());
  return _abPoolCache[key];
}
function castleBlurb(c){
  const e = (c && c.effects) || {}, bits = [];
  if(e.startGold) bits.push(`Start with +${e.startGold} 🪵`);
  if(e.firstUnitAtkBonus) bits.push(`First unit +${e.firstUnitAtkBonus} ⚔`);
  return bits.join(' · ') || 'No special effect';
}
function castleTileHTML(c, extra){ return `<div class="ab-castle-tile ${extra||''}"><div class="ab-castle-ico">${c.icon||'🏰'}</div><div class="ab-castle-name">${escapeHtml(c.name)}</div><div class="ab-castle-hp">🏰 ${c.health} HP</div><div class="ab-castle-fx">${escapeHtml(castleBlurb(c))}</div></div>`; }
function abDisplayDef(run, id){
  const base = getCardDefs()[AutoB.baseId(id)]; if(!base) return null;
  const side = AutoB.sideDefs(getCardDefs(), 'view', run.patches);
  return side.extra[side.idFor(AutoB.baseId(id))] || base;
}
function abHeartsHTML(run){ let h = ''; for(let i=0;i<AutoB.AB.START_HP;i++) h += i < run.hp ? '❤️' : '🖤'; return `<span class="ab-hearts" title="${run.hp} health left">${h}</span>`; }
function abStatusBarHTML(run){
  const goal = AutoB.AB.WIN_GOAL;
  return `<div class="ab-status">
    ${abHeartsHTML(run)}
    <span class="ab-stat" title="Wins this run">🏆 <b>${run.wins}</b>${run.endless ? ' · ♾️ Endless' : ` / ${goal}`}</span>
    <span class="ab-stat" title="Fights played">⚔️ Fight ${run.fights + (run.phase==='prep'?1:0)}</span>
    <span class="ab-stat ab-penalty" title="Health lost on a loss">Loss costs ${AutoB.lossPenalty(run.fights+1)} ❤️</span>
    ${run.leader ? `<span class="ab-stat" title="Deck level: each card's rarity weight × its level; leaders count double">📈 Deck Lv <b>${AutoB.runDeckLevel(getCardDefs(), run)}</b></span>` : ''}
  </div>`;
}
function renderAutobattleSubTab(body){
  if(!AutoB){ body.innerHTML = '<div class="panel">Autobattler unavailable.</div>'; return; }
  const run = loadAbRun();
  const defs = getCardDefs();
  if(!run){
    body.innerHTML = `<div class="panel ab-panel ab-intro">
      <h2>🧩 Autobattler</h2>
      <p class="panel-sub">Build a deck from nothing and watch it fight other players' runs. You make the choices; the fights play themselves.</p>
      <ol class="ab-loop" aria-label="How a run works">
        <li><span class="abl-ico">🏰</span><b>Draft</b><span>a castle, two leaders, then cards</span></li>
        <li><span class="abl-ico">⚔️</span><b>Fight</b><span>another player's run with as many wins</span></li>
        <li><span class="abl-ico">✨</span><b>Boon</b><span>copy a card, +1/+1, or a new passive</span></li>
        <li><span class="abl-ico">🏆</span><b>${AutoB.AB.WIN_GOAL} wins</b><span>cash out, or go Endless</span></li>
      </ol>
      <button class="btn primary big ab-start-hero" id="abStartBtn">🧩 Start a run</button>
      <details class="ab-rules-more"><summary>Full rules</summary>
      <ul class="ab-rules">
        <li>❤️ <b>${AutoB.AB.START_HP} health.</b> A loss in your first ${AutoB.AB.EARLY_FIGHTS} fights costs ${AutoB.AB.EARLY_LOSS}; after that a loss costs ${AutoB.AB.LATE_LOSS}.</li>
        <li>🏆 <b>Reach ${AutoB.AB.WIN_GOAL} wins.</b> Then cash out, or keep going in Endless (stops at fight ${AutoB.AB.HARD_STOP}).</li>
        <li>👑 <b>Two leaders:</b> your leader starts every fight on the board; your sub-leader joins on round ${AutoB.AB.SUB_LEADER_ROUND} and can be swapped between fights.</li>
        <li>✨ <b>After every fight</b> pick a boon: duplicate a card, +1/+1 a card, or give a card a passive.</li>
        <li>👻 <b>Opponents</b> are other players' runs with the same number of wins.</li>
      </ul></details>
    </div>`;
    document.getElementById('abStartBtn').onclick = ()=>{ saveAbRun(AutoB.newRun((Math.random()*2**32)>>>0, Date.now())); renderAutobattleSubTab(body); };
    return;
  }
  const rerender = ()=> renderAutobattleSubTab(body);
  if(run.phase==='draft'){
    const off = AutoB.draftOffers(defs, CHARACTER_DEFS, run);
    const titles = {castle:'Pick your castle', leader:'Pick your leader — starts every fight on the board', subLeader:`Pick your sub-leader — joins on round ${AutoB.AB.SUB_LEADER_ROUND}`, card:'Pick a card'};
    const pickNo = off.kind==='card' ? ` (${run.step-2} of ${AutoB.AB.PICKS})` : '';
    body.innerHTML = `<div class="panel ab-panel">
      <div class="ab-draft-head"><h2>Draft · ${titles[off.kind]}${pickNo}</h2><span class="ab-step">Step ${run.step+1} / ${AutoB.DRAFT_STEPS}</span></div>
      <div class="ab-offers">${off.options.map(id=> `<button type="button" class="ab-offer" data-pick="${escapeAttr(id)}">${off.kind==='castle' ? castleTileHTML(CHARACTER_DEFS[id]) : cardTileHTML(defs[id], {inPlay:true})}</button>`).join('')}</div>
      ${abDeckSummaryHTML(run)}
    </div>`;
    body.querySelectorAll('[data-pick]').forEach(b=> b.onclick = ()=>{ AutoB.applyDraftPick(run, b.dataset.pick); saveAbRun(run); rerender(); });
    return;
  }
  if(run.phase==='result' && abLastFight){ renderAbResult(body, run); return; }
  if(run.phase==='result') run.phase = abNextPhaseAfterResult(run);
  if(run.phase==='boon'){
    run.pendingBoons = run.pendingBoons || AutoB.boonOffers(defs, run); saveAbRun(run);
    body.innerHTML = `<div class="panel ab-panel">${abStatusBarHTML(run)}
      <h2>✨ Pick a boon</h2>
      <div class="ab-offers">${run.pendingBoons.map((bn,i)=>{ const d = abDisplayDef(run, bn.card);
        return `<button type="button" class="ab-offer ab-boon" data-boon="${i}"><div class="ab-boon-label">${bn.type==='dup'?'📑':bn.type==='buff'?'💪':'🔮'} ${escapeHtml(bn.label)}</div>${d?cardTileHTML(d, {inPlay:true}):''}</button>`; }).join('')}</div>
      ${abDeckSummaryHTML(run)}</div>`;
    body.querySelectorAll('[data-boon]').forEach(b=> b.onclick = ()=>{ AutoB.applyBoon(run, run.pendingBoons[+b.dataset.boon]); run.phase = 'prep'; saveAbRun(run); rerender(); });
    return;
  }
  if(run.phase==='goal'){
    body.innerHTML = `<div class="panel ab-panel ab-center">${abStatusBarHTML(run)}
      <div class="ab-big">🏆</div><h2>${AutoB.AB.WIN_GOAL} wins!</h2>
      <p class="panel-sub">Cash out now, or keep going in Endless — every extra win adds to your rewards, but you can still lose your run. Endless stops at fight ${AutoB.AB.HARD_STOP}.</p>
      <div class="ab-actions"><button class="btn primary big" id="abEndlessBtn">♾️ Go Endless</button><button class="btn big" id="abCashBtn">💰 Cash out</button></div></div>`;
    document.getElementById('abEndlessBtn').onclick = ()=>{ AutoB.goEndless(run); saveAbRun(run); rerender(); };
    document.getElementById('abCashBtn').onclick = ()=>{ AutoB.cashOut(run); saveAbRun(run); rerender(); };
    return;
  }
  if(run.phase==='over'){
    if(!run.rewarded){ const rw = AutoB.runRewards(run); Object.entries(rw).forEach(([k,v])=>{ if(v>0) grantCurrency(k, v); }); run.rewarded = rw; saveAbRun(run); }
    const rw = run.rewarded;
    const why = {'out-of-health':'Out of health', 'hard-stop':`Fight ${AutoB.AB.HARD_STOP} — the run is complete`, 'cashed-out':'Cashed out'}[run.overReason] || 'Run over';
    body.innerHTML = `<div class="panel ab-panel ab-center">
      <div class="ab-big">${run.wins>=AutoB.AB.WIN_GOAL?'🏅':'🧩'}</div><h2>${escapeHtml(why)}</h2>
      <p class="ab-final"><b>${run.wins}</b> wins · ${run.losses} losses · ${run.fights} fights</p>
      <div class="winloss-conquest-rewards">${rw.gold?`<span class="hud-pill forge-cur-gold">${mapleLeafIconHTML()} +${rw.gold} Maple Leaves</span>`:''}${rw.dust?`<span class="hud-pill forge-cur-dust">✨ +${rw.dust} Dust</span>`:''}${rw.metal?`<span class="hud-pill forge-cur-metal">🔩 +${rw.metal} Metal</span>`:''}</div>
      <div class="ab-history">${run.history.map(h=> `<span class="ab-h ${h.won?'w':h.draw?'d':'l'}" title="Fight ${h.n} vs ${escapeAttr(h.opp)}">${h.won?'W':h.draw?'D':'L'}</span>`).join('')}</div>
      <div class="ab-actions"><button class="btn primary big" id="abNewRunBtn">Start a new run</button></div></div>`;
    document.getElementById('abNewRunBtn').onclick = ()=>{ saveAbRun(null); abLastFight = null; rerender(); };
    return;
  }
  // prep
  const subOpts = AutoB.canSwapSubLeader(run) ? AutoB.subLeaderOffers(defs, run) : [];
  const L = abDisplayDef(run, run.leader), S = abDisplayDef(run, run.subLeader);
  body.innerHTML = `<div class="panel ab-panel">${abStatusBarHTML(run)}
    <div class="ab-prep">
      <div class="ab-commanders">
        <div class="ab-slot"><div class="ab-slot-l">Castle <span class="ab-note">+${Math.round(AutoB.AB.CASTLE_GROWTH*100)}% health per fight</span></div>${castleTileHTML(Object.assign({}, CHARACTER_DEFS[run.castle]||{name:'Castle',health:30}, {health: AutoB.castleHealthFor((CHARACTER_DEFS[run.castle]||{health:30}).health, run.fights)}))}</div>
        <div class="ab-slot"><div class="ab-slot-l">👑 Leader</div>${L?cardTileHTML(L, {inPlay:true}):''}</div>
        <div class="ab-slot"><div class="ab-slot-l">🥈 Sub-leader <span class="ab-note">joins round ${AutoB.AB.SUB_LEADER_ROUND}</span></div>${S?cardTileHTML(S, {inPlay:true}):''}
          ${subOpts.length ? `<div class="ab-swap"><div class="ab-note">Swap for:</div>${subOpts.map(id=> `<button type="button" class="btn small" data-swap="${escapeAttr(id)}" title="${escapeAttr(defs[id].name+' — '+defs[id].attack+'/'+defs[id].health)}">${defs[id].icon} ${escapeHtml(defs[id].name)}</button>`).join('')}</div>` : `<div class="ab-note">Swapped this round</div>`}</div>
      </div>
      <div class="ab-fight-box"><button class="btn primary big" id="abFightBtn">⚔️ Fight</button><div class="ab-note">vs a run with ${run.wins} win${run.wins===1?'':'s'}</div>
        <button type="button" class="btn small ghost" id="abAbandonBtn">Abandon run</button></div>
    </div>
    ${abDeckSummaryHTML(run)}</div>`;
  body.querySelectorAll('[data-swap]').forEach(b=> b.onclick = ()=>{ AutoB.swapSubLeader(run, b.dataset.swap); saveAbRun(run); rerender(); });
  document.getElementById('abAbandonBtn').onclick = ()=>{ if(confirm('Abandon this run? You keep the rewards for the wins so far.')){ AutoB.cashOut(run); run.overReason = 'cashed-out'; saveAbRun(run); rerender(); } };
  document.getElementById('abFightBtn').onclick = ()=> abFight(body, run);
  wireAbDeckMoves(body, run);
}
function abNextPhaseAfterResult(run){ return run.over ? 'over' : (run.wins >= AutoB.AB.WIN_GOAL && !run.endless ? 'goal' : 'boon'); }
function abCardChip(run, id, n, where){
  const d = abDisplayDef(run, id); if(!d) return '';
  const lvl = (run.levels||{})[AutoB.baseId(id)] || 1;
  const canMove = run.phase==='prep' && (where==='deck' ? AutoB.deckTotal(run.bench||{}) < AutoB.AB.BENCH_SIZE : AutoB.deckTotal(run.deck) < AutoB.AB.DECK_SIZE);
  return `<div class="ab-deck-card ${(run.patches||{})[AutoB.baseId(id)]?'is-boosted':''}">${cardTileHTML(d, {inPlay:true})}<div class="ab-cap"><span class="ab-cap-lvl">Lv ${lvl}</span><span>×${n}</span></div>
    ${run.phase==='prep' ? `<button type="button" class="btn small ab-move" data-move-${where==='deck'?'bench':'deck'}="${escapeAttr(id)}" ${canMove?'':'disabled'} title="${where==='deck'?'Move one copy to the bench':'Move one copy into the deck'}">${where==='deck'?'⬇ Bench':'⬆ Deck'}</button>` : ''}</div>`;
}
function abDeckSummaryHTML(run){
  const ids = Object.keys(run.deck||{}), bench = Object.keys(run.bench||{});
  if(!ids.length && !bench.length) return '';
  return `<div class="ab-deck"><div class="ab-deck-h">Deck · ${AutoB.deckTotal(run.deck)} / ${AutoB.AB.DECK_SIZE} cards <span class="ab-note">+ 2 leaders</span></div>
    <div class="ab-deck-grid">${ids.map(id=> abCardChip(run, id, run.deck[id], 'deck')).join('')}</div>
    <div class="ab-deck-h ab-bench-h">Bench · ${AutoB.deckTotal(run.bench||{})} / ${AutoB.AB.BENCH_SIZE} <span class="ab-note">stored cards don't fight — swap them in between fights</span></div>
    <div class="ab-deck-grid ab-bench">${bench.length ? bench.map(id=> abCardChip(run, id, run.bench[id], 'bench')).join('') : '<div class="ab-note">Empty — duplicates land here when your deck is full.</div>'}</div></div>`;
}
function wireAbDeckMoves(body, run){
  body.querySelectorAll('[data-move-bench]').forEach(b=> b.onclick = ()=>{ AutoB.moveToBench(run, b.dataset.moveBench); saveAbRun(run); renderAutobattleSubTab(body); });
  body.querySelectorAll('[data-move-deck]').forEach(b=> b.onclick = ()=>{ AutoB.moveToDeck(run, b.dataset.moveDeck); saveAbRun(run); renderAutobattleSubTab(body); });
}
function abFight(body, run){
  const pool = abPool(run.wins);
  const faced = run.history.map(h=> h.oppOwner).filter(Boolean);
  const opp = AutoB.pickOpponent(pool, AutoB.hashStr(run.id + ':' + run.fights), faced);
  // You become a ghost for other players at this stage.
  const mySnap = AutoB.snapshotOf(run, myGhostOwnerId(), (myProfile && myProfile.name) || 'You', loadAvatar(), Date.now());
  try{ localStorage.setItem(AB_GHOSTS_KEY, JSON.stringify(AutoB.recordGhost(loadAbGhosts(), mySnap))); }catch(e){}
  livePushGhost('autobattle', run.wins, {castle: mySnap.castle, leader: mySnap.leader, subLeader: mySnap.subLeader, deck: mySnap.deck, patches: mySnap.patches, bench: mySnap.bench||{}});
  const res = AutoB.simulateFight({makeSimEngine, boardSignature, noActionsLeft}, getCardDefs(), CHARACTER_DEFS, run, opp, AutoB.hashStr(run.id + ':fight:' + run.fights));
  const hpBefore = run.hp;
  AutoB.afterFight(run, res, opp.name);
  run.history[run.history.length-1].oppOwner = opp.owner;
  if(res.winner===1){ bumpQuestCounter('wins', 1); awardXp(3); }
  { const st = loadLifetimeStats(); if((st.abBestWins||0) < run.wins){ st.abBestWins = run.wins; try{ localStorage.setItem(STATS_KEY, JSON.stringify(st)); }catch(e){} } }
  bumpQuestCounter('unitsDefeated', res.events.filter(e=> e.type==='death' && e.side==='B').length);
  abLastFight = {res, opp, hpBefore};
  recordRecentOpponent({name: opp.name, mode:'autobattle', deck: Object.fromEntries(Object.entries(opp.deck||{}).map(([k,v])=> [AutoB.baseId(k), v])), result: res.winner===1 ? 'win' : (res.winner===2 ? 'loss' : 'draw')});
  run.phase = 'result';
  saveAbRun(run);
  renderAutobattleSubTab(body);
}
function renderAbResult(body, run){
  const {res, opp, hpBefore} = abLastFight;
  const defs = getCardDefs();
  const won = res.winner===1, draw = res.winner===0;
  const me = {name:(myProfile && myProfile.name) || 'You', avatar: loadAvatar()};
  const bar = (hp, max, cls)=> `<div class="ab-castle-bar ${cls}"><div class="ab-castle-fill" style="width:100%" data-to="${Math.round(Math.max(0,hp)/max*100)}"></div><span>${Math.max(0,hp)} / ${max}</span></div>`;
  body.innerHTML = `<div class="panel ab-panel ab-center ab-result">
    <div class="ab-vs"><div class="ab-vs-side">${avatarHTML(me.avatar, 64)}<div>${escapeHtml(me.name)}</div>${bar(res.hp[0], res.maxHp[0], 'mine')}</div>
      <div class="ab-vs-mid">VS</div>
      <div class="ab-vs-side">${avatarHTML(opp.avatar || {character:'mouse', color:'night'}, 64)}<div>${escapeHtml(opp.name)}</div>${bar(res.hp[1], res.maxHp[1], 'theirs')}</div></div>
    <h2 class="ab-outcome ${won?'win':draw?'draw':'loss'}">${won?'Victory!':draw?'Draw':'Defeat'}</h2>
    <p class="ab-final">${res.rounds} rounds${res.mvp && defs[res.mvp] ? ` · MVP ${defs[res.mvp].icon} ${escapeHtml(defs[res.mvp].name)} (${res.mvpDamage} damage)` : ''}${!won && !draw ? ` · −${hpBefore - run.hp} ❤️` : ''}</p>
    ${abStatusBarHTML(run)}
    <div class="ab-actions"><button class="btn primary big" id="abContinueBtn">Continue</button></div></div>`;
  if(hasGsap()) body.querySelectorAll('.ab-castle-fill').forEach(el=> gsap.to(el, {width: el.dataset.to + '%', duration: 1.1, delay: .3, ease:'power2.out'}));
  else body.querySelectorAll('.ab-castle-fill').forEach(el=> el.style.width = el.dataset.to + '%');
  document.getElementById('abContinueBtn').onclick = ()=>{ abLastFight = null; run.phase = abNextPhaseAfterResult(run); saveAbRun(run); renderAutobattleSubTab(body); };
}
// ---- PvP (2026-10-03, explicit: "one mode is just called PVP, and you use your daily 10 tickets to
// battle random strangers' decks, piloted by AI. They always go first."). A ticket is spent when the
// match starts. The stranger is a deck from the ghost pool at the stage that matches your rating;
// each match you play also records YOUR deck, so you become a stranger for other players. "They go
// first": the stranger plays its card at the START of every round, before you plan, and wins every
// same-column tie in combat. ----
const PVP_TICKETS_PER_DAY = 10;
const PVP_TICKETS_KEY = 'bramblewood_pvp_tickets_v1';
const PVP_DECKS_KEY = 'bramblewood_pvp_decks_v1';
function localDayKey(d){ d = d || new Date(); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }
function loadPvpTickets(){ try{ const t = JSON.parse(localStorage.getItem(PVP_TICKETS_KEY)||'null'); if(t && t.day===localDayKey()) return t; }catch(e){} return {day: localDayKey(), used:0}; }
function pvpTicketsLeft(){ return Math.max(0, PVP_TICKETS_PER_DAY - loadPvpTickets().used); }
function usePvpTicket(){ const t = loadPvpTickets(); if(t.used >= PVP_TICKETS_PER_DAY) return false; t.used++; try{ localStorage.setItem(PVP_TICKETS_KEY, JSON.stringify(t)); }catch(e){} bumpQuestCounter('pvpTickets', 1); return true; }
function msUntilLocalMidnight(){ const n = new Date(); const m = new Date(n.getFullYear(), n.getMonth(), n.getDate()+1); return m - n; }
function pvpStageForRating(r){ const max = Ghosts ? Ghosts.ASYNC.MAX_WINS-1 : 6; return Math.max(0, Math.min(max, Math.round(((r||RANK_MEAN) - 1300) / 70))); }
function loadPvpDecks(){ try{ return JSON.parse(localStorage.getItem(PVP_DECKS_KEY)||'[]') || []; }catch(e){ return []; } }
// PvP matchmaking (2026-10-03): strangers from your own rating tier (widening only if the tier is
// thin), with a light pull toward decks near your deck level — see matchPvp in bramblewood-ghosts.js.
// Candidates: live PvP decks, this browser's recorded decks, and seeded strangers for every tier.
const PVP_RECENT_KEY = 'bramblewood_pvp_recent_owners_v1';
function myPvpDeckLevel(){ return mainDeckLevel(myDeckCounts, myLeaderId) || 1; }
function pvpCandidates(){
  const defs = getCardDefs(), mine = myGhostOwnerId();
  liveRefreshGhosts('pvp');
  const fill = g=> Object.assign({}, g, {rating: g.rating!=null ? g.rating : Ghosts.tierMidRating(Math.min(5, Math.round((g.stage||0)*5/6))), deckLevel: g.deckLevel!=null ? g.deckLevel : Ghosts.simpleDeckLevel(defs, g.deck)});
  const real = LiveData.ghosts.pvp.concat(loadPvpDecks()).filter(g=> g.owner!==mine && g.owner!==cloudUserId && g.deck && !Ghosts.validateDeck(defs, g.deck).length).map(fill);
  const epoch = Math.floor(Date.now()/(7*24*3600*1000));
  const seeds = []; for(let t=0; t<=5; t++) seeds.push(...Ghosts.seedPvpStrangers(defs, t, 8, epoch));
  return real.concat(seeds);
}
function pickPvpStranger(seed){
  let recent = []; try{ recent = JSON.parse(localStorage.getItem(PVP_RECENT_KEY)||'[]'); }catch(e){}
  const res = Ghosts.matchPvp({rating: myRating, deckLevel: myPvpDeckLevel()}, pvpCandidates(), seed, recent);
  if(res.opponent){ recent = [res.opponent.owner].concat(recent.filter(o=> o!==res.opponent.owner)).slice(0, 5); try{ localStorage.setItem(PVP_RECENT_KEY, JSON.stringify(recent)); }catch(e){} }
  return res;
}
function pvpOpponentPool(){ return {decks: pvpCandidates()}; } // kept for older callers/tests
function recordMyPvpDeck(){
  if(!Ghosts) return;
  const tier = Ghosts.tierIndexForRating(myRating);
  const entry = {owner: myGhostOwnerId(), name: (myProfile && myProfile.name) || 'You', avatar: loadAvatar(), deck: Object.assign({}, myDeckCounts), stage: tier, rating: Math.round(myRating), deckLevel: myPvpDeckLevel(), at: Date.now(), source:'player'};
  try{ localStorage.setItem(PVP_DECKS_KEY, JSON.stringify(Ghosts.recordAsyncGhost(loadPvpDecks(), entry, 200))); }catch(e){}
  livePushGhost('pvp', tier, {deck: entry.deck, rating: entry.rating, deckLevel: entry.deckLevel});
}
function pvpTileHTML(){
  const left = pvpTicketsLeft();
  const h = Math.floor(msUntilLocalMidnight()/3600000), mn = Math.floor((msUntilLocalMidnight()%3600000)/60000);
  return `<button class="btn primary big arena-mode-btn pvp-mode-btn" id="startPvpBtn" ${left?'':'disabled'}>
    <span class="amb-ico">⚔️</span><span class="amb-lbl">PvP</span>
    <span class="amb-sub">A stranger's deck from your tier</span>
    <span class="async-run-line">🏅 ${escapeHtml(rankForRating(myRating).label)} · rating ${Math.round(myRating)} · your deck Lv ${myPvpDeckLevel()}</span>
    <span class="async-run-line">🎟️ <b>${left}/${PVP_TICKETS_PER_DAY}</b> tickets today · ${left ? `refills in ${h}h ${mn}m` : `next tickets in ${h}h ${mn}m`}</span>
  </button>`;
}
function settlePvpAfterMatch(m){
  const won = m.winner===1;
  // Elo against the stranger's own rating (async: only your rating moves).
  const oppRating = (m.pvpGhost && m.pvpGhost.rating) || Ghosts.tierMidRating(Ghosts.tierIndexForRating(myRating));
  const { newRating, delta } = Ghosts.eloUpdate(myRating, oppRating, won, m.winner===0);
  myRating = newRating; saveRatingLocal(); cloudPushRating();
  m.pvpRatingDelta = delta;
  // Deliberately low raw rewards (MASTER item 10): the big rewards come from quests.
  const g = won ? 18 : 6, d = won ? 2 : 0;
  grantCurrency('gold', g); if(d) grantCurrency('dust', d);
  m.pvpRewardEarned = {gold:g, dust:d};
}
// Async Arena (item #62): a match that persists in this browser (localStorage) rather than
// only in memory, so leaving the tab and coming back — even after a reload — offers a
// Continue option instead of forcing a fresh Start. Scoped to single-device continuity, not
// cross-device real-time multiplayer.
const ASYNC_MATCH_KEY = 'bramblewood_async_match_v1';
function saveAsyncMatchState(){
  if(!matchState || matchState.mode!=='async' || matchState.over) return;
  try{
    localStorage.setItem(ASYNC_MATCH_KEY, JSON.stringify({
      players: matchState.players, stats: matchState.stats, log: matchState.log, round: matchState.round,
      selectedUid: matchState.selectedUid, deckTotals: matchState.deckTotals,
      leaderDefId: matchState.leaderDefId, leaderUid: matchState.leaderUid,
      asyncGhost: matchState.asyncGhost || null, asyncStage: matchState.asyncStage, opponentName: matchState.opponentName,
    }));
  }catch(e){ /* storage unavailable/full — non-fatal, the match just won't survive a reload */ }
}
function loadAsyncMatchState(){
  try{ const raw = localStorage.getItem(ASYNC_MATCH_KEY); return raw ? JSON.parse(raw) : null; }catch(e){ return null; }
}
function clearAsyncMatchState(){ try{ localStorage.removeItem(ASYNC_MATCH_KEY); }catch(e){} }
function resumeAsyncMatch(){
  const snap = loadAsyncMatchState();
  if(!snap){ alert('No saved Async Arena match found.'); renderPlay(); return; }
  const engine = makeSimEngine(getCardDefs(), nextMatchRng(), {recordEvents:true});
  const sideOf = id=> id===1?'A':'B';
  matchState = {engine, players:snap.players, sideOf, stats:snap.stats||{}, over:false, winner:0, selectedUid:snap.selectedUid||null,
    log:snap.log||[], round:snap.round||1, resolving:false, mode:'async', active:1, turnDone:{1:false,2:false}, awaitingPass:false,
    deckTotals: snap.deckTotals || {1:snap.players[1].deck.length, 2:snap.players[2].deck.length}, speedMult: snap.speedMult||1,
    leaderDefId: snap.leaderDefId||null, leaderUid: snap.leaderUid||null,
    asyncGhost: snap.asyncGhost||null, asyncStage: snap.asyncStage, opponentName: snap.opponentName};
  renderPlay();
}
function saveAndExitAsyncMatch(){ SoundKit.stopAll(); saveAsyncMatchState(); matchState = null; renderPlay(); }
/* ---- Abandoned-match resume (2026-10-03, per explicit request: "If there was a previously
   abandoned game, continue with that game"). Any vs-AI-style match (Test Battle, Conquest,
   Gauntlet, Tutorial) snapshots itself after every render while it's in progress; closing the tab
   mid-fight leaves that snapshot behind, and the next launch drops you straight back in.
   Quitting on purpose (or finishing) clears it. Async Arena keeps its own separate save. ---- */
const RESUME_KEY = 'bramblewood_resume_match_v1';
const RESUMABLE_MODES = new Set(['ai','conquest','gauntlet','tutorial','pvp']);
const RESUME_FIELDS = ['players','stats','round','selectedUid','deckTotals','leaderDefId','leaderUid','mode','conquestNode','battleMode','gladiatorLeaderDefs','tutorialStage','tutorialFaction','tutorialArrangedIds','gauntletWins','opponentName','speedMult','pvpGhost','pvpStage','asyncGhost','asyncStage','enemyBehaviour','drawOffered'];
function saveResumeSnapshot(){
  const m = matchState;
  if(!m || !RESUMABLE_MODES.has(m.mode) || m.resolving) return;
  if(m.over){ clearResumeSnapshot(); return; }
  try{ const snap = {savedAt: Date.now(), log: (m.log||[]).slice(-60)}; RESUME_FIELDS.forEach(k=>{ if(m[k]!==undefined) snap[k] = m[k]; }); localStorage.setItem(RESUME_KEY, JSON.stringify(snap)); }catch(e){}
}
function clearResumeSnapshot(){ try{ localStorage.removeItem(RESUME_KEY); }catch(e){} }
function loadResumeSnapshot(){
  try{ const snap = JSON.parse(localStorage.getItem(RESUME_KEY)||'null'); if(!snap || !snap.players || !RESUMABLE_MODES.has(snap.mode)) return null;
    if(Date.now() - (snap.savedAt||0) > 3*24*3600*1000){ clearResumeSnapshot(); return null; } return snap; }catch(e){ return null; }
}
// Story pass 2026-10-03 (US-07): an unfinished fight is OFFERED, not forced — Home opens with a
// small "Resume / Discard" card instead of dropping you straight back into the match.
const RESUME_MODE_LABEL = {pvp:'PvP fight', ai:'Quick Battle', conquest:'Conquest fight', gauntlet:'Gauntlet fight', tutorial:'tutorial fight'};
function tryResumeAbandonedMatch(){
  const snap = loadResumeSnapshot(); if(!snap) return false;
  switchTab('home');
  document.querySelectorAll('.resume-offer').forEach(e=> e.remove());
  const card = document.createElement('div');
  card.className = 'resume-offer'; card.setAttribute('role', 'dialog'); card.setAttribute('aria-label', 'Unfinished fight');
  const what = (snap.conquestNode && snap.conquestNode.name) ? `${snap.conquestNode.name} (${RESUME_MODE_LABEL[snap.mode]||'fight'})` : (RESUME_MODE_LABEL[snap.mode] || 'fight');
  card.innerHTML = `<div class="ro-ico">⏸️</div><div class="ro-body"><div class="ro-title">You have an unfinished fight</div>
    <div class="ro-sub">${escapeHtml(what)} · round ${snap.round||1}</div></div>
    <div class="ro-actions"><button type="button" class="btn small ghost" id="roDiscard">Discard</button><button type="button" class="btn small primary" id="roResume">▶ Resume</button></div>`;
  document.body.appendChild(card);
  card.querySelector('#roResume').onclick = ()=>{ card.remove(); resumeAbandonedMatchNow(); };
  card.querySelector('#roDiscard').onclick = ()=>{ card.remove(); clearResumeSnapshot(); showToast('Unfinished fight discarded.'); };
  setTimeout(()=>{ try{ card.querySelector('#roResume').focus(); }catch(e){} }, 50);
  return true;
}
function resumeAbandonedMatchNow(){
  const snap = loadResumeSnapshot(); if(!snap) return false;
  try{
    const engine = makeSimEngine(getCardDefs(), nextMatchRng(), {recordEvents:true, battleMode: snap.battleMode || 'gravity'});
    matchState = Object.assign({engine, sideOf:id=> id===1?'A':'B', over:false, winner:0, log:snap.log||[], resolving:false, active:1, turnDone:{1:false,2:false}, awaitingPass:false, speedMult:1}, snap);
    delete matchState.savedAt;
    lastBoardSig = {1:null, 2:null}; knownBoardUids = new Set();
    switchTab('play');
    showToast('▶️ Picking up your unfinished match where you left off.');
    return true;
  }catch(e){ console.error('[Bramblewood] resume failed', e); clearResumeSnapshot(); matchState = null; return false; }
}
function renderArenaSubTab(body){
  const resumable = !!loadAsyncMatchState();
  const dungeonRun = loadDungeonRun();
  const dungeonStageLabel = dungeonRun ? dungeonRun.stage : 1;
  const dungeonNodesHTML = [1,2,3].map(n=>{
    const cls = n<dungeonStageLabel ? 'cleared' : (n===dungeonStageLabel ? 'current' : 'locked');
    const connector = n<3 ? `<span class="dungeon-node-connector ${n<dungeonStageLabel?'cleared':''}"></span>` : '';
    return `<span class="dungeon-node ${cls}">${n}</span>${connector}`;
  }).join('');
  const dungeonStatusHTML = dungeonRun ? `<div class="dungeon-status-line">Stage ${dungeonRun.stage}/${DUNGEON_STAGE_COUNT} · Castle: ${dungeonRun.castleHp!=null?Math.max(0,dungeonRun.castleHp):'Full'} HP · ${dungeonDeckCount(dungeonRun)} cards left in deck</div>` : '';
  body.innerHTML = `
    <div class="panel" style="text-align:center;">
      <p class="panel-sub">${deckSizeBadgeHTML(myDeckCounts)} · ${(CHARACTER_DEFS[myCharacterId]||{}).name||'—'}</p>
      <!-- 2026-09-26 (user report, screenshot: "the cards are all over the place. make them
           consistently sized") — these used to be five separate .arena-mode-row flex containers,
           one per mode-group, each centering and sizing its own 1-3 buttons independently with a
           DIFFERENT min-width per variant (210/230/230/230px) and a different .amb-sub max-width
           per variant (180/210/230/210px). That's what actually produced the "all over the place"
           look: Test Battle/vs PC/Async Arena could only ever size themselves relative to each
           other inside their own shared row, while Gauntlet/Dungeon/Ranked each lived alone in
           their own separate row at a different width, with no shared sizing rule tying any of
           them together. Replaced with ONE .arena-mode-grid (CSS grid, equal-width columns that
           genuinely stretch every cell to match) so every mode tile — plain button or the more
           complex Dungeon panel alike — is really the same size, however many end up sharing a
           row at a given screen width. -->
      ${resumable?`<div class="arena-group"><div class="arena-mode-grid"><button class="btn primary big arena-mode-btn" id="continueAsyncBtn">
          <span class="amb-ico">▶️</span><span class="amb-lbl">Continue</span><span class="amb-sub">Your saved match</span></button></div></div>`:''}
      <div class="arena-group"><h3 class="arena-group-h">Practice</h3><div class="arena-mode-grid arena-practice-grid">
        <button class="btn primary big arena-mode-btn arena-hero" id="startVsAiBtn"><span class="amb-ico">🤖</span><span class="amb-lbl">Quick Battle</span><span class="amb-sub">You vs the computer · costs no Energy</span></button>
        <button class="btn primary big arena-mode-btn" id="startVsPcBtn"><span class="amb-ico">👥</span><span class="amb-lbl">Pass &amp; Play</span><span class="amb-sub">Two players, one device</span></button>
      </div></div>
      <div class="arena-group"><h3 class="arena-group-h">Challenges</h3><div class="arena-mode-grid">
        <button class="btn primary big arena-mode-btn gauntlet-mode-btn" id="startGauntletBtn">
          <span class="amb-ico">🏅</span><span class="amb-lbl">Gauntlet</span><span class="amb-sub">Win ${GAUNTLET_GOAL} in a row</span>
          <span class="gauntlet-streak-line">🔥 ${loadGauntletStreak()} / ${GAUNTLET_GOAL} · best ${loadGauntletBest()}</span>
        </button>
        <div class="arena-mode-btn dungeon-panel" id="dungeonPanel">
          <span class="amb-ico">🗝️</span><span class="amb-lbl">Dungeon</span>
          <span class="amb-sub">3 fights; losses carry over</span>
          <div class="dungeon-node-row">${dungeonNodesHTML}</div>
          ${dungeonStatusHTML}
          <div class="dungeon-panel-actions">
            <button class="btn primary" id="startDungeonBtn">${dungeonRun?'Continue Run':'Enter Dungeon'}</button>
            ${dungeonRun?`<button class="btn ghost" id="abandonDungeonBtn">Abandon Run</button>`:''}
          </div>
        </div>
      </div></div>
      <div class="arena-group"><h3 class="arena-group-h">Online</h3><div class="arena-mode-grid">
        ${pvpTileHTML()}
        ${liveQueueing ? `
        <div class="arena-mode-btn live-queue-status" id="liveQueueStatus">
          <span class="amb-ico">🔎</span><span class="amb-lbl">Searching…</span>
          <span class="amb-sub">Matching by rating</span>
          <button class="btn ghost" id="cancelLiveQueueBtn" style="margin-top:8px;">Cancel</button>
        </div>` : `
        <button class="btn primary big arena-mode-btn live-ranked-mode-btn" id="startLiveRankedBtn">
          <span class="amb-ico">⚡</span><span class="amb-lbl">Ranked Live</span><span class="amb-sub">Real players, real time</span>
        </button>`}
      </div></div>
      ${recentOpponentsPlayerHTML()}
    </div>`;
  document.getElementById('startVsAiBtn').addEventListener('click', ()=> startMatch('ai'));
  document.getElementById('startVsPcBtn').addEventListener('click', ()=> startMatch('pc'));
  const asyncBtn = document.getElementById('startAsyncBtn'); if(asyncBtn) asyncBtn.addEventListener('click', ()=> { clearAsyncMatchState(); startMatch('async'); });
  const pvpBtn = document.getElementById('startPvpBtn'); if(pvpBtn) pvpBtn.addEventListener('click', ()=> startMatch('pvp'));
  document.getElementById('startGauntletBtn').addEventListener('click', ()=> startMatch('gauntlet'));
  document.getElementById('startDungeonBtn').addEventListener('click', startDungeonFight);
  const abandonDungeonBtn = document.getElementById('abandonDungeonBtn');
  if(abandonDungeonBtn) abandonDungeonBtn.addEventListener('click', ()=>{
    if(confirm('Abandon this Dungeon run? Your progress and any carried-over losses will be cleared, but nothing further will be lost.')){
      clearDungeonRun();
      renderArenaSubTab(body);
    }
  });
  if(resumable) document.getElementById('continueAsyncBtn').addEventListener('click', resumeAsyncMatch);
  const liveBtn = document.getElementById('startLiveRankedBtn'); if(liveBtn) liveBtn.addEventListener('click', findLiveRankedMatch);
  body.querySelectorAll('[data-ro-view]').forEach(b=> b.addEventListener('click', ()=> openRecentOpponentDeck(+b.dataset.roView)));
  const cancelLiveBtn = document.getElementById('cancelLiveQueueBtn'); if(cancelLiveBtn) cancelLiveBtn.addEventListener('click', cancelLiveRankedQueue);
}

// ==== Conquest / Raid (2026-09-16, per explicit request) ====================================
// A map-based PvE campaign: a vertical pane of maps on the left, a central window of that
// map's skirmish nodes (regular Skirmish / Elite / Boss / Raid Boss), each a preset enemy
// deck+character piloted by the existing AI. Progress (which nodes are cleared, which Raid
// Bosses have been permanently unlocked) persists in this browser, matching the Async Arena
// precedent (localStorage, not the live shared card database — this is personal progress,
// not shared game content). Beating a Raid Boss node unlocks it permanently in the separate
// Raid tab for repeat fights; regular/Elite/Boss nodes stay in Conquest.
//
// Enemy decks below deliberately reuse existing, already-verified card ids (several already
// used by the vs-AI DEFAULT_DECK) rather than inventing new ones, and escalate in power
// tier by tier (plain Skirmish -> Elite -> Boss -> Raid Boss) via both stronger card mixes
