// Roll Table editor (2026-09-24, per explicit request: "do the pack animation and table for
// rolls. Also, let me edit the table for rolls in an admin-only website"): edits the Shop's pack
// odds/costs table (getShopPacks()/SHOP_PACKS_DEFAULT above) in place, persisted as a localStorage
// override so it survives reloads without touching the shipped default array. Admin-Mode-only
// (see adminModeEnabled) — explicitly framed by the request itself as a stopgap until a real
// server-side admin app exists, so this stays a plain inline editable table, not a fancy form.
function renderRollTableAdminHTML(){
  const packs = getShopPacks();
  const rows = packs.map((p,i)=>`
    <tr data-packidx="${i}">
      <td><input type="text" class="rt-name" value="${escapeAttr(p.name)}" class="w-120"></td>
      <td><input type="number" class="rt-cost-gold" value="${p.cost.gold||0}" min="0" class="w-64"></td>
      <td><input type="number" class="rt-cost-gems" value="${p.cost.gems||0}" min="0" class="w-60"></td>
      <td><input type="number" class="rt-dust" value="${p.dust||0}" min="0" class="w-60"></td>
      <td><input type="number" class="rt-metal" value="${p.metal||0}" min="0" class="w-52"></td>
      <td><input type="number" class="rt-levelchance" value="${p.levelChance||0}" min="0" max="1" step="0.01" class="w-64"></td>
      <td><input type="number" class="rt-unlockchance" value="${p.unlockChance||0}" min="0" max="1" step="0.01" class="w-64"></td>
    </tr>`).join('');
  return `<div class="panel admin-subpanel">
      <h3>🎲 Roll Table — Shop pack odds</h3>
      <p class="panel-sub">Edits what each Shop pack costs and pays out. Chances are 0–1 (e.g. 0.3 = 30%). Saves to this device only.</p>
      <div style="overflow-x:auto;">
        <table class="rt-table" id="rollTableEditor" style="width:100%; border-collapse:collapse; font-size:13px;">
          <thead><tr>
            <th style="text-align:left;">Pack</th><th>Maple Leaves</th><th>Gold Leaves</th><th>✨ Magic Dust</th><th>🔩 Metal</th><th>Level %</th><th>Unlock %</th>
          </tr></thead>
          <tbody>${rows}</tbody>
        </table>
      </div>
      <div style="display:flex; gap:8px; margin-top:10px;">
        <button class="btn primary small" id="rtSaveBtn" type="button">💾 Save roll table</button>
        <button class="btn small ghost" id="rtResetBtn" type="button">↺ Reset to defaults</button>
      </div>
      <p class="panel-sub" id="rtSavedLine" style="margin-top:6px;"></p>
    </div>`;
}
function wireRollTableAdmin(){
  const saveBtn = document.getElementById('rtSaveBtn');
  if(!saveBtn) return; // panel only exists in the DOM when Admin Mode is on
  saveBtn.addEventListener('click', ()=>{
    const packs = getShopPacks().map(p=>({...p, cost:{...p.cost}}));
    document.querySelectorAll('#rollTableEditor tbody tr[data-packidx]').forEach(tr=>{
      const i = Number(tr.getAttribute('data-packidx'));
      if(!packs[i]) return;
      packs[i] = {
        ...packs[i],
        name: tr.querySelector('.rt-name').value || packs[i].name,
        cost: { gold: Math.max(0, Number(tr.querySelector('.rt-cost-gold').value)||0), gems: Math.max(0, Number(tr.querySelector('.rt-cost-gems').value)||0) },
        dust: Math.max(0, Number(tr.querySelector('.rt-dust').value)||0),
        metal: Math.max(0, Number(tr.querySelector('.rt-metal').value)||0),
        levelChance: Math.min(1, Math.max(0, Number(tr.querySelector('.rt-levelchance').value)||0)),
        unlockChance: Math.min(1, Math.max(0, Number(tr.querySelector('.rt-unlockchance').value)||0)),
      };
    });
    saveShopPacksOverride(packs);
    const line = document.getElementById('rtSavedLine');
    if(line) line.textContent = `✓ Saved ${new Date().toLocaleTimeString()} — the Shop now uses this table.`;
  });
  const resetBtn = document.getElementById('rtResetBtn');
  if(resetBtn) resetBtn.addEventListener('click', ()=>{
    if(!confirm('Reset the Roll Table back to its shipped defaults?')) return;
    resetShopPacksOverride();
    renderAdmin();
  });
}
