  if(!lightningTimer) try{ scheduleLightning(matchState); }catch(e){}
  try{ maybeDeckShuffle(matchState); }catch(e){}
  try{ Ambience.play(ambienceKindForMatch(matchState)); }catch(e){}
  const logHud = document.getElementById('battleLogHudBtn');
  if(logHud) logHud.addEventListener('click', ()=>{ const t = document.getElementById('battleLogToggle'); if(t) t.click(); });
  const battleLogToggle = document.getElementById('battleLogToggle');
  if(battleLogToggle) battleLogToggle.addEventListener('click', ()=>{
    battleLogOpen = !battleLogOpen;
    const panel = battleLogToggle.closest('.battle-log-panel');
    if(panel) panel.classList.toggle('collapsed', !battleLogOpen);
    const chevron = battleLogToggle.querySelector('.battle-log-chevron');
    if(chevron) chevron.textContent = battleLogOpen ? '▾' : '▸';
  });
  // Direct-to-battlefield drop target (2026-09-17, per explicit request: "Dragging the card
  // Left right of the actual field or in the centre position should ALSO play the card") —
  // the active player's own board row now accepts a drop directly, not just the dedicated
  // Left/Right buttons below it. Which physical row is "theirs" depends on whose turn it is
  // (bottom row in vs-AI and whenever it's Player 1's turn in hot-seat; top row when it's
  // Player 2's turn in hot-seat — see the topLabel/bottomLabel split in renderMatchUI), so
  // it's resolved fresh here rather than hardcoded to #rowMine. Side is picked purely from
  // which half of the row the drop lands in (left half -> left flank, right half -> right
