function matchStatsHTML(m){
  const totals = computeMatchStats(m);
  // 'dealt'/'biggestHit': higher is better (gold-highlighted). 'taken': LOWER is better, since
  // absorbing less damage is the good outcome — flipped explicitly rather than reusing the same
  // comparison, so a side that dealt more damage doesn't also get highlighted for "winning" at
  // taking more of it too.
  const rows = [
    {label:'Total Damage Dealt', key:'dealt', higherIsBetter:true},
    {label:'Total Damage Taken', key:'taken', higherIsBetter:false},
    {label:'Biggest Hit', key:'biggestHit', higherIsBetter:true},
  ];
  const cellCls = (r)=>{
    const a = totals.A[r.key], b = totals.B[r.key];
    if(a===b) return {A:'', B:''};
    const aWins = r.higherIsBetter ? a>b : a<b;
    return {A: aWins?'wls-best':'', B: aWins?'':'wls-best'};
  };
  // Conquest rewards (item #4 rank, item #6 Metal, 2026-09-20 gold/dust payout) — only ever set
  // on a real Conquest win (see resolveRound()'s own comment), so this stays empty for
  // Arena/Simulator matches.
  const reward = m.conquestRewardEarned;
  const rewardsHTML = m.conquestRankEarned ? `<div class="winloss-conquest-rewards">
      <span class="conquest-rank-badge rank-${m.conquestRankEarned}" title="Graded on how much of your own castle HP you still had left">Rank ${m.conquestRankEarned}</span>
      ${reward && reward.isFirstClear ? `<span class="conquest-firstclear-badge" title="First time clearing this node — a bigger one-off bonus">✨ First Clear</span>` : ''}
      ${reward && reward.gold>0 ? `<span class="hud-pill forge-cur-gold" title="${reward.isFirstClear?'First-clear bonus':'Repeat-clear payout'}">${mapleLeafIconHTML()} ${rewardCountSpan(reward.gold)} Maple Leaves</span>` : ''}
      ${reward && reward.dust>0 ? `<span class="hud-pill forge-cur-dust" title="${reward.isFirstClear?'First-clear bonus':'Repeat-clear payout'}">✨ ${rewardCountSpan(reward.dust)} Dust</span>` : ''}
      ${m.conquestMetalEarned ? `<span class="hud-pill forge-cur-metal" title="Defeating a named Conquest leader (Boss/Raid Boss) pays out Metal">🔩 ${rewardCountSpan(m.conquestMetalEarned)} Metal</span>` : ''}
      ${(m.conquestCardsEarned||[]).map(id=>{ const cd = getCardDefs()[id]; return cd ? `<span class="hud-pill" title="New card unlocked">🃏 ${escapeHtml(cd.name)}</span>` : ''; }).join('')}
    </div>` : '';
  // Online Raid rewards + rank movement (2026-09-22) — separate block since a raid match never
  // sets conquestRankEarned (it isn't a Conquest node at all).
  const raidReward = m.raidRewardEarned;
  const raidHTML = (m.mode==='raidOnline' && m.raidRankAfter) ? `<div class="winloss-conquest-rewards">
      <span class="conquest-rank-badge" title="Your ranked tier after this fight">${m.raidRankAfter.label}</span>
      <span class="hud-pill ${m.raidRatingDelta>=0?'raid-rating-up':'raid-rating-down'}" title="Rating change from this fight">${m.raidRatingDelta>=0?'▲':'▼'} ${Math.abs(m.raidRatingDelta)} rating</span>
      ${raidReward && raidReward.gold>0 ? `<span class="hud-pill forge-cur-gold" title="Raid win payout">${mapleLeafIconHTML()} ${rewardCountSpan(raidReward.gold)} Maple Leaves</span>` : ''}
      ${raidReward && raidReward.dust>0 ? `<span class="hud-pill forge-cur-dust" title="Raid win payout">✨ ${rewardCountSpan(raidReward.dust)} Dust</span>` : ''}
      ${raidReward && raidReward.metal>0 ? `<span class="hud-pill forge-cur-metal" title="Raid win payout">🔩 ${rewardCountSpan(raidReward.metal)} Metal</span>` : ''}
    </div>` : '';
  // Gauntlet streak (#274, 2026-09-25) — parallel to the Conquest/Raid reward blocks above,
  // keyed on m.gauntletStreakAfter being set (only true for mode==='gauntlet', by resolveRound's
  // own gauntlet branch above).
  const pReward = m.pvpRewardEarned;
  const pvpHTML = (m.mode==='pvp' && pReward) ? `<div class="winloss-conquest-rewards">
      <span class="hud-pill ${m.pvpRatingDelta>=0?'raid-rating-up':'raid-rating-down'}">${m.pvpRatingDelta>=0?'▲':'▼'} ${Math.abs(m.pvpRatingDelta)} rating</span>
      <span class="hud-pill forge-cur-gold">${mapleLeafIconHTML()} ${rewardCountSpan(pReward.gold)} Maple Leaves</span>
      ${pReward.dust ? `<span class="hud-pill forge-cur-dust">✨ ${rewardCountSpan(pReward.dust)} Dust</span>` : ''}
      <span class="hud-pill">🎟️ ${pvpTicketsLeft()}/${PVP_TICKETS_PER_DAY} tickets left</span>
    </div>` : '';
  const aReward = m.asyncRewardEarned;
  const asyncHTML = (m.mode==='async' && m.asyncRunAfter) ? `<div class="winloss-conquest-rewards">
      ${m.asyncRunComplete ? `<span class="conquest-rank-badge">${m.asyncRunAfter.wins>=Ghosts.ASYNC.MAX_WINS ? '🏅 Perfect run!' : '🏁 Run over'} · ${m.asyncRunAfter.wins}W–${m.asyncRunAfter.losses}L</span>` : `<span class="conquest-rank-badge" title="This Async Arena run">📨 Run: ${m.asyncRunAfter.wins}W–${m.asyncRunAfter.losses}L</span>`}
      ${aReward && aReward.gold>0 ? `<span class="hud-pill forge-cur-gold">${mapleLeafIconHTML()} ${rewardCountSpan(aReward.gold)} Maple Leaves</span>` : ''}
      ${aReward && aReward.dust>0 ? `<span class="hud-pill forge-cur-dust">✨ ${rewardCountSpan(aReward.dust)} Dust</span>` : ''}
      ${aReward && aReward.metal>0 ? `<span class="hud-pill forge-cur-metal">🔩 ${rewardCountSpan(aReward.metal)} Metal</span>` : ''}
    </div>` : '';
  const orReward = m.raidRewardEarned;
  const raidOfflineHTML = (m.mode==='raidOffline' && m.raidDamageDealt!=null) ? `<div class="winloss-conquest-rewards">
      <span class="conquest-rank-badge">${m.raidOverwhelmed ? '💥 Overwhelm! ' : '⚔️ '}${Number(m.raidDamageDealt).toLocaleString()} damage to ${escapeHtml(m.raidBoss.name)}</span>
      <span class="hud-pill" title="Shared raid HP left this week">❤️ ${m.raidRemainingAfter} HP left${m.raidRemainingAfter<=0?' — defeated!':''}</span>
      ${orReward && orReward.gold>0 ? `<span class="hud-pill forge-cur-gold">${mapleLeafIconHTML()} ${rewardCountSpan(orReward.gold)} Maple Leaves</span>` : ''}
      ${orReward && orReward.dust>0 ? `<span class="hud-pill forge-cur-dust">✨ ${rewardCountSpan(orReward.dust)} Dust</span>` : ''}
    </div>` : '';
  const gReward = m.gauntletRewardEarned;
  const gauntletHTML = (m.mode==='gauntlet' && m.gauntletStreakAfter!=null) ? `<div class="winloss-conquest-rewards">
      ${m.gauntletRunComplete ? `<span class="conquest-rank-badge" title="You won ${GAUNTLET_GOAL} in a row!">🏅 Run Complete!</span>` : `<span class="conquest-rank-badge" title="Current Gauntlet win streak">🔥 Streak: ${m.gauntletStreakAfter}/${GAUNTLET_GOAL}</span>`}
      <span class="hud-pill" title="Best Gauntlet streak so far">🏆 Best: ${m.gauntletBestAfter}</span>
      ${gReward && gReward.gold>0 ? `<span class="hud-pill forge-cur-gold" title="Gauntlet win payout">${mapleLeafIconHTML()} ${rewardCountSpan(gReward.gold)} Maple Leaves</span>` : ''}
      ${gReward && gReward.dust>0 ? `<span class="hud-pill forge-cur-dust" title="Gauntlet win payout">✨ ${rewardCountSpan(gReward.dust)} Dust</span>` : ''}
      ${gReward && gReward.metal>0 ? `<span class="hud-pill forge-cur-metal" title="Run Complete bonus">🔩 ${rewardCountSpan(gReward.metal)} Metal</span>` : ''}
    </div>` : '';
  // Ranked 1v1 Live (#277) — m.liveRankAfter/liveRatingDelta are only ever set on the HOST
  // (resolveRound's liveRanked branch, which — per the module header comment above it — only
  // ever actually runs on the host client). The peer's own rating DOES still get updated
  // server-side by that same RPC call, just not reflected in ITS post-match card the instant
  // the match ends — a known small gap (would need the host to compute and broadcast the
  // peer's own delta back specifically), so the peer gets an honest "check Ranking" note
  // instead of a silently-missing/wrong number.
  const liveHTML = (m.mode!=='liveRanked') ? '' : (m.liveRankAfter ? `<div class="winloss-conquest-rewards">
      <span class="conquest-rank-badge" title="Your ranked tier after this match">${m.liveRankAfter.label}</span>
      <span class="hud-pill ${m.liveRatingDelta>=0?'raid-rating-up':'raid-rating-down'}" title="Rating change from this match">${m.liveRatingDelta>=0?'▲':'▼'} ${Math.abs(m.liveRatingDelta)} rating</span>
      ${m.liveOpponentName ? `<span class="hud-pill" title="Who you played">vs ${escapeAttr(m.liveOpponentName)}</span>` : ''}
    </div>` : `<div class="winloss-conquest-rewards">
      <span class="hud-pill" title="Your rating was updated server-side by the match host">Rating updated — check Ranking for your new tier</span>
    </div>`);
  // Dungeon (2026-09-26) — parallel to the Gauntlet block above, keyed on mode==='dungeon' (the
  // three outcome fields set by resolveRound()'s dungeon branch are mutually exclusive: exactly
  // one of dungeonRunComplete/dungeonRunFailed/dungeonStageAfter is truthy for any given fight).
  const dReward = m.dungeonRewardEarned;
  const dungeonHTML = (m.mode==='dungeon') ? `<div class="winloss-conquest-rewards">
      ${m.dungeonRunComplete ? `<span class="conquest-rank-badge" title="You cleared all ${DUNGEON_STAGE_COUNT} Dungeon fights!">🗝️ Dungeon Cleared!</span>`
        : m.dungeonRunFailed ? `<span class="conquest-rank-badge" title="The run ends here">💀 Run Failed — Stage ${m.dungeonStageReached}/${DUNGEON_STAGE_COUNT}</span>`
        : `<span class="conquest-rank-badge" title="On to the next Dungeon fight">➡️ Stage ${m.dungeonStageAfter}/${DUNGEON_STAGE_COUNT} next</span>`}
      ${!m.dungeonRunFailed && !m.dungeonRunComplete ? `<span class="hud-pill" title="Cards remaining in this run's deck, after any losses from this fight">🃏 ${m.dungeonDeckLeft} cards left</span>` : ''}
      ${dReward && dReward.gold>0 ? `<span class="hud-pill forge-cur-gold" title="Full clear payout">${mapleLeafIconHTML()} ${rewardCountSpan(dReward.gold)} Maple Leaves</span>` : ''}
      ${dReward && dReward.dust>0 ? `<span class="hud-pill forge-cur-dust" title="Full clear payout">✨ ${rewardCountSpan(dReward.dust)} Dust</span>` : ''}
      ${dReward && dReward.metal>0 ? `<span class="hud-pill forge-cur-metal" title="Full clear payout">🔩 ${rewardCountSpan(dReward.metal)} Metal</span>` : ''}
    </div>` : '';
  return `<div class="winloss-stats">
    ${(m.mode==='conquest' || m.mode==='tutorial') ? rewardsPanelHTML(m) : rewardsHTML}${raidHTML}${raidOfflineHTML}${pvpHTML}${asyncHTML}${gauntletHTML}${liveHTML}${dungeonHTML}
    <div class="winloss-stats-head"><span></span><span>${sideLabel('A')}</span><span>${sideLabel('B')}</span></div>
    ${rows.map(r=>{ const cls = cellCls(r); return `<div class="winloss-stats-row"><span class="wls-label">${r.label}</span><span class="wls-val ${cls.A}">${totals.A[r.key]}</span><span class="wls-val ${cls.B}">${totals.B[r.key]}</span></div>`; }).join('')}
  </div>`;
}
// 2026-09-26 ("is there any reward animation for finishing a skirmish, do it"): the win/loss
// modal's own mount already pops in with a spring overshoot (see the hasGsap() block in
// renderMatchUI above) and a real win already triggers starFallCelebration's falling stars +
// cha-ching chime — but the actual reward row (rank badge, "+150 Maple Leaves" etc, see
// matchStatsHTML above) was static markup with zero motion, the exact opposite of what a payout
// moment should feel like. Pops each badge/pill in with its own staggered spring (so a Dungeon
// full-clear's 3 currency pills read as a little cascade, not one flat block) and counts every
// "+N" up from zero as its pill lands, rather than just having the final number already there.
// Called once per match end from the same hasGsap() mount block (icoEl bounce et al.) so it never
// re-fires on an incidental re-render while the modal is still up (that whole block is already
// gated behind !m.winCelebrated one level up).
function wireWinLossRewardAnim(){
  const rewardsEl = document.querySelector('.winloss-conquest-rewards');
  if(!rewardsEl) return;
  const pieces = Array.from(rewardsEl.children);
  if(!pieces.length) return;
  gsap.set(pieces, {opacity:0, scale:.5, y:10});
  gsap.to(pieces, {opacity:1, scale:1, y:0, duration:.5, ease:'back.out(2.6)', stagger:.13, delay:.5});
  pieces.forEach((el, i)=>{
    el.querySelectorAll('.reward-count').forEach((countEl, j)=>{
      const target = parseInt(countEl.getAttribute('data-target'), 10);
      if(!target) return;
      const counter = {n:0};
      gsap.to(counter, {n:target, duration:.6, delay:.5+i*.13+.12+j*.08, ease:'power2.out',
        onUpdate: ()=>{ countEl.textContent = '+'+Math.round(counter.n); },
        onComplete: ()=>{ countEl.textContent = '+'+target; }
      });
    });
  });
  rewardsCheer();
}
function logText(ev){
  const defs = getCardDefs();
  const nm = id=> defs[id] ? `${defs[id].icon} ${defs[id].name}` : id;
  switch(ev.type){
    case 'play': return {cls:'', text:`${sideLabel(ev.side)} played ${nm(ev.defId)}.`};
    case 'discard': {
      const meta = PITCH_RESOURCE_META[ev.resource] || PITCH_RESOURCE_META.lumber;
      const amt = ev.amount!=null ? ev.amount : 1; // legacy replay events (pre-Stone) had no resource/amount fields — they were always +1 gold
      return {cls:'', text:`${sideLabel(ev.side)} discarded ${nm(ev.defId)} for +${amt} ${meta.glyph}.`};
    }
    // 2026-09-20 (explicit bug report: "it should say 'Enemy drew a card' in our battle log as
    // we don't know what they drew"): the enemy's hand is hidden information — naming the exact
    // card it drew leaked something the player has no legitimate way to see. Only the player's
    // OWN draw (side 'A') still names the card; the enemy's stays generic.
    case 'draw': return {cls:'', text: ev.side==='A' ? `${sideLabel(ev.side)} drew ${nm(ev.defId)}.` : `${sideLabel(ev.side)} drew a card.`};
    case 'overdraw': return {cls:'', text: `${sideLabel(ev.side)} had a full hand — ${nm(ev.defId)} went to the graveyard for +${ev.lumber||1} 🪵.`};
    case 'hit': {
      // Elemental conversion note (2026-09-29): Poison zeroes ev.dmg out entirely (the whole
      // amount became poison stacks instead), so without this the log would just read "hit for
      // 0" with no explanation. Decay still shows its real ev.dmg plus the extra ATK-drain note.
      let elemNote = '';
      if(ev.elementalConvert==='poison') elemNote = ` — converted to ${ev.elementalAmount} Poison ☠ instead of direct damage`;
      else if(ev.elementalConvert==='decay') elemNote = ` (also -${ev.elementalAmount} Attack, Decay 🦠)`;
      return {cls:ev.armorBlocked?'armor':'', text:`${nm(ev.attDefId)} hit ${nm(ev.targetDefId)} for ${ev.dmg}${ev.armorBlocked?' — blocked to 0 by Armor! 🛡':''}${ev.rend?' (Rend — Armor bypassed) 🗡':''}${ev.crit?' 💥 Crit!':''}${ev.festerBonus?` (+${ev.festerBonus} Fester ☠)`:''}${ev.ruptureBonus?` (+${ev.ruptureBonus} Rupture 🩸)`:''}${ev.swipe?' (swipe)':''}${ev.sweep?' (sweep)':''}${elemNote}.`};
    }
    case 'hitHQ': return {cls:'', text:`${nm(ev.attDefId)} struck ${matchState&&matchState.mode==='pc' ? (ev.targetSide==='A'?"Player 1's":"Player 2's") : (ev.targetSide==='A'?'your':'the enemy')} HQ for ${ev.dmg}${ev.swipe?' (swipe)':''}.`};
    case 'thorns': return {cls:'', text:`${nm(ev.fromDefId)}'s Thorns reflected ${ev.dmg} onto ${nm(ev.targetDefId)}. 🌵`};
    case 'reflect': return {cls:'', text:`${nm(ev.fromDefId)}'s Reflect threw ${ev.dmg} damage back at ${nm(ev.targetDefId)}. 🪞`};
    case 'pierceHQ': return {cls:'', text:`${nm(ev.attDefId)}'s Pierce punched through for ${ev.dmg} bonus damage to ${matchState&&matchState.mode==='pc' ? (ev.targetSide==='A'?"Player 1's":"Player 2's") : (ev.targetSide==='A'?'your':'the enemy')} HQ. 🗡`};
    case 'overwhelmHQ': return {cls:'', text:`${nm(ev.attDefId)}'s Overwhelm spilled ${ev.dmg} bonus damage into ${matchState&&matchState.mode==='pc' ? (ev.targetSide==='A'?"Player 1's":"Player 2's") : (ev.targetSide==='A'?'your':'the enemy')} HQ. 💥`};
    case 'gash': return {cls:'bleed', text:`${nm(ev.attDefId)}'s Gash tore into ${nm(ev.targetDefId)} for +${ev.amount} bleed. 🩸`};
    case 'blindMiss': return {cls:'', text:`${nm(ev.attDefId)} swings blindly and misses entirely! 👁`};
    case 'poisonTick': return {cls:'poison', text:`${nm(ev.defId)} took ${ev.dmg} poison damage. 🫧`};
    case 'decayTick': return {cls:'poison', text:`${nm(ev.defId)} decayed for ${ev.dmg} damage and -${ev.atk} Attack. 🦠`};
    case 'bleedTick': return {cls:'bleed', text:`${nm(ev.defId)} took ${ev.dmg} bleed damage. 🩸`};
    case 'arrow': return {cls:'', text:`${nm(ev.defId)} looses ${ev.fire ? 'a flaming arrow 🔥🏹' : 'an arrow 🏹'}${ev.targetDefId ? ' at ' + nm(ev.targetDefId) : ' at the castle'}`};
    case 'revive': return {cls:'gold', text:`${nm(ev.defId)} refused to die — revived at 1 HP! ✨`};
    case 'collapseIn': return {cls:'', text:`${nm(ev.defId)} falls into the center from the ${ev.fromSide}. ➡`};
    case 'death': return {cls:'', text:`${nm(ev.defId)} died.`};
    case 'spawn': return {cls:'', text:`${nm(ev.defId)} ×${ev.count} spawned. 🐝`};
    case 'gold': return {cls:'gold', text:`${nm(ev.defId)} generated +${ev.amount} 🪙.`};
    case 'grace': return {cls:'grace', text:`${nm(ev.defId)} generated +${ev.amount} 🕊️.`};
    case 'devilry': return {cls:'devilry', text:`${nm(ev.defId)} generated +${ev.amount} ★.`};
    // 2026-09-21 ("battle log not perfected yet" — a follow-up audit): stone/lumber/elemental
    // energy generation had no case here at all, unlike their gold/grace/devilry siblings right
    // above — each one silently fell through to the bare `default: ev.type`, so a Structure or
    // any other card generating one of these three resources printed the literal word "stone",
    // "lumber", or "elementalEnergy" as its entire battle-log line instead of a real sentence.
    // Same icons floatResourceGain() already uses for these three (see renderVfxForEvent).
    case 'stone': return {cls:'gold', text:`${nm(ev.defId)} generated +${ev.amount} 🪨.`};
    case 'lumber': return {cls:'gold', text:`${nm(ev.defId)} generated +${ev.amount} 🪵.`};
    case 'elementalEnergy': return {cls:'gold', text:`${nm(ev.defId)} generated +${ev.amount} ✨.`};
    // 2026-09-21 audit: `heal` (a dedicated healer-target event, engine's fireHealAction — distinct
    // from `sap`'s attacker-heals-self-off-the-hit shape) had no case either, and `chainBreak`
    // (a Devilry-chained card's chains snapping, already given its own on-card flourish/sound —
    // see playChainBreakFlourish/SoundKit.chainBreak — but never a matching log line) likewise
    // fell through to the raw type-name default.
    case 'heal': return {cls:'heal', text:`${nm(ev.attDefId)} healed ${nm(ev.targetDefId)} for ${ev.amount} HP. 💚`};
    case 'chainBreak': return {cls:'gold', text:`${nm(ev.defId)}'s chains snapped — free to act again! ⛓`};
    case 'bounty': return {cls:'gold', text:`Bounty paid: +${ev.amount} 🪵 for slaying ${nm(ev.fromDefId)}.`}; // 2026-09-22: bounty pays Lumber now, not Gold
    case 'sap': return {cls:'heal', text:`${nm(ev.attDefId)} drained ${ev.amount} HP from the hit. 🩹`};
    case 'exile': return {cls:'exile', text:`${nm(ev.defId)} was exiled from ${ev.zone}. 🌫`};
    case 'render': return {cls:'', text:`${nm(ev.attDefId)} lowered ${nm(ev.targetDefId)}'s Attack by ${ev.amount}. 📉`};
    case 'evaded': return {cls:'', text:`${nm(ev.targetDefId)} evaded ${nm(ev.attDefId)}'s attack! 🌀`};
    case 'statusFx': {
      const kindText = {
        poison: `poisoned ${nm(ev.targetDefId)} (+${ev.amount} ☠)`,
        expose: `exposed ${nm(ev.targetDefId)} 🎯`,
        stun: `stunned ${nm(ev.targetDefId)} 💫`,
        debuffAttack: `lowered ${nm(ev.targetDefId)}'s Attack by ${ev.amount}`,
        scar: `scarred ${nm(ev.targetDefId)} (+${ev.amount} 🗡, permanent)`,
        cleanse: `cleansed itself of all ailments ✨`,
        grit: `toughened up from the fight (+${ev.amount}⚔, permanent) 💪`,
        blind: `blinded ${nm(ev.targetDefId)} 👁 (its next attacks may miss)`,
        shock: `shocked ${nm(ev.targetDefId)} ⚡ (+50% damage taken)`,
        corrode: `corroded ${nm(ev.targetDefId)}'s Attack by ${ev.amount} 🧪`,
        // freeze/sleep/paralyze/stunOnHit (2026-09-24, found while adding Stagger for task #109):
        // same gap this map's own comments already flag for bleed/esprit above — these four fell
        // through to the bare `|| ev.kind` fallback (a battle-log line reading literally "Card
        // froze."), unnoticed since they're rarer procs than the ever-present poison/bleed.
        freeze: `froze ${nm(ev.targetDefId)} ❄ (skips its next action)`,
        sleep: `put ${nm(ev.targetDefId)} to sleep 💤 (skips its next action, breaks on damage)`,
        paralyze: `paralyzed ${nm(ev.targetDefId)} ⚡ (may skip each round while active)`,
        stunOnHit: `stunned ${nm(ev.targetDefId)} 💫 (skips this round)`,
        // Stagger (2026-09-24, task #109 — the physical elemental status, Shock's mirror).
        stagger: `staggered ${nm(ev.targetDefId)} 💢 (-50% damage dealt)`,
        berserk: `flew into a berserk rage (+${ev.amount}⚔, permanent) 😡`,
        momentum: `surged with Momentum after the kill (+${ev.amount}⚔, permanent) 🔥`,
        // bleed/esprit (2026-09-21 coverage audit): the VFX/SFX side of both was fixed in the
        // batch that found them completely silent — this battle-log map had the exact same gap
        // (both fell through to the raw `|| ev.kind` fallback, printing the bare word "bleed" or
        // "esprit" as the whole sentence) and went unnoticed until this follow-up pass.
        bleed: `bled ${nm(ev.targetDefId)} (+${ev.amount} 🩸)`,
        esprit: `grew stronger from a new ally's arrival (+${ev.amount}⚔, permanent) 🤝`,
      }[ev.kind] || ev.kind;
      const cls = ev.kind==='poison' || ev.kind==='corrode' ? 'poison' : ev.kind==='bleed' ? 'bleed' : (ev.kind==='cleanse' || ev.kind==='grit' || ev.kind==='berserk' || ev.kind==='momentum' || ev.kind==='esprit') ? 'heal' : '';
      return {cls, text:`${nm(ev.attDefId)} ${kindText}.`};
    }
    case 'explode': return {cls:'exile', text:`${nm(ev.defId)}'s fuse ran out — 💥 ${ev.dmg} damage to ${ev.targetUid? nm(ev.targetDefId) : (ev.targetSide==='A'?'your HQ':'the enemy HQ')}!`};
    case 'namedBuff': return {cls:'gold', text:`${nm(ev.attDefId)} buffed ${nm(ev.targetDefId)} +${ev.amount}⚔${ev.amount2?`/+${ev.amount2}❤`:''}. 🐝`};
    case 'ready': return {cls:'', text:`${nm(ev.defId)} is ready to fight.`};
    case 'frenzy': return {cls:'quick', text:`${nm(ev.attDefId)}'s Frenzy triggers — attacking again! 🔥`};
    // 2026-09-20 (explicit bug report: "the battle log is missing some of the attack
    // transactions"): a card that was gathered as a candidate attacker but sat its turn out —
    // Reload cooldown, Stun, Frozen, Asleep, a failed Paralyze coin flip, still Chained, Shell
    // recovery, or debuffed to 0 Attack — used to produce NO log line at all, so a round could
    // visibly have fewer hit/hitHQ entries than ready-looking creatures on the field with
    // nothing explaining the gap. See gatherAttackers' new skipTurn() in the engine.
    case 'skipTurn': {
      const reasonText = {
        reload: 'is still reloading and sits this round out. 🔃',
        stunned: 'is stunned and can\'t act this round. 💫',
        frozen: 'is frozen solid and can\'t act. ❄',
        asleep: 'is fast asleep and can\'t act. 💤',
        paralyzed: 'is paralyzed and fails to act this round. ⚡',
        chained: 'is still chained and can\'t act. ⛓',
        shell: 'is recovering in its shell and can\'t act. 🐚',
        zeroAttack: 'has no Attack left to swing with.',
      }[ev.reason] || 'can\'t act this round.';
      return {cls:'', text:`${nm(ev.defId)} ${reasonText}`};
    }
    case 'roundStart': return {cls:'', text:`— Round ${ev.round} —`};
    case 'swapPositions': return {cls:'', text:`${nm(ev.attDefId)} scurries ${nm(ev.aDefId)} and ${nm(ev.bDefId)} out of position! 🔀`};
    default: return {cls:'', text: ev.type};
  }
}
function renderLogLine(ev){
  const log = document.getElementById('battleLog'); if(!log) return;
  // 2026-09-21 ("battle log not perfected yet" audit): waitTick had no case in logText() either,
  // so every single per-round Wait countdown tick — for EVERY card still on Wait, EVERY round —
  // was printing the raw literal text "waitTick" as its own battle-log line. Unlike the other
  // gaps just above (genuinely missing information), this one doesn't want a nicer sentence, it
  // wants to not be here at all: the countdown is already shown live on the card's own wait-ring
  // badge, and only the milestone moment (Wait hits 0 — the separate 'ready' event, which DOES
  // get a real log line below) is actually log-worthy. Left unfixed this would have flooded the
  // log with several "waitTick" lines every round in any match with more than one waiting card.
  if(ev.type==='waitTick') return;
  if(ev.type==='tkDivider'){ const d = document.createElement('div'); d.className = 'log-row tk-log-divider'; d.textContent = ev.text; log.appendChild(d); log.scrollTop = 0; return; }
  const {cls,text} = logText(ev);
  const row = document.createElement('div');
  row.className = 'log-row '+cls;
  row.textContent = text;
  log.appendChild(row);
  log.scrollTop = 0;
}
/* ---- attack "feel", GSAP-driven since 2026-09-16 ("improve the effects and gsap-like
   animations of the game"): every card that lands (or attempts) a hit reels back into a
   wind-up, then snaps forward into the strike — mine lunges up toward the enemy row, enemy
   lunges down toward mine — via a real GSAP timeline with spring/back easing, replacing the
   old CSS-keyframe-class + setTimeout-chain version. Ranged/missile sources also get a
   projectile glyph that physically travels from attacker to target, and a Guardian-redirected
   hit gets a shield flash on whoever actually ate it. A non-GSAP fallback (the original CSS
   version) is kept in every function below in case gsap somehow fails to load. ---- */
function hasGsap(){ return typeof gsap !== 'undefined'; }
// Pacing: base durations were "slowed 2x" once already (130/190/230 -> 260/380/460) and are
// now slowed another 1.5x on top ("overall animation should be 50% slower") for a base of
// 390/570/690, then divided by the player's chosen speed multiplier (see the ffBtn wiring in
// renderMatchUI and delayForEvent) so >> speeds the attack-feel animations up too, not just
// the gap between events. `death` is deliberately NOT derived from the same 1.5x slowdown —
// see delayForEvent's comment ("death animations can chain together 2x faster").
function animMs(){
  const mult = (matchState && matchState.speedMult) || 1;
  const sd = (ms, floor)=> Math.max(floor||40, Math.round(ms/mult));
  return { windup: sd(390,50), strike: sd(570,70), projectile: sd(690,70), impactPad: sd(180,30), death: sd(480,120) };
}
function boardCardEl(uid){ return document.querySelector(`.board-card[data-uid="${uid}"]`); }
// Task #125 (2026-09-17, "it should land there with some measurable impact! Then push the
// cards off"): a shared little "shove" tween for whichever board-cards sit immediately to the
// left/right of a card that just landed — they hop away a few px and spring back, so a landing
// reads as a physical nudge on the row rather than the new card just quietly appearing next to
// its neighbors. Reused by both the generic landing-impact flourish below and the more playful
// bee-drone spawn landing (task #126).
function pushNeighborCards(el, opts){
  opts = opts || {};
  if(!hasGsap() || !el) return;
  const row = el.closest('.board-row'); if(!row) return;
  const cards = [...row.querySelectorAll('.board-card[data-uid]')];
  const idx = cards.indexOf(el);
  const mult = (matchState && matchState.speedMult) || 1;
  const dist = opts.distance || 8;
  const dur = Math.max(.06, (opts.durationMs||220)/mult/1000);
  const shove = (target, dir)=>{
    const shoveUid = target.getAttribute && target.getAttribute('data-uid');
    // Cause G fix (see animateAttacker's own long comment for the full story): a neighbor being
    // shoved can ALSO simultaneously be a live Flip target (mid-reflow) — this neighbor-shove
    // tween shares the `x` property with Flip's own internal absolute-mode tween, so kicking it
    // off here (and the `gsap.killTweensOf(target,'x')` that used to precede it) would corrupt
    // Flip's shared timeline exactly the same way an overlapping attack lunge did. Skip the
    // shove for a currently-flipping neighbor — Flip's reposition wins, no extra nudge this time.
    if(shoveUid && flippingEls.has(shoveUid)) return;
    gsap.killTweensOf(target, 'x');
    if(shoveUid) shovedUids.add(shoveUid);
    gsap.timeline({
      onComplete: ()=>{ if(shoveUid) shovedUids.delete(shoveUid); },
    })
      .to(target, {x: dir*dist, duration:dur*0.42, ease:'power2.out'})
      .to(target, {x:0, duration:dur*0.7, ease:'back.out(2.4)', clearProps:'x'});
  };
  if(idx>0) shove(cards[idx-1], -1);
  if(idx>=0 && idx<cards.length-1) shove(cards[idx+1], 1);
}
// The ordinary landing impact for any freshly played/spawned card: a quick squash-thud on the
// card itself (see .landing-impact/.impact-burst in arena_template.html) plus the neighbor
// shove above. Distinct from the bee-drone flourish (playBeeSpawnLanding) and from the
// column-collapse dust puff (collapse-landed, a different moment — a card sliding INTO a hole,
// not a new card touching down).
function playLandingImpact(uid){
  const el = boardCardEl(uid); if(!el) return;
  el.classList.add('landing-impact');
  // 2026-09-17, per explicit request ("remove the fight explosion effect on SUMMON, it's out
  // of place — that kind of effect should trigger when a card GETS HIT instead"): the 💥 burst
  // that used to fire here on every single card landing (see hitExplosionVfx below for its new
  // home) is gone; the squash-thud + neighbor shove — the actual "landed with impact" feel —
  // stay exactly as they were.
  setTimeout(()=>{ el.classList.remove('landing-impact'); }, 300);
  pushNeighborCards(el, {distance:8, durationMs:220});
  waterRippleAt(el);
}
// 2026-09-21 ("The spawning of a card should look sexier"): a quick golden ring pulse + a couple
// of sparkle glyphs, layered on top of playLandingImpact's existing squash-thud, specifically for
// a card the PLAYER just dragged in from hand (isHandPlay in renderBoard's entrance tween) — kept
// off onAttackedSpawn/onDeathSpawn/triggerSpawn tokens, which already have their own distinct
// bee-landing/generic-impact flourishes and don't need a third competing effect layered on.
function playHandSummonGlow(uid){
  const el = boardCardEl(uid); if(!el) return;
  const ring = document.createElement('div');
  ring.className = 'fx-burst summon-glow-ring';
  el.appendChild(ring);
  setTimeout(()=> ring.remove(), 520);
  ['-16%','116%'].forEach((left, i)=>{
    const spark = document.createElement('div');
    spark.className = 'fx-burst summon-spark';
    spark.textContent = '✨';
    spark.style.left = left;
    spark.style.animationDelay = (i*40)+'ms';
    el.appendChild(spark);
    setTimeout(()=> spark.remove(), 560);
  });
}
// 2026-09-17, per explicit request (see playLandingImpact's own comment above): the 💥 burst
// moved from "a card gets summoned" to "a card gets hit" — and instead of always sitting
// dead-center, it lands at a randomized point over the card each time, so a flurry of hits
// (Sweep/Swipe chains, multiple attackers) doesn't read as the exact same burst repeating in
// the exact same spot. Deliberately its own function/element rather than reusing floatText —
// this is a one-shot decorative burst, not a piece of moving/readable text.
// Item #7 audit (2026-09-19, "the white overlay keeps getting repeatedly overlaid again and
// over again - can you check that there is no such loop happening... 1 white overlay object per
// card... No programmatic creation of html elements on top of the card"): ran a dedicated
// Playwright audit — 12+ back-to-back real combat rounds (3v3, every card ready to swing every
// round, the harshest case for any per-hit VFX) with the DOM sampled after each round for (a)
// duplicate same-class children under any .board-card and (b) every known transient VFX
// selector's count settling back to 0 well after its own timeout. Both came back clean every
// round — no duplicate/leaked elements anywhere (see /tmp/white_overlay_audit*.js in that
// session's scratch space). The card's own "white glint" is .card-tile::after, a single static
// CSS pseudo-element baked into the card's markup — never created/duplicated by JS — so there is
// no loop to find here. What likely read as "getting overlaid again and again" is that glint
// (::after) stacking visually with the top-light ring (::before) and the rarity-band scrim, all
// three genuinely separate, single, always-present layers rather than one accumulating bug; the
// item #8 gradient pass (weaker + shorter top/bottom fades) directly reduces how strong that
// stacked look reads.
// Elemental micro-bursts (2026-09-22, VFX direction: "elemental micro-bursts"): a hit whose
// dmgType is actually elemental (cold/heat/acid/poison — plain 'physical' stays the generic 💥)
// swaps in the matching glyph plus a colored glow (.fx-burst-<type> in arena_template.html)
// instead of the plain explosion, so different damage flavors read differently on landing, not
// just via dmgGlyph()'s existing use in ranged projectile trails.
// Decay (2026-09-29) added alongside the pre-existing four -- its own icon (🦠) reads distinctly
// from Poison's skull, since a Decay hit still deals normal HP damage on top of the ATK drain
// (Poison's conversion instead replaces the HP damage entirely) and the two should be tellable
// apart at a glance during a fight.
const ELEMENTAL_BURST_GLYPH = {cold:'❄', heat:'🔥', acid:'🧪', poison:'☠', decay:'🦠'};
function hitExplosionVfx(uid, dmgType){
  const el = boardCardEl(uid); if(!el) return;
  const burst = document.createElement('div');
  const elemGlyph = ELEMENTAL_BURST_GLYPH[dmgType];
  burst.className = 'fx-burst hit-burst' + (elemGlyph ? ` fx-burst-elemental fx-burst-${dmgType}` : '');
  burst.textContent = elemGlyph || '💥';
  // Kept away from the very edges (25%-75%) so the burst always reads as landing ON the card.
  burst.style.left = (25 + Math.random()*50).toFixed(1)+'%';
  burst.style.top = (25 + Math.random()*50).toFixed(1)+'%';
  el.appendChild(burst);
  setTimeout(()=> burst.remove(), 500);
}
// 2026-09-17 follow-up ("summoning large creatures (>20 def or >10 att) should have an
// earthquake effect"): a whole-battlefield shake, distinct from (and layered on top of) the
// per-card landing-impact/bee-landing flourishes above, which only ever move the landing card
// and its immediate neighbors. This shakes BOTH rows together via the shared .battlefield
// container so a big card landing on your side still visibly rattles the enemy's row too —
// it's a "the ground just shook" event, not a per-card one.
function playEarthquake(){
  const el = document.querySelector('.battlefield');
  if(!el) return;
  el.classList.remove('earthquake'); void el.offsetWidth; // restart if one is already mid-shake
  el.classList.add('earthquake');
  setTimeout(()=> el.classList.remove('earthquake'), 500);
}
// Task #126 (2026-09-17, "The spawning from getting hit (Bee Drone) should happen immediately
// and rebalance the positions. There should be a cute animation of the bee landing then pushing
// the cards!"): the onAttackedSpawn token gets its own bouncier, bee-themed touch-down — a
// bigger squash, a little bee glyph buzzing off, and a firmer shove of its new neighbors —
// instead of the plain landing-impact above, so a counter-spawn reads as its own distinct beat.
function playBeeSpawnLanding(uid){
  const el = boardCardEl(uid); if(!el) return;
  el.classList.add('bee-landing');
  const burst = document.createElement('div');
  burst.className = 'fx-burst bee-land-burst';
  burst.textContent = '🐝';
  el.appendChild(burst);
  setTimeout(()=>{ burst.remove(); el.classList.remove('bee-landing'); }, 560);
  pushNeighborCards(el, {distance:13, durationMs:260});
}
// Not scoped to `.hq-tile` — the player's own Castle now lives in the bottom UI as a
// separate widget (see renderMatchUI), so this just looks for whichever element carries
// data-hq="A"/"B", wherever it currently renders.
function hqTileEl(side){ return document.querySelector(`[data-hq="${side}"]`); }
function shakeEl(el){
  if(!el) return;
  // Cause G fix (see animateAttacker's own long comment for the full story): same guard — a
  // damaged card can be a live Flip target (mid-reflow) at the exact moment it gets hit, and
  // this shake tween shares `x` with Flip's own internal tween. Skip the GSAP shake (fall back
  // to the CSS-class shake, which at least doesn't reach into the SAME element Flip is actively
  // repositioning via inline transform) rather than risk corrupting the in-flight reposition.
  const uid = el.getAttribute && el.getAttribute('data-uid');
  const isFlipping = uid && flippingEls.has(uid);
  if(hasGsap() && !isFlipping){
    gsap.killTweensOf(el, 'x');
    const d = animMs().impactPad/1000/4;
    gsap.timeline()
      .to(el, {x:-6, duration:d, ease:'power1.inOut'})
      .to(el, {x:6, duration:d*1.6, ease:'power1.inOut'})
      .to(el, {x:-3, duration:d*1.2, ease:'power1.inOut'})
      .to(el, {x:0, duration:d, ease:'power1.inOut', clearProps:'x'});
  } else if(!hasGsap()){
    el.classList.add('shake');
    setTimeout(()=> el.classList.remove('shake'), 340);
  }
}
// Health feedback (2026-09-14): a quick red flash on an HQ/Castle whenever it takes damage.
function flashHqDamage(el){
  if(!el) return;
  el.classList.add('hq-hit-flash');
  setTimeout(()=> el.classList.remove('hq-hit-flash'), 420);
}
// 2026-09-19 ("then there needs to be a (larger) hit animation" for castle hits): a heavier,
// more consequential-feeling impact than the plain shakeEl+flashHqDamage combo every ordinary
// card-vs-card hit also gets — bigger shake amplitude (own GSAP tween, not the shared shakeEl
// helper, so the amplitude can genuinely differ), a bigger/longer flash (.hq-hit-flash-big,
// see arena_template.html), an explosion burst reusing hitExplosionVfx's 💥 pattern, and a full
// battlefield rumble via the existing playEarthquake() — the same "the ground just shook" cue
// big-creature summons already use — so a castle hit reads as the board-wide event it is.
function hqHitBigVfx(el){
  if(!el) return;
  if(hasGsap()){
    gsap.killTweensOf(el, 'x,scale');
    const d = animMs().impactPad/1000/4;
    gsap.timeline()
      .to(el, {x:-14, scale:1.05, duration:d, ease:'power1.inOut'})
      .to(el, {x:14, duration:d*1.6, ease:'power1.inOut'})
      .to(el, {x:-7, duration:d*1.2, ease:'power1.inOut'})
      .to(el, {x:0, scale:1, duration:d, ease:'power1.inOut', clearProps:'x,scale'});
  } else {
    el.classList.add('shake');
    setTimeout(()=> el.classList.remove('shake'), 340);
  }
  el.classList.remove('hq-hit-flash-big'); void el.offsetWidth;
  el.classList.add('hq-hit-flash-big');
  setTimeout(()=> el.classList.remove('hq-hit-flash-big'), 560);
  const burst = document.createElement('div');
  burst.className = 'fx-burst hit-burst hq-hit-burst';
  burst.textContent = '💥';
  el.appendChild(burst);
  setTimeout(()=> burst.remove(), 560);
  playEarthquake();
}
// "No" feedback (2026-09-17, per explicit request: "when trying to summon a card without
// sufficient resources, it shakes red" / "when trying to discard a card that doesn't give
// resources, it shakes red") — see playCardByUid/discardCardByUid for the two call sites.
// Deliberately its own class (.deny-shake) rather than reusing shakeEl's plain .shake, which
// already means "this card got hit" — a rejected action needs its own distinct read.
function denyShake(el){
  if(!el) return;
  el.classList.remove('deny-shake'); void el.offsetWidth; // restart if one is already mid-shake
  el.classList.add('deny-shake');
  setTimeout(()=> el.classList.remove('deny-shake'), 420);
  SoundKit.deny();
}
function floatText(el, text, cls){
  if(!el) return;
  const f = document.createElement('div');
  const heavyHit = /^-\d+$/.test(String(text)) && Math.abs(parseInt(text, 10)) >= 8 && !cls;
  f.className = 'dmg-float'+(cls?(' '+cls):'')+(heavyHit?' heavy':'');
  // 2026-10-06 (user: "for the poison and bleed hits, the icon should accompany it"): the icon is
  // its own element beside the number, so the number's gradient fill can't wash out the emoji.
  const raw = String(text);
  const icon = (raw.match(/[\p{Extended_Pictographic}\u2600-\u27BF\uFE0F\u200D]+/gu) || []).join('').replace(/\uFE0F/g, '');
  const num = raw.replace(/[\p{Extended_Pictographic}\u2600-\u27BF\uFE0F\u200D]+/gu, '').trim() || raw;
  f.innerHTML = (cls && /\bcrit\b/.test(cls) ? '<span class="df-burst" aria-hidden="true"></span>' : '') + (icon ? `<span class="df-ico">${icon}</span>` : '') + `<span class="df-num" data-t="${escapeAttr(num)}">${escapeHtml(num)}</span>`;
  f.dataset.t = raw;
  // Item #2 (2026-09-16, "damage text shouldn't just fly up, they should have some
  // amount of random x-force"): a little random horizontal drift baked in per-instance.
  // Floating-number coverage audit (2026-09-18, "with some variation in x and y so a burst of
  // simultaneous numbers doesn't stack unreadably on top of each other"): x already varied —
  // added a randomized starting Y offset plus a per-instance travel-distance jitter too, so
  // several floats landing on the same element in the same instant (Sweep's 2-3 simultaneous
  // hit numbers, several statusFx procs off one card in one round, a resource-pill ping that
  // lands right as a hit number is still rising) fan out instead of stacking in lockstep.
  const dx = Math.random()*24-12;
  const dy0 = Math.random()*10-5;
  const travel = 0.9 + Math.random()*0.2;
  el.appendChild(f);
  if(hasGsap()){
    // 2026-10-03 ("damage numbers sometimes seem duplicated — 2 numbers thrown up right after each
    // other"): the .dmg-float CSS bounce keyframes (up, down, UP AGAIN) kept running underneath
    // GSAP's tween and, being an animation, overrode it — that second hop read as a second number.
    // GSAP owns the motion now. Also (same report: castle numbers "too high up and not obvious"):
    // every float — unit or castle — now starts at the same spot INSIDE its target (28% down) at
    // the same size, so numbers are consistent and never pushed off the top of the screen.
    f.style.animation = 'none';
    gsap.set(f, {position:'absolute', left:'50%', top:`calc(40% + ${dy0.toFixed(1)}px)`, xPercent:-50, x:0, y:0, opacity:0, scale:.6});
    gsap.timeline({onComplete:()=> f.remove()})
      .to(f, {opacity:1, scale:1.1, y:-20*travel, x:dx*0.4, duration:.16, ease:'back.out(2.6)'})
      .to(f, {y:-46*travel, x:dx, duration:.55, ease:'power1.out'}, '<0.02')
      .to(f, {opacity:0, y:-58*travel, duration:.35, ease:'power1.in'}, '>-0.1');
  } else {
    f.style.top = (-6+dy0)+'px';
    f.style.setProperty('--dx', dx.toFixed(1)+'px');
    setTimeout(()=> f.remove(), 1150);
  }
}
// Item drop (item #3, 2026-09-16): when a kill pays out a resource (currently bounty gold),
// show something visibly falling out of the kill — heavier and more "gravitas" than the
// damage-text float above (a bigger, randomized side kick, a longer/steeper fall with a real
