    gsap.set(d, {position:'absolute', left:'50%', top:6, xPercent:-50, x:0, y:0, rotate:0, opacity:1});
    gsap.timeline({onComplete:()=> d.remove()})
      .to(d, {y:34, x:dx*0.5, rotate:rot*0.6, duration:.22, ease:'power1.out'})
      .to(d, {y:64, x:dx, rotate:rot, duration:.4, ease:'bounce.out'})
