        setTimeout(()=>{ try{ if(ev.type!=='evaded') SoundKit.arrowThunk(pa.fire); }catch(e){} }, arrowWind + arrowFlightMs());
        // 2026-10-06: the full bow choreography (draw, release + recoil, flight, impact) lives in
