/* ---- Login / entrance screen (2026-09-14, extended 2026-09-20 per explicit request: "Have a
   login page at the landing page. If already logged in, click start. After clicking start,
   bushes peel off, the background starts to move to reveal the next page 'underneath', fading
   off. The button is the last to fade off. And the logo fades off in a majestic way.")
   Two states inside the same overlay, swapped by renderEntranceAuth():
     - no saved profile yet -> a name field + "Enter the Grove" (login) button
     - a saved profile exists -> "Welcome back, X" + a "Start" button
   Only clicking Start (never the login button itself) plays the peel-off/fade sequence and
   reveals Home underneath — see the .leaving CSS in arena_template.html for the actual staged
   bush/background/text/button/logo animation this just toggles on. ---- */
function hasStoredCloudSession(){
  try{ return Object.keys(localStorage).some(k=> /^sb-.*-auth-token$/.test(k) && /"access_token"/.test(localStorage.getItem(k)||'') && !/"is_anonymous":true/.test(localStorage.getItem(k)||'')); }catch(e){ return false; }
}
// "Welcome back" only for someone who has actually played here before; a first-timer gets "Welcome!".
function hasPlayedBefore(){
  try{ return loadTutorialDone() || loadTutorialStage()>1 || !!localStorage.getItem('bramblewood_arena_stats') || !!localStorage.getItem(CONQUEST_PROGRESS_KEY); }catch(e){ return false; }
}
function renderEntranceAuth(){
  const el = document.getElementById('entranceAuthArea');
  if(!el) return;
  if(myProfile && myProfile.name){
    el.innerHTML = `<p class="entrance-welcome-back">${hasPlayedBefore() ? `Welcome back, <b>${escapeHtml(myProfile.name)}</b>` : `Welcome, <b>${escapeHtml(myProfile.name)}</b>!`} 🌰</p>
      <button class="btn primary big splash-enter" id="startBtn">▶ Start</button>
      <p class="entrance-account-line" id="entranceAccountLine" hidden></p>`;
    const btn = document.getElementById('startBtn');
    if(btn) btn.addEventListener('click', triggerEntranceAnimation);
  } else {
    el.innerHTML = `<form id="loginForm" class="entrance-login-form" autocomplete="off">
        <input id="loginNameInput" type="text" maxlength="24" placeholder="Choose a warband name…" autocomplete="off">
        <button type="submit" class="btn primary big splash-enter" id="loginSubmitBtn">🌿 Enter the Grove</button>
      </form>
      <button type="button" class="btn ghost small entrance-signin-btn" id="entranceSignInBtn">🔑 Sign in</button>
      <p class="entrance-account-line" id="entranceAccountLine" hidden></p>
      <p class="entrance-login-note">No account needed to play — Enter the Grove to jump straight in as a guest. Already have an account? Sign in above to sync progress, Online Raid, and Shop packs across devices.</p>`;
    const form = document.getElementById('loginForm');
    // Reliability hardening (2026-09-24, "im stuck. i cant enter." bug report): wrapped in
    // try/catch so a throw here (e.g. saveMyProfile or the re-render hitting something
    // unexpected) surfaces in the console instead of silently eating the click with no visible
    // effect — matches the reported symptom of the button appearing to do nothing.
    function handleLoginSubmit(e){
      if(e) e.preventDefault();
      try{
        const input = document.getElementById('loginNameInput');
        const raw = (input && input.value || '').trim().slice(0,24);
        saveMyProfile({name: raw || 'Woodland Warrior'});
        renderEntranceAuth(); // swap straight to the Start-button state — Start itself is a separate click
      }catch(err){
        console.error('[Bramblewood] loginForm submit failed:', err);
        // Best-effort recovery: still get the player past this screen rather than leaving them
        // stuck on a form that just swallowed their click.
        try{ saveMyProfile({name:'Woodland Warrior'}); }catch(e2){}
        try{ renderEntranceAuth(); }catch(e3){}
      }
    }
    if(form) form.addEventListener('submit', handleLoginSubmit);
    // Belt-and-suspenders: a plain click listener on the button itself, in addition to the
    // form's submit event. type="submit" inside a <form> should always fire 'submit' on click,
    // but this costs nothing and guards against any edge case (odd embedding context, a browser
    // quirk) where the submit event doesn't fire the way it does in every tested environment.
    const submitBtn = document.getElementById('loginSubmitBtn');
    if(submitBtn) submitBtn.addEventListener('click', e=>{
      // If the form's own submit handler already ran (the normal case), this is a harmless
      // no-op re-render. Guard with a flag on the element so a genuine double-fire (submit event
      // AND this click both landing) doesn't call it twice in the same tick.
      if(submitBtn._bwHandled) return;
      submitBtn._bwHandled = true;
      setTimeout(()=>{ submitBtn._bwHandled = false; }, 50);
      // Give the native submit event a chance to fire first; only act here if it didn't (the
      // form field would still be present and un-swapped if renderEntranceAuth() never ran).
      setTimeout(()=>{ if(document.getElementById('loginForm')) handleLoginSubmit(e); }, 0);
    });
    // Standard "primary action + secondary lower-emphasis action" pairing (2026-09-24, per
    // explicit request to add a sign-in option here): Enter the Grove is the primary, filled CTA
    // (this app's default, guest/local path — no account required); Sign In is the smaller ghost
    // button beneath it for the alternate path, reusing the SAME shared auth-gate modal every
    // other gated feature (Raid, Shop) already opens via requireSignIn — no new sign-in UI. Since
    // requireSignIn() no-ops straight to onSuccess when already signed in, this is safe to show
    // unconditionally rather than needing its own signed-in check.
    const signInBtn = document.getElementById('entranceSignInBtn');
    if(signInBtn) signInBtn.addEventListener('click', ()=> requireSignIn('to sync your progress', renderEntranceAuth));
  }
  refreshAccountUI();
}
function triggerEntranceAnimation(instant){
  const splashEl = document.getElementById('splashScreen');
  if(instant===true && splashEl){ splashEl.hidden = true; }
  const splash = instant===true ? null : splashEl;
  try{ sessionStorage.setItem('bramblewood_seen_splash', '1'); }catch(e){}
  // Reliability hardening (2026-09-24, "im stuck. i cant enter." bug report): everything below
  // this point touches a LOT of app state (switchTab('home') alone fans out into renderHome and
  // whatever that pulls in -- currencies, card levels, conquest progress, achievements, etc.).
  // Before this hardening, an uncaught exception ANYWHERE in that fan-out would halt this
  // function's execution outright -- since splash.classList.add('leaving') and the setTimeout
  // that hides the splash both came AFTER the switchTab('home') call, a throw there left the
  // splash permanently stuck on screen with no visible error and nothing in reach for the player
  // to do about it. That matches the reported symptom exactly (click does nothing, screen frozen)
  // and is a real gap regardless of what specifically throws. Two independent safety nets now
  // guarantee the player is never stuck on this screen again:
  //   1) the whole body runs inside try/catch, with the catch path forcing the splash away and
  //      still attempting to land the player on Home;
  //   2) a hard watchdog timer force-hides the splash a few seconds after click no matter what,
  //      even if some future bug throws from inside a setTimeout callback where try/catch here
  //      can't reach it.
  let watchdogFired = false;
  const watchdog = setTimeout(()=>{
    if(splash && !splash.hidden){
      watchdogFired = true;
      console.error('[Bramblewood] entrance watchdog: splash was still visible 4s after Enter the Grove was clicked — forcing it away.');
      splash.hidden = true; splash.classList.remove('leaving');
      try{ if(typeof currentTab==='undefined' || !currentTab) switchTab('home'); }catch(e2){ console.error('[Bramblewood] watchdog fallback switchTab(home) also failed:', e2); }
    }
  }, 4000);
  function clearWatchdog(){ clearTimeout(watchdog); }
  try{
    // Mandatory tutorial (2026-09-23, batch #28; extended into a 6-skirmish series batch #31): a
    // player who hasn't completed it yet gets either the Otters/Hummingbirds Faction Choice screen
    // (genuinely brand new -- no faction saved yet) or is dropped straight back into whichever
    // skirmish they left off on (faction already chosen, series still in progress) -- instead of
    // ever actually seeing Home. Splitting these two cases matters now that the tutorial is a
    // multi-fight series: previously a reload mid-tutorial was a non-issue (one fight, seconds
    // long), but re-showing the Faction Choice screen (and its 15s countdown) on every reload would
    // silently re-roll the player's faction and restart the whole series from skirmish 1 every time
    // they closed the tab. needsFactionPick / needsTutorialResume below are mutually exclusive.
    const needsFactionPick = !loadTutorialDone() && !loadFactionChoice() && !loadResumeSnapshot();
    const needsTutorialResume = !loadTutorialDone() && !!loadFactionChoice() && !loadResumeSnapshot();
    function enterTutorialFlow(){ try{ if(needsFactionPick) showFactionScreen(); else if(needsTutorialResume) beginTutorialStage(loadTutorialStage()); }catch(eTut){ console.error('[Bramblewood] enterTutorialFlow failed, falling back to Home:', eTut); try{ switchTab('home'); }catch(eHome){} } }
    if(!splash){ if(needsFactionPick || needsTutorialResume) enterTutorialFlow(); else if(!tryResumeAbandonedMatch()){ switchTab('home'); maybeRemindSignIn(); } clearWatchdog(); return; }
    // Render Home UNDERNEATH the still-visible overlay first, so the peel-off/fade genuinely
    // reveals a real page rather than a blank wrap for however long the animation takes.
    switchTab('home');
    splash.classList.add('leaving');
    // Matches the total staged duration of the .leaving CSS below (bushes/background first, then
    // text, then the button, then the logo's own longer "majestic" fade last of all).
    setTimeout(()=>{
      try{
        splash.hidden = true; splash.classList.remove('leaving');
        enterTutorialFlow();
        if(!needsFactionPick && !needsTutorialResume && !tryResumeAbandonedMatch()) maybeRemindSignIn();
      }catch(eInner){
        console.error('[Bramblewood] entrance animation callback failed:', eInner);
        splash.hidden = true; splash.classList.remove('leaving');
      }finally{
        clearWatchdog();
      }
    }, 2100);
  }catch(eOuter){
    // switchTab('home') (or anything else above) threw synchronously -- don't leave the splash
    // stuck. Force it away right now rather than waiting on the watchdog.
    console.error('[Bramblewood] triggerEntranceAnimation failed, forcing entry anyway:', eOuter);
    if(splash){ splash.hidden = true; splash.classList.remove('leaving'); }
    clearWatchdog();
    try{ switchTab('home'); }catch(eRetry){ console.error('[Bramblewood] fallback switchTab(home) also failed:', eRetry); }
  }
}
// Loading screen (2026-10-06, user: "add a loading screen to load the shaders in, at least 50%"):
// fonts, the shader programs and the first art load behind it. It lifts once the shaders are
// compiled and at least half of everything is in (the rest keeps loading in the background), or
// after 8 s whatever happens. Weights: shaders 40, fonts 10, art 50.
setTimeout(function runLoader(){ // after this script finishes, so every module-level const exists
  const el = document.getElementById('bwLoader'); if(!el) return;
  const fill = document.getElementById('bwLoaderFill'), stepEl = document.getElementById('bwLoaderStep');
  let pct = 0, shadersDone = false, closed = false;
  const add = (n, label)=>{ pct = Math.min(100, pct + n); if(fill) fill.style.width = pct.toFixed(0) + '%'; el.setAttribute('aria-valuenow', String(Math.round(pct))); if(label && stepEl) stepEl.textContent = label; maybeClose(); };
  const close = ()=>{ if(closed) return; closed = true; if(fill) fill.style.width = '100%'; el.classList.add('is-done'); setTimeout(()=> el.remove(), 500); };
  const t0 = performance.now();
  function maybeClose(){ if(shadersDone && pct >= 50) setTimeout(close, Math.max(180, 700 - (performance.now() - t0))); } // never a sub-second flash
  setTimeout(close, 8000);
  // fonts
  try{ (document.fonts && document.fonts.ready ? document.fonts.ready : Promise.resolve()).then(()=> add(10, 'Lettering the signposts…')); }catch(e){ add(10); }
  // shaders
  const shaderJob = (typeof shadersEnabled === 'function' && shadersEnabled() && ShaderM && ShaderM.precompile) ? ShaderM.precompile() : Promise.resolve(false);
  if(stepEl) stepEl.textContent = 'Lighting the lamps…';
  shaderJob.then(()=>{ shadersDone = true; add(40, 'Painting the cards…'); }).catch(()=>{ shadersDone = true; add(40); });
  // art: the splash, the map backgrounds and the first cards
  const urls = [];
  try{ const sp = splashArtURL(); if(sp && !/^data:/.test(sp)) urls.push(sp); }catch(e){}
  try{ [...document.styleSheets].forEach(sh=>{ let rules = []; try{ rules = sh.cssRules || []; }catch(e){} [...rules].forEach(r=>{ const t = r.cssText || ''; if(t.indexOf('--map-art:') < 0) return; const mm = t.match(/--map-art:\s*url\(["']?([^"')]+)["']?\)/); if(mm && !/^data:/.test(mm[1]) && !urls.includes(mm[1])) urls.push(mm[1]); }); }); }catch(e){}
  try{ Object.values(getCardDefs()).forEach(d=>{ if(d && d.art && !/^data:/.test(d.art) && urls.length < 40) urls.push(d.art); }); }catch(e){}
  const per = urls.length ? 50/urls.length : 50;
  if(!urls.length) add(50);
  urls.forEach(u=>{ const img = new Image(); let counted = false; const done = ()=>{ if(counted) return; counted = true; add(per); };
    img.onload = done; img.onerror = done; img.decoding = 'async'; img.src = u; setTimeout(done, 6000); });
}, 0);
(function initEntrance(){
  const splash = document.getElementById('splashScreen');
  if(!splash) return;
  let seen = false;
  try{ seen = sessionStorage.getItem('bramblewood_seen_splash')==='1'; }catch(e){}
  // A reload in the same tab skips the splash but is still a restart of the game — so it still
  // gets the once-per-load sign-in reminder (maybeRemindSignIn itself checks tutorial/sign-in).
  if(seen){ triggerEntranceAnimation(true); return; } // reload in the same tab: straight back in (tutorial / resume / Home)
  // 2026-10-03 ("Once signed in, skip past the front screen, just go straight in"): a returning
  // signed-in player (a saved Supabase session in this browser) never sees the splash at all.
  if(hasStoredCloudSession()){
    triggerEntranceAnimation(true);
    // The splash (where "Welcome back" lives) is skipped for signed-in players, so greet them on Home.
    if(hasPlayedBefore() && myProfile && myProfile.name) setTimeout(()=> showToast(`Welcome back, ${myProfile.name}! 🌰`), 600);
    return;
  }
  renderEntranceAuth();
})();

/* ---- Settings panel: music/SFX/voice volume sliders (Task list item 7, 2026-09-18, "Creating
   a settings menu... the sounds setting should be moved there. There should be volume sliders
   for 1) music 2) sound effect 3) voice effects.") — supersedes the old single mute toggle
   (Task #203). See arena/context-audio.md for the full system this wires into.
   2026-09-19 follow-up ("move the settings... beside the Quit button"): refactored from a
   one-shot IIFE into wireSettingsButton(idSuffix) so the SAME wiring logic can drive two
   independent instances — the topbar's original '' (wired once, below, at load) and the
   in-match HUD's 'Hud' (re-wired after every renderMatchUI/renderHUD, since the HUD row is
   rebuilt as an HTML string on nearly every action — see those functions' own calls to this).
   Two independent DOM instances rather than relocating one node, since relocating would need
   re-appending after every single HUD rebuild anyway and this is simpler and just as cheap. */
// Atmosphere packs (2026-10-03 — the "shaders keep Minecraft alive" idea, v0): a colour grade over
// the whole game plus a light/particle layer (dust motes, fireflies, rain, falling leaves). Purely
// cosmetic, per-device, off by default; reduced motion keeps the grade and drops the particles.
const ATMOSPHERES = [
  {id:'live', label:'🕰️ Live (your clock)'},
  {id:'off', label:'Off'}, {id:'golden', label:'🌅 Golden hour'}, {id:'moonlit', label:'🌙 Moonlit'},
  {id:'rain', label:'🌧️ Rain'}, {id:'autumn', label:'🍂 Autumn'},
];
const ATMO_KEY = 'bramblewood_atmosphere_v1';
// Immersion #5 (2026-10-05, "a living clock"): 'live' — the default for anyone who hasn't picked an
// atmosphere — follows the player's own local time: dawn 5–8, day 8–17, dusk 17–20, night 20–5.
function loadAtmosphere(){ try{ return localStorage.getItem(ATMO_KEY) || 'live'; }catch(e){ return 'live'; } }
function timeOfDay(d){ const h = (d || new Date()).getHours(); return h>=5 && h<8 ? 'dawn' : h>=8 && h<17 ? 'day' : h>=17 && h<20 ? 'dusk' : 'night'; }
function currentTimeOfDay(){ return document.body && document.body.dataset.tod || timeOfDay(); }
let liveClockTimer = null;
let atmoRaf = null;
function setAtmosphere(id){
  if(!ATMOSPHERES.some(a=> a.id===id)) id = 'off';
  try{ localStorage.setItem(ATMO_KEY, id); }catch(e){}
  document.body.dataset.atmo = id;
  // Live: tint by the clock, re-checked every 5 minutes; particles follow the phase.
  if(liveClockTimer){ clearInterval(liveClockTimer); liveClockTimer = null; }
  if(id==='live'){
    const tod = timeOfDay(); document.body.dataset.tod = tod;
    liveClockTimer = setInterval(()=>{ if(loadAtmosphere()==='live' && timeOfDay()!==document.body.dataset.tod) setAtmosphere('live'); }, 5*60*1000);
    try{ if(typeof Ambience!=='undefined') Ambience.setTimeOfDay(tod); }catch(e){}
  } else { delete document.body.dataset.tod; try{ if(typeof Ambience!=='undefined') Ambience.setTimeOfDay(null); }catch(e){} }
  const fx = id==='live' ? ({dawn:'golden', day:'off', dusk:'golden', night:'moonlit'})[document.body.dataset.tod] : id;
  let tint = document.getElementById('atmoTint'); if(!tint){ tint = document.createElement('div'); tint.id = 'atmoTint'; document.body.appendChild(tint); }
  let cv = document.getElementById('atmoCanvas'); if(!cv){ cv = document.createElement('canvas'); cv.id = 'atmoCanvas'; document.body.appendChild(cv); }
  if(atmoRaf){ cancelAnimationFrame(atmoRaf); atmoRaf = null; }
  const ctx = cv.getContext('2d'); ctx.clearRect(0,0,cv.width,cv.height);
  const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(fx==='off' || reduce){ cv.hidden = true; return; }
  cv.hidden = false;
  const fit = ()=>{ cv.width = innerWidth; cv.height = innerHeight; };
  fit(); window.addEventListener('resize', fit);
  const N = fx==='rain' ? 140 : fx==='autumn' ? 26 : (id==='live' ? 26 : 48);
  const rnd = Math.random;
  const ps = Array.from({length:N}, ()=> ({x: rnd()*innerWidth, y: rnd()*innerHeight, v: 0.3 + rnd(), p: rnd()*Math.PI*2, s: 1 + rnd()*2.5}));
  const leaves = ['🍂','🍁','🍃'];
  // Perf (2026-10-05, user: "the site is now running slowly when many cards are in view"): the
  // motes were a full-screen canvas redrawn every frame with a fresh radial gradient per particle,
  // on top of everything. Now: one pre-rendered sprite per colour, 30 fps, and paused during a
  // fight (the battlefield has its own weather) so it never competes with the cards.
  const sprite = (col)=>{ const c = document.createElement('canvas'); c.width = c.height = 32; const g = c.getContext('2d');
    const rg = g.createRadialGradient(16,16,0,16,16,16); rg.addColorStop(0, col); rg.addColorStop(1, 'rgba(255,255,255,0)'); g.fillStyle = rg; g.fillRect(0,0,32,32); return c; };
  const moteImg = sprite(fx==='moonlit' ? 'rgba(210,255,140,1)' : 'rgba(255,236,170,.85)');
  let lastDraw = 0, paused = false;
  const frame = t=>{
    if(document.body.dataset.atmo !== id) return;
    atmoRaf = requestAnimationFrame(frame);
    const inFight = typeof matchState !== 'undefined' && matchState && !matchState.over;
    if(inFight){ if(!paused){ ctx.clearRect(0,0,cv.width,cv.height); paused = true; document.body.classList.add('in-fight'); } return; }
    if(paused){ paused = false; document.body.classList.remove('in-fight'); }
    if(t - lastDraw < 32) return; lastDraw = t;
    ctx.clearRect(0,0,cv.width,cv.height);
    ps.forEach((q,i)=>{
      if(fx==='rain'){ q.y += 28*q.v; q.x -= 4*q.v; if(q.y > cv.height){ q.y = -20; q.x = rnd()*cv.width + 60; }
        ctx.strokeStyle = 'rgba(190,210,235,.35)'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(q.x, q.y); ctx.lineTo(q.x - 3, q.y + 14); ctx.stroke(); }
      else if(fx==='autumn'){ q.y += 1.4*q.v; q.x += Math.sin(t/900 + q.p)*1.6; if(q.y > cv.height+20){ q.y = -20; q.x = rnd()*cv.width; }
        ctx.save(); ctx.translate(q.x, q.y); ctx.rotate(Math.sin(t/700 + q.p)); ctx.globalAlpha = .75; ctx.font = (12 + q.s*4)+'px serif'; ctx.fillText(leaves[i%3], 0, 0); ctx.restore(); }
      else { // golden motes / moonlit fireflies
        q.y -= 0.3*q.v; q.x += Math.sin(t/1400 + q.p)*0.6; if(q.y < -10){ q.y = cv.height + 10; q.x = rnd()*cv.width; }
        const a = 0.35 + 0.35*Math.sin(t/(fx==='moonlit'?500:900) + q.p);
        const r = q.s*4; ctx.globalAlpha = Math.max(0, a); ctx.drawImage(moteImg, q.x - r, q.y - r, r*2, r*2); ctx.globalAlpha = 1; }
    });
  };
  atmoRaf = requestAnimationFrame(frame);
}
try{ if(loadAtmosphere()!=='off') setTimeout(()=> setAtmosphere(loadAtmosphere()), 400); }catch(e){}
// Admin/testing: ?tod=night (or dawn/day/dusk) previews a phase without waiting for the clock.
try{ const q = new URLSearchParams(location.search).get('tod'); if(q && /^(dawn|day|dusk|night)$/.test(q)) timeOfDay = ()=> q; }catch(e){}
// Shader layers (T7): real WebGL on the splash, the Home backdrop and the Conquest maps — see
// bramblewood-shaders.js. On by default where it can run; Settings → Shader effects turns it off.
const SHADER_KEY = 'bramblewood_shaders_v1';
const ShaderM = (typeof window!=='undefined' && window.BramblewoodShaders && window.BramblewoodShaders.mount) ? window.BramblewoodShaders : null;
function shadersEnabled(){
  if(!ShaderM || !ShaderM.isSupported()) return false;
  if(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return false;
  let v = null; try{ v = localStorage.getItem(SHADER_KEY); }catch(e){}
  if(v) return v === 'on';
  const lowPower = (navigator.hardwareConcurrency && navigator.hardwareConcurrency <= 2) || (navigator.deviceMemory && navigator.deviceMemory <= 2) || (navigator.connection && navigator.connection.saveData);
  return !lowPower;
}
const SPLASH_DEPTH_ART = (()=>{ const v = "__SPLASH_DEPTH__"; return v.indexOf('__SPLASH') === 0 ? '' : v; })(); // depth map for experiment #2 (tools/make_splash_depth.py)
function splashArtURL(){
  const v = getComputedStyle(document.documentElement).getPropertyValue('--splash-art').trim();
  const m = v.match(/^url\((['"]?)(.*)\1\)$/); return m ? m[2] : '';
}
function mountSceneShader(host, opts){
  if(!host || !shadersEnabled() || host.querySelector(':scope > .bw-shader')) return null;
  const img = splashArtURL(); if(!img || img.indexOf('__SPLASH') >= 0) return null;
  return ShaderM.mount(host, Object.assign({preset:'scene', image: img, prepend: true, depth: SPLASH_DEPTH_ART || null}, opts||{}));
}
function mountMapShader(host, mapId){
  if(!host || !shadersEnabled()) return null;
  const kind = ShaderM.MAP_KIND[mapId]; if(kind == null) return null;
  return ShaderM.mount(host, {preset:'map', kind, prepend: true, className: 'bw-shader-map'});
}
// Battlefield weather (2026-10-03, effects experiment #5): the map overlay system, placed under
// the cards and toned down. Rain on wet maps (and with the 🌧️ Rain atmosphere), the map's own look
// elsewhere. The canvas is moved into each re-rendered battlefield rather than recreated.
let battleWeather = null;
function battleWeatherKind(m){
  if(typeof loadAtmosphere==='function' && loadAtmosphere()==='rain') return 11;
  const override = loadBattlefieldBgOverride();
  const mapId = (override && override!=='auto' && override!=='calm') ? override : (m && m.conquestNode && m.conquestNode.mapId) || 'm1';
  if(mapId==='m2' || mapId==='m8') return 11;
  if(matchIsRainy(m)) return 11;
  const k = ShaderM.MAP_KIND[mapId]; return k == null ? 0 : k;
}
// Passing showers (2026-10-05, user: "introduce rain effect, sometimes happens on the first map"):
// about one Outskirts fight in three is fought in the rain — rolled once per fight, so a retry
// may come up dry. Rain brings its own ambience and the wet-ground look.
function matchIsRainy(m){
  if(!m) return false;
  if(m.rainy == null){
    const mapId = (m.conquestNode && m.conquestNode.mapId) || (m.mode==='conquest' ? 'm1' : null);
    m.rainy = mapId === 'm1' && Math.random() < 0.33;
  }
  return !!m.rainy;
}
// Storm lightning (2026-10-06, effects "Coming next"): on storm and rain battlefields a bolt lights
// the field now and then — a soft double flicker, a white point light high on the shader, and the
// thunder rolls in half a second later. Gentle on purpose (two flickers, low peak, none with
// reduced motion) so it never becomes a strobe.
var lightningTimer = null; // var: renderMatchUI can run (match resume) before this line executes
function scheduleLightning(m){
  clearTimeout(lightningTimer); lightningTimer = null;
  if(!m || m.over || m.testKit) return;
  const kind = battleWeatherKind(m); if(kind !== 10 && kind !== 11) return;
  const [lo, hi] = kind === 10 ? [9, 22] : [18, 40];
  lightningTimer = setTimeout(()=>{ lightningStrike(m); scheduleLightning(matchState); }, (lo + Math.random()*(hi-lo))*1000);
}
function lightningStrike(m){
  if(m !== matchState || !m || m.over || document.hidden) return;
  const bf = document.getElementById('battlefieldEl'); if(!bf) return;
  const reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(!reduce){
    const f = document.createElement('div'); f.className = 'bf-lightning'; f.setAttribute('aria-hidden','true');
    f.style.setProperty('--lx', (15 + Math.random()*70).toFixed(0) + '%');
    bf.appendChild(f); setTimeout(()=> f.remove(), 900);
  }
  try{ if(battleWeather && battleWeather.flash) battleWeather.flash(0.15 + Math.random()*0.7, 0.05, [0.85, 0.9, 1], reduce ? 0.35 : 0.8, 0.7, 700); }catch(e){}
  try{ Ambience.thunder(0.5 + Math.random()*0.6); }catch(e){}
}
function mountBattleWeather(m){
  const bf = document.getElementById('battlefieldEl');
  if(!bf || !m || !shadersEnabled() || m.testKit){ if(battleWeather){ battleWeather.destroy(); battleWeather = null; } return; }
  const kind = battleWeatherKind(m);
  const feltMode = bf.classList.contains('has-floor-art') ? 2 : 1;
  if(battleWeather && battleWeather.kindId===kind && battleWeather.feltMode===feltMode && ShaderM.reattach(battleWeather, bf, true)) return;
  if(battleWeather){ battleWeather.destroy(); battleWeather = null; }
  battleWeather = ShaderM.mount(bf, {preset:'map', kind, prepend:true, intensity:0.55, className:'bw-shader-battle', felt: bf.classList.contains('has-floor-art') ? 2 : 1, shadows:'.board-card .card-tile'});
  if(battleWeather){ battleWeather.kindId = kind; battleWeather.feltMode = feltMode; }
}
// Impact light (2026-10-05): a short point light on the battlefield felt where a hit lands,
// coloured by damage type. Castle hits flash bigger, at the board's edge nearest that castle.
const LIGHT_COLORS = {heat:[1, 0.55, 0.18], cold:[0.45, 0.75, 1], poison:[0.5, 1, 0.35], acid:[0.75, 1, 0.3], decay:[0.6, 0.45, 0.8], physical:[1, 0.88, 0.62]};
function battleLightAt(el, dmgType, big){
  if(!battleWeather || !battleWeather.flash || !el) return;
  const bf = document.getElementById('battlefieldEl'); if(!bf) return;
  const b = bf.getBoundingClientRect(), r = el.getBoundingClientRect();
  const x = Math.max(0, Math.min(1, (r.left + r.width/2 - b.left)/b.width));
  const y = Math.max(0, Math.min(1, (r.top + r.height/2 - b.top)/b.height));
  battleWeather.flash(x, y, LIGHT_COLORS[dmgType] || LIGHT_COLORS.physical, big ? 0.9 : 0.55, big ? 0.6 : 0.32, big ? 900 : 520);
  if(big && battleWeather.wave) battleWeather.wave(x, y, LIGHT_COLORS[dmgType] || LIGHT_COLORS.physical, 0.9, 760);
}
function mountEntranceShaders(){ document.querySelectorAll('.splash .entrance-bg').forEach(el=> mountSceneShader(el)); }
function setShadersEnabled(on){
  try{ localStorage.setItem(SHADER_KEY, on ? 'on' : 'off'); }catch(e){}
  if(!on){ if(ShaderM) ShaderM.destroyAll(); return; }
  mountEntranceShaders();
  try{ if(currentTab==='home') mountSceneShader(document.querySelector('#view-home .hs-back'), {scale: 0.5, intensity: 0.8});
       if(currentTab==='play' && playSubTab==='conquest' && !matchState && !conquestWorldView) mountMapShader(document.getElementById('conquestCanvas'), conquestSelectedMap); }catch(e){}
}
try{ setTimeout(mountEntranceShaders, 50); }catch(e){}
function wireSettingsButton(idSuffix){
  const btn = document.getElementById('settingsBtn'+idSuffix);
  const panel = document.getElementById('settingsPanel'+idSuffix);
  if(!btn || !panel) return;
  const sliders = {
    music: {el: document.getElementById('musicVolumeSlider'+idSuffix), val: document.getElementById('musicVolumeVal'+idSuffix), get: ()=>SoundKit.getMusicVolume(), set: v=>SoundKit.setMusicVolume(v)},
    sfx:   {el: document.getElementById('sfxVolumeSlider'+idSuffix),   val: document.getElementById('sfxVolumeVal'+idSuffix),   get: ()=>SoundKit.getSfxVolume(),   set: v=>SoundKit.setSfxVolume(v)},
    voice: {el: document.getElementById('voiceVolumeSlider'+idSuffix), val: document.getElementById('voiceVolumeVal'+idSuffix), get: ()=>SoundKit.getVoiceVolume(), set: v=>SoundKit.setVoiceVolume(v)},
  };
  Object.values(sliders).forEach(s=>{
    if(!s.el) return;
    const pct = Math.round(s.get()*100);
    s.el.value = String(pct);
    if(s.val) s.val.textContent = pct+'%';
    s.el.addEventListener('input', ()=>{
      const v = parseInt(s.el.value,10)/100;
      s.set(v);
      if(s.val) s.val.textContent = Math.round(v*100)+'%';
    });
  });
  // Battlefield background picker (2026-09-30, queued backlog item): options built fresh every
  // time a panel opens (cheap, and CONQUEST_MAPS never changes at runtime) rather than baked into
  // the static template markup, so the map list has exactly one source of truth. 'auto' preserves
  // today's per-Conquest-map theming; 'calm' is the new deliberately-plain option; any specific
  // map id forces that theme everywhere, Conquest or not (see battlefieldMapClass's own comment).
  const bfSelect = document.getElementById('battlefieldBgSelect'+idSuffix);
  if(bfSelect){
    const current = loadBattlefieldBgOverride();
    bfSelect.innerHTML = `<option value="auto">🗺️ Auto (by map)</option><option value="calm">🌿 Calm (minimal)</option>` +
      CONQUEST_MAPS.map(map=>`<option value="${map.id}">${map.icon} ${escapeAttr(map.name)}</option>`).join('');
    bfSelect.value = current;
    // A stored value from a map that no longer exists (shouldn't happen, but defensive) would
    // otherwise silently leave the <select> on its first option while the pill still applies a
    // now-orphaned class — fall back to 'auto' outright rather than let those two disagree.
    if(bfSelect.value !== current){ bfSelect.value = 'auto'; saveBattlefieldBgOverride('auto'); }
    bfSelect.addEventListener('change', ()=>{
      saveBattlefieldBgOverride(bfSelect.value);
      // Live-apply mid-match (no full re-render — that would disrupt whatever else is on screen)
      // by just swapping the one class battlefieldMapClass ever contributes to this element.
      const bfEl = document.getElementById('battlefieldEl');
      if(bfEl && matchState) bfEl.className = 'battlefield ' + battlefieldMapClass(matchState);
    });
  }
  const shSel = document.getElementById('shaderSelect'+idSuffix);
  if(shSel){
    const can = !!(ShaderM && ShaderM.isSupported());
    shSel.innerHTML = can ? `<option value="on">On</option><option value="off">Off</option>` : `<option value="off">Not supported on this device</option>`;
    shSel.disabled = !can; shSel.value = shadersEnabled() ? 'on' : 'off';
    shSel.addEventListener('change', ()=> setShadersEnabled(shSel.value === 'on'));
  }
  wireLanguageSelects();
  const atmo = document.getElementById('atmosphereSelect'+idSuffix);
  if(atmo){
    atmo.innerHTML = ATMOSPHERES.map(x=> `<option value="${x.id}">${x.label}</option>`).join('');
    atmo.value = loadAtmosphere();
    atmo.addEventListener('change', ()=> setAtmosphere(atmo.value));
  }
  const open = ()=>{
    panel.hidden = false;
    if(!idSuffix) renderSettingsLinks();
    if(atmo) atmo.value = loadAtmosphere();
    btn.classList.add('is-open');
    btn.setAttribute('aria-expanded','true');
  };
  const close = ()=>{
    panel.hidden = true;
    btn.classList.remove('is-open');
    btn.setAttribute('aria-expanded','false');
  };
  btn.addEventListener('click', (e)=>{
    e.stopPropagation();
    if(panel.hidden) open(); else close();
  });
  panel.addEventListener('click', e=> e.stopPropagation()); // clicking a slider shouldn't close the panel via the outside-click handler below
}
// Global outside-click/Escape closes WHICHEVER settings panel is currently open (topbar or HUD
// instance) — a single shared listener rather than one per instance, since the HUD instance's
// button/panel get re-wired (and their old listeners garbage-collected) on every render.
function closeAnyOpenSettingsPanel(){
  document.querySelectorAll('.settings-panel').forEach(p=>{
    if(p.hidden) return;
    p.hidden = true;
    const btn = document.getElementById(p.id.replace('settingsPanel','settingsBtn'));
    if(btn){ btn.classList.remove('is-open'); btn.setAttribute('aria-expanded','false'); }
  });
}
document.addEventListener('click', closeAnyOpenSettingsPanel);
document.addEventListener('keydown', e=>{ if(e.key==='Escape') closeAnyOpenSettingsPanel(); });
wireSettingsButton(''); // the topbar's own instance — wired once, here, at load

// Language button (2026-09-20, per explicit request: "Language button on the btm left too") —
// static markup outside #appWrap (see its own comment in arena_template.html for why), wired
// once here at load, same pattern as the topbar's settings instance just above. Deliberately
// honest about scope: there's no real i18n/translation layer in this app, so English is the
// only option that actually does anything when clicked — every other listed language is already
// rendered `disabled` in the markup with a "Soon" tag, so this function only needs to handle
// open/close, not a language-switch that would otherwise have nothing real to do.
function closeLanguagePanel(){
  const btn = document.getElementById('langBtn');
  const panel = document.getElementById('langPanel');
  if(!panel || panel.hidden) return;
  panel.hidden = true;
  if(btn){ btn.classList.remove('is-open'); btn.setAttribute('aria-expanded','false'); }
}
(function wireLanguageButton(){
  const btn = document.getElementById('langBtn');
  const panel = document.getElementById('langPanel');
  if(!btn || !panel) return;
  btn.addEventListener('click', (e)=>{
    e.stopPropagation();
    closeAnyOpenSettingsPanel(); // don't leave a Settings panel open behind this one
    if(panel.hidden){
      panel.hidden = false;
      btn.classList.add('is-open');
      btn.setAttribute('aria-expanded','true');
    } else {
      closeLanguagePanel();
    }
  });
  panel.addEventListener('click', e=> e.stopPropagation());
  // The active (English) option just closes the panel — it's already selected, there's nothing
  // to switch to. Every other option is `disabled` in the markup already, so no listener is
  // needed there at all; a disabled button fires no click.
  const activeOpt = panel.querySelector('.lang-option.is-active');
  if(activeOpt) activeOpt.addEventListener('click', closeLanguagePanel);
})();
document.addEventListener('click', closeLanguagePanel);
document.addEventListener('keydown', e=>{ if(e.key==='Escape') closeLanguagePanel(); });

// "Who goes first" field flash (2026-09-18) — called from renderVfxForEvent's 'roundStart'
// handler above. Flashes the row that resolves combat first this round with a brief red wash
// plus a small burst of autumn leaves popping out of THAT row specifically (fixed-positioned off
// its own getBoundingClientRect, not the ambient weather's whole-viewport random drift, since the
// two rows stack vertically — a screen-wide leaf fall wouldn't read as "this one" over the other).
function flagFirstFieldFlash(side){
  const rowEl = document.getElementById(side==='A' ? 'rowMine' : 'rowEnemy');
  if(!rowEl) return;
  rowEl.classList.remove('goes-first-flash'); void rowEl.offsetWidth; // restart if mid-flash already
  rowEl.classList.add('goes-first-flash');
  setTimeout(()=> rowEl.classList.remove('goes-first-flash'), 1100);
  const rect = rowEl.getBoundingClientRect();
  if(rect.width<=0 || rect.height<=0) return; // row not actually visible (e.g. off-tab) — flash class alone is harmless, skip the leaf spawn
  const LEAVES = ['🍁','🍂','🍃'];
  const layer = (window.autumnWeather && window.autumnWeather.layerFront) || document.body;
  const count = 6 + Math.floor(Math.random()*3);
  for(let i=0;i<count;i++){
    const leaf = document.createElement('span');
    leaf.className = 'field-first-leaf';
    leaf.textContent = LEAVES[Math.floor(Math.random()*LEAVES.length)];
    leaf.style.left = (rect.left + Math.random()*rect.width) + 'px';
    leaf.style.top = (rect.top + rect.height*0.3 + Math.random()*rect.height*0.4) + 'px';
    leaf.style.fontSize = (16 + Math.random()*10) + 'px';
    leaf.style.setProperty('--pop-x', (Math.random()*80-40).toFixed(0)+'px');
    leaf.style.setProperty('--pop-rot', (Math.random()*300-150).toFixed(0)+'deg');
    leaf.style.animationDelay = (Math.random()*0.15) + 's';
    layer.appendChild(leaf);
    setTimeout(()=> leaf.remove(), 1400);
  }
}
/* ---- Autumn Village Weather (2026-09-17, per explicit request: "Can we have patterns of
   autumn leaves floating in the air... These leaves come randomly. sometimes theyre out and
   about, at low counts, sometimes a gust of them blows by") ----
   A persistent, app-wide ambient decoration, separate from (and running alongside) the splash
   screen's own fixed 6-leaf loop. Two independent randomized schedulers, both running for as
   long as the tab stays open:
     - scheduleAmbient(): a single leaf every ~3.5-9s — "out and about, at low counts."
     - scheduleGust(): every ~25-55s, a burst of 10-18 leaves staggered over ~1.5s — "a gust of
       them blows by."
   Pure decoration: fixed position, no pointer events, appended once to a dedicated layer at
   the end of <body> so it never disturbs the app's own DOM structure. */
(function initAutumnWeather(){
  const LEAVES = ['🍁','🍂','🍃'];
  // 2026-09-17 follow-up ("some of the leaves should fly behind the board, and some behind the
  // buttons only — different layers"): three stacked layers instead of one. See each layer's
  // own #autumnWeatherLayer*/z-index comment in arena_template.html for the exact stacking
  // order — Back sits behind the battlefield/buttons entirely, Mid sits behind the buttons but
  // in front of the battlefield, Front (the original layer/id, untouched) sits in front of
  // everything, same as before this change.
  function ensureLayer(id){
    let el = document.getElementById(id);
    if(!el){
      el = document.createElement('div');
      el.id = id;
      el.setAttribute('aria-hidden', 'true');
      document.body.appendChild(el);
    }
    return el;
  }
  const layerBack = ensureLayer('autumnWeatherLayerBack');
  const layerMid = ensureLayer('autumnWeatherLayerMid');
  const layerFront = ensureLayer('autumnWeatherLayer'); // original id/behavior, kept as the "front" layer
  function pickLayer(){
    // 2026-09-26 (user report, screenshot: a leaf drifted directly over the in-match Quit
    // button, reading as "why can't I quit the fight"): layerFront is deliberately in front of
    // EVERYTHING, buttons included, which is fine ambiance most places but not acceptable over
    // the in-match HUD row — Quit chief among its controls — where a player needs total
    // confidence the button they see is clickable. Rather than lean on z-index alone (fragile
    // against future stacking-context changes), simply never hand out layerFront while a match
    // is on screen; the back/mid split still gives real depth variety, just without anything
    // ever drawing on top of the board's own controls.
    const appWrap = document.getElementById('appWrap');
    const inMatch = !!(appWrap && appWrap.classList.contains('in-match'));
    const r = Math.random();
    if(inMatch) return r<0.45 ? layerBack : layerMid;
    // Weighted so most leaves stay at the original "in front" depth (unchanged default feel),
    // with a meaningful minority visibly ducking behind the board or the buttons for real
    // depth variety, per the explicit ask.
    if(r<0.35) return layerBack;
    if(r<0.6) return layerMid;
    return layerFront;
  }
  function spawnLeaf(opts){
    opts = opts || {};
    const leaf = document.createElement('div');
    leaf.className = 'weather-leaf';
    leaf.textContent = LEAVES[Math.floor(Math.random()*LEAVES.length)];
    // Item #276 (2026-09-20, "Have a small chance (1%) that leaves blow with strong gusts
    // (strong y, also varies strongly). Some of these leaves can spawn midway on the left or
    // right border of the screen."): a rare single-leaf outlier, independent of the multi-leaf
    // scheduleGust() burst below — every ordinary spawn (ambient trickle OR a gust-burst leaf)
    // has a 1-in-100 chance of instead being one of these: much bigger horizontal drift/sway and
    // a much wider duration spread (reads as being blown hard and unevenly, not just a slightly
    // bigger version of a normal leaf), and half the time it starts already partway down the
    // screen right at the left/right edge instead of drifting in from the top like every other
    // leaf. opts.noStrongGust lets a caller opt a specific spawn out (not currently used, but
    // keeps this self-contained if a future caller needs a guaranteed-plain leaf).
    const isStrongGust = !opts.noStrongGust && Math.random() < 0.01;
    const edgeSpawn = isStrongGust && Math.random() < 0.5;
    let startLeft = Math.random()*100; // vw
    let startTop = null; // null = use the CSS default (-8vh, drifts in from above the screen)
    if(edgeSpawn){
      const fromLeftEdge = Math.random() < 0.5;
      startLeft = fromLeftEdge ? -4 : 104; // just off whichever screen edge
      startTop = 30 + Math.random()*40; // vh — "midway" down the screen, not from the top
    }
    const duration = opts.duration || (isStrongGust ? (3 + Math.random()*13) : (9 + Math.random()*7)); // seconds — a strong gust varies MUCH more (some very fast, some slow) than the steady ambient drift
    // 2026-09-17 follow-up ("have more left/right momentum"): both the overall left-right push
    // AND the side-to-side swing riding on top of it got a real increase, not just a tweak —
    // was +/-80px of straight-line drift and no independent sway at all (see the
    // weatherLeafFall keyframe comment in arena_template.html for how --leaf-sway is used).
    // Sway was tempered down from an initial 60-130px pass (see "too jerky" follow-up below)
    // once the smoother, decaying-amplitude keyframe curve was in — this range plus that curve
    // is what actually reads as a dampened swing rather than erratic jitter.
    const drift = (isStrongGust ? (Math.random()*1100-550) : (Math.random()*440-220)).toFixed(0); // px of net left/right travel by landing (was +/-80)
    const sway = (isStrongGust ? (80 + Math.random()*110) : (40 + Math.random()*55)).toFixed(0); // px of side-to-side swing amplitude layered on top
    const rot = (Math.random()*520-260).toFixed(0); // deg of total rotation over the fall
    const size = (14 + Math.random()*14).toFixed(0); // px
    const delay = opts.delay || 0;
    leaf.style.left = startLeft + 'vw';
    if(startTop!=null) leaf.style.top = startTop + 'vh';
    leaf.style.fontSize = size + 'px';
    leaf.style.animationDuration = duration + 's';
    leaf.style.animationDelay = delay + 's';
    leaf.style.setProperty('--leaf-drift', drift + 'px');
    leaf.style.setProperty('--leaf-sway', sway + 'px');
    leaf.style.setProperty('--leaf-rot', rot + 'deg');
    leaf.style.opacity = (0.45 + Math.random()*0.4).toFixed(2);
    if(isStrongGust) leaf.classList.add('weather-leaf-strong');
    (opts.layer || pickLayer()).appendChild(leaf);
    setTimeout(()=> leaf.remove(), (duration+delay)*1000 + 200);
  }
  // Item 3 (2026-09-17, "While not in the play menu. There should be less leaves."): the
  // battlefield/play tab is where the leaf weather is meant to set a scene behind live combat —
  // on every OTHER tab (codex, deck builder, conquest, sim) it was just as busy, which reads as
  // clutter rather than atmosphere when there's no board to frame. Rather than a hard on/off
  // (which would make the weather feel like it "breaks" when you leave play), ambient spawns get
  // much rarer and gusts drop to a small fraction of their normal leaf count off the play tab.
  function offPlayTab(){ return currentTab !== 'play'; }
  // Item #276 (2026-09-20, "The great fall of leaves should be 50% rarer"): both schedulers'
  // wait times are doubled from their previous ranges, which halves how often either an ambient
  // leaf or a full gust actually fires — the straightforward way to make an average-rate event
  // "50% rarer" is to double its average wait, not to touch how many leaves show up once it does
  // fire (that's the separate "more spread out" change just below).
  function scheduleAmbient(){
    const wait = (7000 + Math.random()*11000) * (offPlayTab() ? 3.5 : 1);
    setTimeout(()=>{ spawnLeaf(); scheduleAmbient(); }, wait);
  }
  function scheduleGust(){
    const wait = 50000 + Math.random()*60000;
    setTimeout(()=>{
      const count = offPlayTab() ? (2 + Math.floor(Math.random()*2)) : (10 + Math.floor(Math.random()*9));
      // Item #276 follow-up ("During the fall, the... time displacement of the leaves should be
      // significantly greater. With some leaves spawning in 0.6s after the first leaf falls."):
      // the per-leaf stagger inside one gust used to be a tight 0-1.5s spread (every leaf landed
      // within a second and a half of the first) — widened to 0-4s so a gust visibly trickles in
      // over several seconds rather than arriving as one clump, while still guaranteeing several
      // leaves land in that original ~0.6s window near the front of the burst.
      for(let i=0;i<count;i++) spawnLeaf({delay: Math.random()*4, duration: 4+Math.random()*6});
      scheduleGust();
    }, wait);
  }
  scheduleAmbient();
  scheduleGust();
  // Exposed for tests (and any future debug/settings hook) rather than kept purely internal.
  window.autumnWeather = { spawnLeaf, layerBack, layerMid, layerFront };
})();

/* ---- Star-fall reward animation (2026-09-18, Epic B, per explicit request: "On successfully
   leveling anything, 1–5 stars should fall from the ceiling like leaves, arriving at different
   times... and separately, stars should also visibly jump out of the card itself and then fall
   like leaves. This reuses the existing Autumn Village leaf-physics system...as the base for the
   star particles") ----
   Two distinct pieces, both fired together from starFallCelebration():
     - Ceiling stars: a LITERAL reuse of the leaf system above — same .weather-leaf fall
       keyframe/drift/sway/rotation math (spawnStar mirrors spawnLeaf almost line for line), just
       starred glyphs in their own glowing top-most layer, staggered via `delay` exactly like a
       leaf gust is.
     - Card-origin burst: a second, separate, shorter flourish anchored to the leveled card's
       live on-screen rect ("jump out of the card") — the leaf keyframe's vh-relative fall math
       only makes sense starting near the very top of the screen, so a mid-screen "pop out and
       drop" needs its own short keyframe (cardStarPopFall, see arena_template.html) rather than
       reusing weatherLeafFall's full 112vh travel from wherever the card happens to sit. */
(function initStarFall(){
  const STAR_GLYPHS = ['⭐','🌟','✨'];
  function ensureStarLayer(){
    let el = document.getElementById('starFallLayer');
    if(!el){ el = document.createElement('div'); el.id = 'starFallLayer'; el.setAttribute('aria-hidden','true'); document.body.appendChild(el); }
    return el;
  }
  function spawnStar(opts){
    opts = opts || {};
    const star = document.createElement('div');
    star.className = 'weather-leaf star-particle';
    star.textContent = STAR_GLYPHS[Math.floor(Math.random()*STAR_GLYPHS.length)];
    const startLeft = opts.left!=null ? opts.left : Math.random()*100;
    const duration = opts.duration || (2.6 + Math.random()*1.6);
    const drift = (Math.random()*320-160).toFixed(0);
    const sway = (30 + Math.random()*40).toFixed(0);
    const rot = (Math.random()*480-240).toFixed(0);
    const size = (16 + Math.random()*10).toFixed(0);
    const delay = opts.delay || 0;
    star.style.left = startLeft + 'vw';
    star.style.fontSize = size + 'px';
    star.style.animationDuration = duration + 's';
    star.style.animationDelay = delay + 's';
    star.style.setProperty('--leaf-drift', drift + 'px');
    star.style.setProperty('--leaf-sway', sway + 'px');
    star.style.setProperty('--leaf-rot', rot + 'deg');
    ensureStarLayer().appendChild(star);
    setTimeout(()=> star.remove(), (duration+delay)*1000 + 250);
  }
  function spawnCardStarPop(originRect, delayMs){
    const star = document.createElement('div');
    star.className = 'card-star-pop';
    star.textContent = STAR_GLYPHS[Math.floor(Math.random()*STAR_GLYPHS.length)];
    const cx = originRect.left + originRect.width*(0.25+Math.random()*0.5);
    const cy = originRect.top + originRect.height*(0.25+Math.random()*0.5);
    star.style.left = cx + 'px';
    star.style.top = cy + 'px';
    star.style.fontSize = (18+Math.random()*8).toFixed(0) + 'px';
    star.style.setProperty('--star-pop-dx', (Math.random()*160-80).toFixed(0)+'px');
    star.style.setProperty('--star-pop-rot', (Math.random()*360-180).toFixed(0)+'deg');
    star.style.setProperty('--star-pop-dur', (0.9+Math.random()*0.5).toFixed(2)+'s');
    setTimeout(()=>{
      ensureStarLayer().appendChild(star);
      setTimeout(()=> star.remove(), 1600);
    }, delayMs||0);
  }
  // Public entry point — `originEl` is the leveled card's live tile (or null, if none is on
  // screen right now, e.g. leveled from a list view that scrolled it out of sight); `count` is
  // how many stars to award (clamped 1-5 per the request; callers can pass a fixed number or
  // let it roll randomly).
  function starFallCelebration(originEl, count){
    count = Math.max(1, Math.min(5, count || (1+Math.floor(Math.random()*5))));
    for(let i=0;i<count;i++){
      spawnStar({delay: i*0.18 + Math.random()*0.15, duration: 2.4+Math.random()*1.6});
    }
    if(originEl){
      const rect = originEl.getBoundingClientRect();
      const burstCount = Math.min(count, 3);
      for(let i=0;i<burstCount;i++) spawnCardStarPop(rect, i*140);
    }
    SoundKit.gold(); // reuse the existing "cha-ching" cue for this reward moment
  }
  window.starFallVfx = { celebrate: starFallCelebration };
})();

/* ---- 3D card-flip reveal (Task list item 4, 2026-09-18: "do a card flip (X) animation. for
   revealing card rewards or something") ----
   A generic, reusable "flip this card over to reveal what's underneath" helper — not coupled to
   any one feature. Replaces `mountEl`'s content with a flip stage showing `frontHTML` face-up;
   calling the returned `.reveal()` performs the 3D rotate-on-the-vertical-axis flip over to
   `backHTML`, firing `onFlipped` right as the new face becomes visible (the halfway point of the
   rotation, not the end of it, so a caller can time a sound/VFX/text-swap to the actual moment
   the "old" face disappears and the "new" one appears, not after the whole tween settles).
   First wired up for the Forge's own level-up reveal (old stats card -> new stats card) below,
   since that's the one place the app already has a clean, ready-made "before"/"after" card face
   pair — see wireLevelUpFlip-equivalent code in renderForge's level-up click handler. */
function flipRevealCard(mountEl, opts){
  if(!mountEl) return null;
  opts = opts || {};
  const durationMs = opts.durationMs || 620;
  mountEl.innerHTML = `<div class="flip3d-stage">
      <div class="flip3d-inner" style="transition-duration:${durationMs}ms;">
        <div class="flip3d-face flip3d-front">${opts.frontHTML||''}</div>
        <div class="flip3d-face flip3d-back">${opts.backHTML||''}</div>
      </div>
    </div>`;
  const inner = mountEl.querySelector('.flip3d-inner');
  let revealed = false;
  return {
    reveal(){
      if(revealed || !inner) return; revealed = true;
      SoundKit.cardFlip();
      inner.classList.add('is-flipped');
      setTimeout(()=>{ if(opts.onFlipped) opts.onFlipped(); }, durationMs*0.5);
    },
  };
}

/* ---- Emoji firework burst (Task list item 6, 2026-09-18: "an animation function ready with
   parameter being emojis where when activated, it bursts out emojis of slightly varying sizes
   out like a firework, then they drop with gravity and slowly fade out... like a celebration
   effect when you click on a button... I haven't thought of where to use this") ----
   A ready-to-call, generic celebration burst — not wired to any specific button yet, exactly per
   the request. Call: emojiBurstVfx.burst(originEl, {emojis:['🎉','⭐'], count:14}). Reuses the
   same #starFallLayer overlay the star-fall celebration above already established (one shared
   fixed full-screen layer for every "stuff flies across the screen" effect, rather than each one
   creating its own), but with its own physics: particles launch outward from originEl in random
   directions/speeds (the "firework" burst), arc under a simple simulated gravity via a dedicated
   keyframe, then fade out right before removal — distinct from the star-fall's straight top-to-
   bottom leaf-drift path, which doesn't suit an outward burst. */
(function initEmojiBurst(){
  function ensureLayer(){
    let el = document.getElementById('starFallLayer');
    if(!el){ el = document.createElement('div'); el.id = 'starFallLayer'; el.setAttribute('aria-hidden','true'); document.body.appendChild(el); }
    return el;
  }
  function burst(originEl, opts){
    opts = opts || {};
    const emojis = (opts.emojis && opts.emojis.length) ? opts.emojis : ['🎉','✨','⭐'];
    const count = Math.max(1, Math.min(30, opts.count || 14));
    const rect = originEl && originEl.getBoundingClientRect
      ? originEl.getBoundingClientRect()
      : {left: window.innerWidth/2, top: window.innerHeight/2, width:0, height:0};
    const originX = rect.left + rect.width/2, originY = rect.top + rect.height/2;
    const layer = ensureLayer();
    for(let i=0;i<count;i++){
      const p = document.createElement('div');
      p.className = 'firework-particle';
      p.textContent = emojis[Math.floor(Math.random()*emojis.length)];
      // Launch angle spread across the full circle (a true "firework" burst, not just upward),
      // with speed/size/rotation/duration all randomized per-particle so a burst never looks
      // like a mechanically identical ring of copies.
      const angle = Math.random()*Math.PI*2;
      const speed = 60 + Math.random()*110;
      const dx = Math.cos(angle)*speed, dy = Math.sin(angle)*speed;
      const size = (14 + Math.random()*14).toFixed(0);
      const rot = (Math.random()*280-140).toFixed(0);
      const duration = (0.9 + Math.random()*0.6).toFixed(2);
      p.style.left = originX + 'px'; p.style.top = originY + 'px';
      p.style.fontSize = size + 'px';
      p.style.setProperty('--fw-dx', dx.toFixed(0)+'px');
      p.style.setProperty('--fw-dy', dy.toFixed(0)+'px');
      p.style.setProperty('--fw-rot', rot+'deg');
      p.style.animationDuration = duration+'s';
      layer.appendChild(p);
      setTimeout(()=> p.remove(), duration*1000 + 100);
    }
  }
  window.emojiBurstVfx = { burst };
})();

/* ---- Speech framework scaffold (Task list item 8, 2026-09-18: "Start to create a framework for
   'speech'. Sometimes in skirmishes, characters will talk during the game with speech bubbles
   while making a sfx from a set list, representing the character's voice.") ----
   Deliberately a SCAFFOLD, not a finished writing pass — see game-design-v30-addendum.md and
   arena/context-audio.md for why: real per-character personality needs the user's creative
   input, so this ships generic, all-ages battle-chatter lines any card can use, plus the plumbing
   (bubble UI, trigger hooks, a "voice" SFX blip) a future content pass drops real lines into.
   SPEECH_BANKS is the one place new lines get added later — nothing else in this file needs to
   change to extend the vocabulary. */
const SPEECH_BANKS = {
  onSummon: ["Let's go!", "I'm ready!", "Count me in!", "Here I come!", "Watch this!"],
  onAttack: ["Take this!", "Hyah!", "Got you!", "Right at you!", "Eat this!"],
  onDeath:  ["Ugh...", "Not like this...", "Tell my burrow...", "Well fought...", "Argh!"],
  // Castle speech (task #228, "Castle speech bubble presets... reusing the existing per-card
  // speech-bubble framework rather than a second system"): same deliberate scaffold choice as
  // the three banks above — generic, all-ages lines any Bramble/castle can use, not a specific
  // character voice (that still needs Jay's own creative input, same caveat as the original
  // scaffold comment above). Wired to two moments: the castle taking a hit, and the match
  // ending — see maybeSpeakHQ's call sites in renderVfxForEvent (hitHQ) and renderMatchUI
  // (the win/loss modal's one-shot celebration gate).
  castleOnHit: ["Hold the line!", "We're under attack!", "Shields up!", "That one stung!", "Steady, everyone!"],
  castleOnWin: ["Victory is ours!", "Well fought, all of you!", "The Bramble stands!", "We did it!", "Home safe, for now."],
  castleOnLoss: ["We'll rebuild...", "Not our day...", "Regroup — we try again.", "The Bramble falls...", "Next time. For sure."],
};
// Chosen not to fire on EVERY eligible event — real chatter is intermittent, not a caption track,
// and a card talking every single time it acts would get noisy/spammy fast in a busy round.
const SPEECH_CHANCE = 0.28;
// Per-uid cooldown (ms) so a card that both attacks and gets attacked in the same busy round
// doesn't stack two bubbles on top of each other mid-animation.
const SPEECH_COOLDOWN_MS = 2600;
const lastSpokeAt = new Map(); // uid -> timestamp, module-scoped so it survives across renders
function showSpeechBubble(el, text){
  if(!el) return;
  const b = document.createElement('div');
  b.className = 'speech-bubble';
  b.textContent = text;
  // Appended to <body> (not `el`) and positioned with fixed left/top computed from the card's
  // own getBoundingClientRect() — see the CSS comment on .speech-bubble. This is what lets the
  // bubble render above the map/field instead of getting clipped by .board-row's overflow-y.
  document.body.appendChild(b);
  const bubbleRect = b.getBoundingClientRect(); // real size even at opacity:0 (still laid out)
  // 2026-10-02 ("when scrolling up and down, the text gets left behind"): re-anchor to the card
  // every frame while the bubble is alive, so it follows scrolling (and a board re-render, which
  // swaps the card's element — re-found by its data-uid) instead of staying where it first appeared.
  const uid = el.getAttribute && el.getAttribute('data-uid');
  let anchor = el;
  const place = ()=>{
    if(!anchor.isConnected && uid){ const fresh = document.querySelector(`.board-card[data-uid="${uid}"]`); if(fresh) anchor = fresh; }
    if(!anchor.isConnected) return;
    const cardRect = anchor.getBoundingClientRect();
    b.style.left = (cardRect.left + cardRect.width/2 - bubbleRect.width/2) + 'px';
    b.style.top = (cardRect.top - bubbleRect.height - 6) + 'px';
  };
  place();
  const follow = ()=>{ if(!b.isConnected) return; place(); requestAnimationFrame(follow); };
  requestAnimationFrame(follow);
  if(hasGsap()){
    gsap.timeline({onComplete:()=> b.remove()})
      .to(b, {opacity:1, scale:1, y:0, duration:.22, ease:'back.out(2.2)'})
      .to(b, {opacity:1, duration:1.4}) // hold, readable
      .to(b, {opacity:0, y:-8, duration:.3, ease:'power1.in'});
  } else {
    b.style.opacity = '1'; b.style.transform = 'translateY(0) scale(1)';
    setTimeout(()=>{ b.style.opacity='0'; }, 1700);
    setTimeout(()=> b.remove(), 2050);
  }
}
// Bank name -> custom-speech trigger key (2026-09-29): the generic scaffold above predates the
// custom system and named its banks slightly differently ('onSummon' vs the custom system's
// 'onSpawn'); this is the one place that mapping lives, so the three original call sites below
// (onSummon/onAttack/onDeath) transparently pick up a card's own custom lines too, with zero
// changes needed at those call sites themselves.
const SPEECH_BANK_TO_CUSTOM_TRIGGER = {onSummon:'onSpawn', onAttack:'onAttack', onDeath:'onDeath'};
// Looks up defId's own custom speech lines for triggerKey (any of CUSTOM_SPEECH_TRIGGERS) and, if
// any slot is filled, rolls CUSTOM_SPEECH_CHANCE and returns one at random — or null if this card
// has nothing written for this trigger, or the roll missed. Kept separate from the generic
// SPEECH_BANKS roll (maybeSpeak below) since the two systems have independently-tunable odds.
function pickCustomSpeechLine(defId, triggerKey){
  if(defId==null || !triggerKey) return null;
  const def = getCardDefs()[defId];
  const slots = def && def.speeches && def.speeches[triggerKey];
  if(!Array.isArray(slots)) return null;
  const filled = slots.filter(s=> s && s.trim());
  if(!filled.length) return null;
  if(Math.random() > CUSTOM_SPEECH_CHANCE) return null;
  return filled[Math.floor(Math.random()*filled.length)];
}
// The one entry point every trigger site below calls. `uid` needs a live board-card element to
// anchor the bubble to (a dead/not-yet-rendered card silently no-ops, same pattern as floatText).
// `seed` drives voiceTone()'s pitch — passing the card's own uid means the SAME physical card
// instance sounds consistent for its own lifetime, without needing any real per-character audio.
// `customTriggerKey` (2026-09-29): explicit override for which CUSTOM_SPEECH_TRIGGERS key to check
// this card's own authored lines against — falls back to SPEECH_BANK_TO_CUSTOM_TRIGGER[bank] when
// omitted, so existing onSummon/onAttack/onDeath call sites need no changes. Passing `bank:null`
// (a brand-new trigger like 'onHit'/'onSkill' with no generic scaffold bank of its own) skips the
// generic fallback entirely — silence unless this specific card actually wrote a line for it.
function maybeSpeak(uid, bank, customTriggerKey){
  if(uid==null) return;
  const trigKey = customTriggerKey || SPEECH_BANK_TO_CUSTOM_TRIGGER[bank];
  const now = Date.now();
  const last = lastSpokeAt.get(String(uid))||0;
  if(now - last < SPEECH_COOLDOWN_MS) return;
  const c = typeof currentCardByUid==='function' ? currentCardByUid(uid) : null;
  // Custom line takes priority over the generic scaffold whenever this card actually wrote one
  // for this trigger — a player who took the time to author a line for their card wants to hear
  // it, not the generic placeholder chatter.
  const customLine = trigKey ? pickCustomSpeechLine(c && c.defId, trigKey) : null;
  let line = customLine;
  if(!line){
    if(!bank) return; // no generic bank for this trigger (e.g. On Hit/On Skill/Idle) -- custom-only
    const lines = SPEECH_BANKS[bank]; if(!lines || !lines.length) return;
    if(Math.random() > SPEECH_CHANCE) return;
    line = lines[Math.floor(Math.random()*lines.length)];
  }
  const el = boardCardEl(uid); if(!el) return;
  lastSpokeAt.set(String(uid), now);
  showSpeechBubble(el, line);
  SoundKit.voiceTone(Number(uid)||0);
}
// Castle/HQ mirror of maybeSpeak (task #228): anchors the bubble to the HQ tile (hqTileEl) instead
// of a board card, since the castle has no card uid of its own. Uses a synthetic 'hq-A'/'hq-B' key
// into the same lastSpokeAt map so its cooldown never collides with a real card's uid. `opts.force`
// skips both the intermittent SPEECH_CHANCE roll and the cooldown — used only for the one-shot
// win/loss line (a deliberate, always-plays moment, not ambient battle chatter like onHit is).
function maybeSpeakHQ(side, bank, opts){
  if(side!=='A' && side!=='B') return;
  const lines = SPEECH_BANKS[bank]; if(!lines || !lines.length) return;
  const force = !!(opts && opts.force);
  const key = 'hq-'+side;
  const now = Date.now();
  if(!force){
    const last = lastSpokeAt.get(key)||0;
    if(now - last < SPEECH_COOLDOWN_MS) return;
    if(Math.random() > SPEECH_CHANCE) return;
  }
  const el = hqTileEl(side); if(!el) return;
  lastSpokeAt.set(key, now);
  const line = lines[Math.floor(Math.random()*lines.length)];
  showSpeechBubble(el, line);
  SoundKit.voiceTone(side==='A' ? 1000 : 2000); // seeds distinct from any real card uid range
}

/* ---- Touch drag-and-drop shim (2026-09-18, Epic C — main-arena mobile pass, per the roadmap's
   own framing: "native HTML5 drag doesn't work on touch devices at all — this needs a
   pointer-events-based reimplementation, not just CSS") ----
   Rather than rewriting every one of this app's several drag-and-drop call sites (the
   battlefield row, the Left/Right/Discard drop zones, the deck-editor's pool->list drag, the
   Leader slot) to carry a second, parallel touch-specific code path, this listens globally for
   touch gestures on any [draggable="true"] element and REPLAYS the exact same sequence of real
   DragEvents (dragstart -> dragover, tracking the finger -> drop -> dragend) a mouse drag would
   fire, backed by a working DataTransfer stand-in so every existing
   `e.dataTransfer.getData('text/plain')` read downstream (and every dragover/dragleave
   highlight) keeps working completely unmodified on both desktop and touch. A small floating
   ghost copy of the dragged tile follows the finger so the gesture actually reads as a drag.
   A movement threshold (DRAG_THRESHOLD_PX) is the key safety valve: a plain tap that never
   moves far enough never fires any of this and falls through to the browser's own native click
   event exactly as before this shim existed — so it can never break the tap-to-arm/tap-to-add
   click-based flows that already make most of this app touch-usable without ANY dragging at
   all (playing a card via tap + the Left/Right/Discard buttons, adding/removing a deck-pool
   card via tap). This shim only ever matters for the handful of interactions that are
   drag-only today (dropping straight onto the battlefield row, deck-editor drag-to-add, and
   the Leader slot, which currently has no click alternative at all). */
(function initTouchDragShim(){
  const DRAG_THRESHOLD_PX = 10;
  let candidate = null;   // the [draggable] element touched, before the threshold is crossed
  let startX = 0, startY = 0;
  let dragEl = null, ghost = null, dt = null, lastTarget = null, dragActive = false;
  function makeDataTransfer(){
    const store = {};
    return { setData:(k,v)=>{ store[k]=String(v); }, getData:(k)=>store[k]||'', effectAllowed:'move', dropEffect:'move' };
  }
  function elementUnderGhost(x,y){
    if(ghost) ghost.style.display = 'none';
    const el = document.elementFromPoint(x,y);
    if(ghost) ghost.style.display = '';
    return el;
  }
  function fireDragEvent(type, el, touch, extra){
    if(!el) return;
    const ev = new Event(type, {bubbles:true, cancelable:true});
    ev.dataTransfer = dt;
    if(touch){ ev.clientX = touch.clientX; ev.clientY = touch.clientY; }
    if(extra) Object.assign(ev, extra);
    el.dispatchEvent(ev);
  }
  function beginDrag(touch){
    dragActive = true;
    dragEl = candidate;
    dt = makeDataTransfer();
    lastTarget = null;
    ghost = dragEl.cloneNode(true);
    ghost.style.cssText = `position:fixed; pointer-events:none; z-index:9999; opacity:.85; transform:translate(-50%,-50%) scale(1.05); left:${touch.clientX}px; top:${touch.clientY}px; width:${dragEl.offsetWidth}px; height:${dragEl.offsetHeight}px;`;
    document.body.appendChild(ghost);
    fireDragEvent('dragstart', dragEl, touch);
  }
  function endDrag(touch){
    if(dragActive){
      const target = elementUnderGhost(touch.clientX, touch.clientY);
      if(target) fireDragEvent('drop', target, touch);
      fireDragEvent('dragend', dragEl, touch);
    }
    if(ghost){ ghost.remove(); ghost = null; }
    candidate = null; dragEl = null; dt = null; lastTarget = null; dragActive = false;
  }
  document.addEventListener('touchstart', (e)=>{
    const t = e.target.closest('[draggable="true"]');
    if(!t || t.getAttribute('draggable')==='false') return;
    candidate = t;
    const touch = e.touches[0];
    startX = touch.clientX; startY = touch.clientY;
  }, {passive:true});
  document.addEventListener('touchmove', (e)=>{
    if(!candidate) return;
    const touch = e.touches[0];
    if(!dragActive){
      const dx = touch.clientX-startX, dy = touch.clientY-startY;
      if((dx*dx + dy*dy) < DRAG_THRESHOLD_PX*DRAG_THRESHOLD_PX) return; // still just a tap, let native click fire
      beginDrag(touch);
    }
    e.preventDefault(); // once an actual drag is underway, stop the page from scrolling under it
    if(ghost){ ghost.style.left = touch.clientX+'px'; ghost.style.top = touch.clientY+'px'; }
    const target = elementUnderGhost(touch.clientX, touch.clientY);
    if(target !== lastTarget){
      if(lastTarget) fireDragEvent('dragleave', lastTarget, touch, {relatedTarget:target});
      if(target) fireDragEvent('dragover', target, touch);
      lastTarget = target;
    } else if(target){
      fireDragEvent('dragover', target, touch);
    }
  }, {passive:false});
  document.addEventListener('touchend', (e)=>{ if(candidate) endDrag(e.changedTouches[0]); });
  document.addEventListener('touchcancel', (e)=>{ if(candidate) endDrag(e.changedTouches[0]); });
})();
